    assert_eq!(direct_discard.input_ranges, 2);
    assert_eq!(direct_discard.coalesced_ranges, 1);
    assert_eq!(direct_discard.physical_discard_ranges, 1);
    assert_eq!(direct_discard.physical_discard_bytes, 6);
    assert_eq!(direct_discard.invalidated_cache_entries, 1);
    assert_eq!(chunk.physical_discard_ranges(), 1);
    assert_eq!(chunk.physical_discard_bytes(), 6);
    let chunk_ready = chunk.storage_readiness(1, 1, 100);
