    assert_eq!(page_discard_page.chunk_id, Some(chunk_id.clone()));
    assert_eq!(
        page_discard_page.receipts[0].idempotency_key,
        "block-discard-a"
    );
    let expected_chunk_id = PageId {
        chunk_id: chunk_id.clone(),
        page_index: 0,
    };
