#[test]
fn replica_service_snapshot_chunks_restore_replacement_nodes() {
    let chunk_id = ChunkId::new(1, 99).unwrap();
    let chunk_a = PageId {
        chunk_id: chunk_id.clone(),
        page_index: 0,
    };
    let chunk_b = PageId {
        chunk_id,
        page_index: 1,
    };
    let mut source = MatrixReplicaService::new();
    source
        .write_chunk(chunk_a.clone(), 0, b"abcdefghijklmnop")
        .unwrap();
    source.write_chunk(chunk_b.clone(), 4, b"qrstuvwx").unwrap();
    source.discard_chunk(&chunk_a, 4, 4).unwrap();
    source
        .prewarm_chunk_ranges(
            &chunk_b,
            vec![DataRange {
                offset: 4,
                length: 4,
            }],
            0,
        )
        .unwrap();

    let mut assembler = ReplicaServiceSnapshotAssembler::default();
    let mut pages = Vec::new();
    let mut offset = 0;
    loop {
        let chunk = source.export_snapshot_chunk(offset, 64).unwrap();
        assert_eq!(chunk.offset, offset);
        let next_offset = offset.saturating_add(chunk.payload.len() as u64);
        assert_snapshot_progress(
            &chunk.install_progress(),
            !chunk.eof,
            next_offset,
            chunk.total_bytes,
            &chunk.full_checksum,
        );
        offset = next_offset;
        let eof = chunk.eof;
        pages.push(chunk);
        if eof {
            break;
        }
    }
    assert!(pages.len() > 1);
    let streamed_chunks = source.export_snapshot_chunks(64).unwrap();
    assert_eq!(streamed_chunks, pages);
    let mut callback_chunks = Vec::new();
    let export_progress = source
        .export_snapshot_chunk_stream(64, |chunk| {
            callback_chunks.push(chunk);
            Ok(())
        })
        .unwrap();
    assert_eq!(callback_chunks, pages);
    assert_snapshot_progress(
        &export_progress,
        false,
        pages.last().unwrap().total_bytes,
        pages.last().unwrap().total_bytes,
        &pages.last().unwrap().full_checksum,
    );
    assert!(matches!(
        ReplicaServiceSnapshotAssembler::default().push_chunk(pages[1].clone()),
        Err(ObjectError::InvalidArgument(_))
    ));
    let mut retry_assembler = ReplicaServiceSnapshotAssembler::default();
    assert!(retry_assembler
        .push_chunk(pages[0].clone())
        .unwrap()
        .is_none());
    let progress_after_first = retry_assembler.install_progress();
    assert!(retry_assembler
        .push_chunk(pages[0].clone())
        .unwrap()
        .is_none());
    assert_eq!(retry_assembler.install_progress(), progress_after_first);
    assert!(matches!(
        retry_assembler.abort_install(Some("wrong-stream")),
        Err(ObjectError::InvalidArgument(_))
    ));
    let abort_report = retry_assembler
        .abort_install(Some(&progress_after_first.stream_id))
        .unwrap();
    assert!(abort_report.aborted);
    assert!(abort_report.previous_stream_active);
    assert_eq!(
        abort_report.previous_next_offset,
        progress_after_first.next_offset
    );
    assert_eq!(
        abort_report.previous_remaining_bytes,
        progress_after_first.remaining_bytes
    );
    assert_eq!(
        abort_report.previous_stream_id,
        progress_after_first.stream_id
    );
    assert!(!abort_report.cleared_progress.stream_active);
    assert_eq!(abort_report.cleared_progress.next_offset, 0);
    assert!(retry_assembler
        .push_chunk(pages[0].clone())
        .unwrap()
        .is_none());
    let mut retry_mismatch = pages[0].clone();
    retry_mismatch.payload[0] ^= 0x7f;
    assert!(matches!(
        retry_assembler.push_chunk(retry_mismatch),
        Err(ObjectError::Corruption(_))
    ));
    let mut corrupt = pages[0].clone();
    corrupt.payload[0] ^= 0x01;
    assert!(matches!(
        ReplicaServiceSnapshotAssembler::default().push_chunk(corrupt),
        Err(ObjectError::Corruption(_))
    ));

    let mut assembled = None;
    for chunk in pages.clone() {
        let expected_next = chunk.offset.saturating_add(chunk.payload.len() as u64);
        let expected_total = chunk.total_bytes;
        let expected_full = chunk.full_checksum.clone();
        let eof = chunk.eof;
        assembled = assembler.push_chunk(chunk).unwrap();
        assert_snapshot_progress(
            &assembler.install_progress(),
            !eof,
            if eof { 0 } else { expected_next },
            if eof { 0 } else { expected_total },
            if eof { "" } else { &expected_full },
        );
    }
    let snapshot_bytes = assembled.expect("final chunk service snapshot");
    let snapshot = ReplicaServiceSnapshot::from_bytes(&snapshot_bytes).unwrap();
    assert_eq!(snapshot.pages.len(), 2);

    let mut replacement = MatrixReplicaService::new();
    replacement.install_snapshot_bytes(&snapshot_bytes).unwrap();
    let mut partial_replacement = MatrixReplicaService::new();
    let partial_progress = partial_replacement
        .install_snapshot_chunks(vec![pages[0].clone()])
        .unwrap();
    assert!(partial_progress.stream_active);
    assert_eq!(
        partial_replacement.snapshot_install_progress(),
        partial_progress
    );
    let resumed_progress = partial_replacement
        .install_snapshot_chunks(pages.iter().skip(1).cloned().collect::<Vec<_>>())
        .unwrap();
    assert_snapshot_progress(
        &resumed_progress,
        false,
        snapshot_bytes.len() as u64,
        snapshot_bytes.len() as u64,
        &etag(&snapshot_bytes),
    );
    assert!(
        !partial_replacement
            .snapshot_install_progress()
            .stream_active
    );
    assert_eq!(
        partial_replacement.read_chunk(&chunk_b, 4, 4).unwrap().data,
        b"qrst".to_vec()
    );
    let mut streamed_replacement = MatrixReplicaService::new();
    let install_progress = streamed_replacement
        .install_snapshot_chunks(pages.clone())
        .unwrap();
    assert_snapshot_progress(
        &install_progress,
        false,
        snapshot_bytes.len() as u64,
        snapshot_bytes.len() as u64,
        &etag(&snapshot_bytes),
    );
    assert_eq!(
        streamed_replacement
            .read_chunk(&chunk_b, 4, 4)
            .unwrap()
            .data,
        b"qrst".to_vec()
    );
    let state = replacement.read_chunk_state(&chunk_a).unwrap();
    assert_eq!(
        state.discarded_ranges,
        vec![DataRange {
            offset: 4,
            length: 4
        }]
    );
    assert!(matches!(
        replacement.read_chunk(&chunk_a, 4, 4),
        Err(ObjectError::Corruption(_))
    ));
    let restored = replacement.read_chunk(&chunk_b, 4, 4).unwrap();
    assert_eq!(restored.data, b"qrst".to_vec());
}

