    let mut read_fence_lag_meta =
        metaserver_placement_node("meta-read-lag", "rack-lag", true, true, "topology-lag", 9);
    read_fence_lag_meta
        .meta_health
        .control_proof
        .read_fence_covered = false;
    read_fence_lag_meta
        .meta_health
        .control_proof
        .read_fence_commit_lag = 3;
    read_fence_lag_meta
        .meta_health
        .control_proof
        .read_fence_read_index_lag = 2;
    read_fence_lag_meta
        .meta_health
        .control_proof
