#[test]
fn rust_distributed_readiness_fences_checksums() {
    let store = MatrixObjectStore::new(test_options()).unwrap();
    let readiness = store.distributed_readiness(0, 10, 0, 0, 1, 100, 0).unwrap();
    assert_eq!(
        readiness.distributed_readiness_checksum,
        readiness.control_checksum
    );
    assert_eq!(
        readiness
            .to_control_fields("")
            .get("distributed_readiness_checksum"),
        Some(&readiness.control_checksum)
    );
    assert_eq!(readiness.control_checksum_format, "MOSRSOBJECTREADY68");
    assert_eq!(
        readiness
            .to_control_fields("")
            .get("control_checksum_format"),
        Some(&readiness.control_checksum_format)
    );
    verify_objectstore_distributed_readiness_checksum(
        &readiness,
        Some(&readiness.control_checksum),
        Some(&readiness.control_checksum_format),
        Some(&readiness.distributed_readiness_checksum),
    )
    .unwrap();
    assert!(matches!(
        store.distributed_readiness_fenced(
            0,
            10,
            0,
            0,
            1,
            100,
            0,
            None,
            None,
            Some("fnv1a64:0000000000000000"),
        ),
        Err(ObjectError::PreconditionFailed(_))
    ));
}

#[test]
fn rust_control_plane_catalog_selection_is_metaserver_first() {
    let store = MatrixObjectStore::new(test_options()).unwrap();
    let embedded_default = store.select_catalog_endpoint(None, None).unwrap().unwrap();
    assert_eq!(embedded_default.catalog_source, "metaserver");
    assert_eq!(embedded_default.effective_mode, "metaserver");
    assert_eq!(
        embedded_default.catalog_endpoint,
        EMBEDDED_METASERVER_CATALOG_ENDPOINT
    );
    assert!(!embedded_default.placement_required);
    let embedded_default_set = store.select_catalog_endpoint_set(None, None).unwrap();
    assert_eq!(embedded_default_set.endpoint_count(), 1);
    assert_eq!(
        embedded_default_set
            .selected
            .as_ref()
            .unwrap()
            .catalog_endpoint,
        EMBEDDED_METASERVER_CATALOG_ENDPOINT
    );
    let selected = store
        .select_catalog_endpoint(Some("meta.local:9105"), Some("root.local:9100"))
        .unwrap()
        .unwrap();
    assert_eq!(selected.configured_mode, "auto");
    assert_eq!(selected.effective_mode, "metaserver");
    assert_eq!(selected.catalog_source, "metaserver");
    assert_eq!(selected.catalog_endpoint, "meta.local:9105");
    assert!(!selected.placement_required);
    assert_eq!(
        selected.catalog_route_checksum_format,
        CONTROL_PLANE_CATALOG_SELECTION_CHECKSUM_FORMAT
    );
    assert!(!selected.catalog_route_checksum.is_empty());
    selected
        .require_catalog_route_checksum(&selected.catalog_route_checksum)
        .unwrap();
    assert!(matches!(
        selected.require_catalog_route_checksum("stale-route-token"),
        Err(ObjectError::PreconditionFailed(_))
    ));
    let fields = selected.to_control_fields();
    assert_eq!(
        fields.get("effective_control_plane_mode").unwrap(),
        "metaserver"
    );
    assert_eq!(fields.get("catalog_source").unwrap(), "metaserver");
    assert_eq!(
        fields.get("catalog_route_checksum").unwrap(),
        &selected.catalog_route_checksum
    );

    let endpoint_set = store
        .select_catalog_endpoint_set(
            Some("meta-a.local:9105, meta-b.local:9105,meta-a.local:9105"),
            Some("root.local:9100"),
        )
        .unwrap();
    assert_eq!(endpoint_set.configured_mode, "auto");
    assert_eq!(endpoint_set.effective_mode, "metaserver");
    assert_eq!(endpoint_set.endpoint_count(), 2);
    assert_eq!(
        endpoint_set.catalog_route_checksum_format,
        CONTROL_PLANE_CATALOG_ENDPOINT_SET_CHECKSUM_FORMAT
    );
    assert!(!endpoint_set.catalog_route_checksum.is_empty());
    endpoint_set
        .require_catalog_route_checksum(&endpoint_set.catalog_route_checksum)
        .unwrap();
    assert!(matches!(
        endpoint_set.require_catalog_route_checksum("stale-route-set-token"),
        Err(ObjectError::PreconditionFailed(_))
    ));
    assert_eq!(
        endpoint_set.selected.as_ref().unwrap().catalog_endpoint,
        "meta-a.local:9105"
    );
    assert_eq!(
        endpoint_set.endpoints[1].catalog_endpoint,
        "meta-b.local:9105"
    );
    let endpoint_fields = endpoint_set.to_control_fields();
    assert_eq!(endpoint_fields.get("catalog_endpoint_count").unwrap(), "2");
    assert_eq!(
        endpoint_fields.get("catalog_route_checksum").unwrap(),
        &endpoint_set.catalog_route_checksum
    );
    assert_eq!(
        endpoint_fields.get("catalog_endpoint.1").unwrap(),
        "meta-b.local:9105"
    );
    let store_endpoint_set = store
        .select_catalog_endpoint_set(Some("meta-c.local:9105,meta-d.local:9105"), None)
        .unwrap();
    assert_eq!(store_endpoint_set.endpoint_count(), 2);
    assert_eq!(
        store_endpoint_set
            .selected
            .as_ref()
            .unwrap()
            .catalog_endpoint,
        "meta-c.local:9105"
    );

    let mut configured_meta_store = MatrixObjectStore::new(test_options()).unwrap();
    let configured_meta_set = configured_meta_store
        .configure_metaserver_catalog_endpoints(
            " meta-config-a.local:9105,meta-config-b.local:9105,meta-config-a.local:9105 ",
        )
        .unwrap();
    assert_eq!(
        configured_meta_store.configured_metaserver_catalog_endpoints(),
        Some("meta-config-a.local:9105,meta-config-b.local:9105")
    );
    assert_eq!(configured_meta_set.endpoint_count(), 2);
    assert_eq!(
        configured_meta_set
            .selected
            .as_ref()
            .unwrap()
            .catalog_endpoint,
        "meta-config-a.local:9105"
    );
    assert_eq!(configured_meta_set.effective_mode, "metaserver");
    assert!(!configured_meta_set.placement_required);
    let configured_meta_selected = configured_meta_store
        .select_catalog_endpoint(None, Some("root-config.local:9100"))
        .unwrap()
        .unwrap();
    assert_eq!(configured_meta_selected.catalog_source, "metaserver");
    assert_eq!(
        configured_meta_selected.catalog_endpoint,
        "meta-config-a.local:9105"
    );
    let configured_meta_mode = configured_meta_store
        .configure_control_plane_mode("metaserver", None, None)
        .unwrap();
    assert_eq!(configured_meta_mode.endpoint_count(), 2);
    let configured_meta_status = configured_meta_store
        .module_status(0, 10, 0, 0, 2, 100, 0)
        .unwrap();
    assert_eq!(configured_meta_status.control_plane_mode, "metaserver");
    assert_eq!(configured_meta_status.catalog_source, "metaserver");
    assert_eq!(
        configured_meta_status.catalog_endpoint,
        "meta-config-a.local:9105"
    );
    assert!(configured_meta_status.metaserver_catalog_endpoint_configured);
    assert!(!configured_meta_status.rootserver_catalog_endpoint_configured);
    assert!(!configured_meta_status.catalog_route_checksum.is_empty());
    assert!(matches!(
        configured_meta_store.configure_metaserver_catalog_endpoints("   "),
        Err(ObjectError::InvalidArgument(_))
    ));
    assert!(matches!(
        configured_meta_store.configure_metaserver_catalog_endpoints("meta-a.local:9105,"),
        Err(ObjectError::InvalidArgument(_))
    ));

    let root_only_auto = store
        .select_catalog_endpoint(None, Some("root.local:9100"))
        .unwrap()
        .unwrap();
    assert_eq!(root_only_auto.catalog_source, "metaserver");
    assert_eq!(
        root_only_auto.catalog_endpoint,
        EMBEDDED_METASERVER_CATALOG_ENDPOINT
    );
    assert_eq!(root_only_auto.effective_mode, "metaserver");
    assert!(!root_only_auto.placement_required);
    let root_only_auto_set = store
        .select_catalog_endpoint_set(None, Some("root.local:9100"))
        .unwrap();
    assert_eq!(root_only_auto_set.endpoint_count(), 1);
    assert_eq!(
        root_only_auto_set.selected.as_ref().unwrap().catalog_source,
        "metaserver"
    );
    assert_eq!(root_only_auto_set.effective_mode, "metaserver");
    assert!(!root_only_auto_set.placement_required);

    // A ROOT CATALOG ENDPOINT IS REFUSED, not stored and ignored, because nothing reads
    // one: the control plane is the metaserver. This is also the journal-replay path, which
    // reaches the same function.
    let mut configured_store = MatrixObjectStore::new(test_options()).unwrap();
    for endpoint in [" root-config.local:9100 ", "root.local:9100", "   ", ""] {
        match configured_store.configure_placement_fallback_endpoint(endpoint) {
            Err(ObjectError::InvalidArgument(_)) => {}
            other => panic!("{endpoint:?} should be refused, and it gave {other:?}"),
        }
    }
    assert_eq!(
        configured_store.configured_placement_fallback_endpoint(),
        None,
        "a refused endpoint must not have been stored"
    );
    let configured_root_status = configured_store
        .module_status(0, 10, 0, 0, 2, 100, 0)
        .unwrap();
    assert_eq!(configured_root_status.control_plane_mode, "metaserver");
    assert_eq!(configured_root_status.catalog_source, "metaserver");
    assert_eq!(
        configured_root_status.catalog_endpoint,
        EMBEDDED_METASERVER_CATALOG_ENDPOINT
    );
    assert!(!configured_root_status.rootserver_catalog_endpoint_configured);
    assert!(!configured_root_status.placement_required);
    // And a store cannot be built with one either.
    let mut rejected_options = test_options();
    rejected_options.rootserver_catalog_endpoint = "root.local:9100".to_string();
    assert!(matches!(
        MatrixObjectStore::new(rejected_options),
        Err(ObjectError::InvalidArgument(_))
    ));

    // THE RETIRED MODES are refused BY NAME rather than falling into the catch-all, so the
    // error says what happened to them instead of only what is allowed.
    for retired in ["globalcatalog", "global-catalog", "catalog", "rootserver", "root"] {
        match ControlPlaneMode::parse(retired) {
            Err(ObjectError::InvalidArgument(message)) => assert!(
                message.contains("retired"),
                "{retired:?} should be refused as retired, and the message is {message:?}"
            ),
            other => panic!("{retired:?} should be refused, and it gave {other:?}"),
        }
    }
    // The surviving modes keep their durable codes: a snapshot written before this change
    // names auto 0 and metaserver 1, and those must not move.
    assert_eq!(ControlPlaneMode::Auto.snapshot_code(), 0);
    assert_eq!(ControlPlaneMode::MetaServer.snapshot_code(), 1);
    // A ROOTSERVER-MODE SNAPSHOT WITH NO ENDPOINT WAS A METASERVER -- it selected the
    // embedded metaserver catalog -- so it loads as one rather than being refused.
    for empty in ["", "   "] {
        assert_eq!(
            ControlPlaneMode::from_snapshot_code_with_endpoint(3, empty).unwrap(),
            ControlPlaneMode::MetaServer,
            "code 3 with no endpoint was already a metaserver"
        );
    }
    // With an endpoint it was pointed at a catalog this build cannot reach, and
    // globalcatalog always required one. Refused rather than silently repointed.
    assert!(matches!(
        ControlPlaneMode::from_snapshot_code_with_endpoint(3, "root.local:9100"),
        Err(ObjectError::InvalidArgument(_))
    ));
    assert!(matches!(
        ControlPlaneMode::from_snapshot_code_with_endpoint(2, ""),
        Err(ObjectError::InvalidArgument(_))
    ));
    assert!(matches!(
        ControlPlaneMode::from_snapshot_code_with_endpoint(4, ""),
        Err(ObjectError::Corruption(_))
    ));

    let mut meta_options = test_options();
    meta_options.control_plane_mode = ControlPlaneMode::MetaServer;
    let meta_store = MatrixObjectStore::new(meta_options).unwrap();
    let embedded_meta_selection = meta_store
        .select_catalog_endpoint(None, Some("root.local:9100"))
        .unwrap()
        .unwrap();
    assert_eq!(embedded_meta_selection.catalog_source, "metaserver");
    assert_eq!(
        embedded_meta_selection.catalog_endpoint,
        EMBEDDED_METASERVER_CATALOG_ENDPOINT
    );
    assert!(!embedded_meta_selection.placement_required);
    let embedded_meta_endpoint_set = meta_store
        .select_catalog_endpoint_set(None, Some("root.local:9100"))
        .unwrap();
    assert_eq!(embedded_meta_endpoint_set.endpoint_count(), 1);
    assert_eq!(
        embedded_meta_endpoint_set
            .selected
            .as_ref()
            .unwrap()
            .catalog_endpoint,
        EMBEDDED_METASERVER_CATALOG_ENDPOINT
    );
    assert!(matches!(
        store.select_catalog_endpoint_set(Some("meta-a.local:9105,"), None),
        Err(ObjectError::InvalidArgument(_))
    ));

    let mut registration_store = MatrixObjectStore::new(test_options()).unwrap();
    let objectstore_registration = registration_store
        .register_local_objectstore_gateway_in_catalog(
            "objectstore-a",
            "objectstore-a.local:9200",
            "rack-a",
            1024,
            128,
            false,
            10,
            "metaserver",
        )
        .unwrap();
    let objectstore_fields = objectstore_registration.to_control_fields();
    assert_eq!(
        objectstore_fields.get("service_kind").unwrap(),
        "objectstore"
    );
    assert_eq!(
        objectstore_fields.get("catalog_endpoint").unwrap(),
        "embedded-metaserver-catalog"
    );
    assert_eq!(
        objectstore_fields.get("catalog_endpoint_count").unwrap(),
        "1"
    );

    let page_registration = registration_store
        .register_local_pageserver_in_catalog(
            "block-a",
            "block-a.local:9300",
            "rack-a",
            0,
            2,
            0,
            0,
            10,
            "metaserver",
        )
        .unwrap();
    let page_fields = page_registration.to_control_fields();
    assert_eq!(page_fields.get("service_kind").unwrap(), "chunkserver");
    assert_eq!(page_fields.get("allocator_shard_index").unwrap(), "0");
    assert_eq!(page_fields.get("allocator_shard_count").unwrap(), "2");
    assert_eq!(
        page_fields.get("catalog_endpoint").unwrap(),
        "embedded-root-catalog"
    );

    let chunk_registration = registration_store
        .register_local_chunkserver_in_catalog(
            "chunk-reg-a",
            "chunk-reg-a.local:9400",
            "rack-a",
            0,
            0,
            0,
            10,
            "metaserver",
        )
        .unwrap();
    let chunk_fields = chunk_registration.to_control_fields();
    assert_eq!(chunk_fields.get("service_kind").unwrap(), "chunkserver");
    assert_eq!(
        chunk_fields.get("catalog_endpoint").unwrap(),
        "embedded-root-catalog"
    );
    assert_eq!(chunk_fields.get("catalog_endpoint_count").unwrap(), "1");

    let objectstore_offline = registration_store
        .offline_local_objectstore_gateway_in_catalog("objectstore-a", 20, "metaserver")
        .unwrap();
    assert!(!objectstore_offline.node.online);
    assert!(objectstore_offline.node.draining);
    let objectstore_offline_fields = objectstore_offline.to_control_fields();
    assert_eq!(objectstore_offline_fields.get("online").unwrap(), "false");
    assert_eq!(objectstore_offline_fields.get("draining").unwrap(), "true");
    assert_eq!(
        objectstore_offline_fields.get("catalog_endpoint").unwrap(),
        "embedded-metaserver-catalog"
    );

    let page_offline = registration_store
        .offline_local_pageserver_in_catalog("block-a", 0, 2, 0, 0, 30, "metaserver")
        .unwrap();
    assert!(!page_offline.node.online);
    assert!(page_offline.node.draining);
    assert!(!page_offline.node.page_health.ready);
    assert!(!page_offline.node.page_health.read_ready);
    let page_offline_fields = page_offline.to_control_fields();
    assert_eq!(page_offline_fields.get("online").unwrap(), "false");
    assert_eq!(
        page_offline_fields.get("allocator_shard_count").unwrap(),
        "2"
    );

    let chunk_offline = registration_store
        .offline_local_chunkserver_in_catalog("chunk-reg-a", 0, 0, 0, 40, "metaserver")
        .unwrap();
    assert!(!chunk_offline.node.online);
    assert!(chunk_offline.node.draining);
    assert!(!chunk_offline.node.chunk_health.accepting_writes);
    assert!(!chunk_offline.node.chunk_health.raft_writable);
    assert_eq!(chunk_offline.node.chunk_health.service_mode, "offline");
    let chunk_offline_fields = chunk_offline.to_control_fields();
    assert_eq!(chunk_offline_fields.get("online").unwrap(), "false");
    assert_eq!(chunk_offline_fields.get("draining").unwrap(), "true");
}

#[test]
fn object_store_rebalances_capacity_pressure_with_object_report() {
    let mut store = MatrixObjectStore::new(test_options()).unwrap();
    for (node_id, domain, capacity) in [("chunk-a", "rack-a", 64), ("chunk-b", "rack-b", 64)] {
        store
            .register_placement_node(placement_node(node_id, domain, capacity))
            .unwrap();
    }
    let (metadata, before) = store
        .put_object_with_root_placement(
            "bucket",
            "rebalance",
            vec![b'r'; 32],
            "application/octet-stream",
            2,
            PutOptions::default(),
        )
        .unwrap();
    assert_eq!(
        before.node_ids,
        vec!["chunk-a".to_string(), "chunk-b".to_string()]
    );
    for (node_id, domain, capacity) in [("chunk-c", "rack-c", 128), ("chunk-d", "rack-d", 128)] {
        store
            .register_placement_node(placement_node(node_id, domain, capacity))
            .unwrap();
    }

    let plan = store.plan_object_capacity_rebalance(1, 40, None);
    assert_eq!(plan.checked_objects, 1);
    assert_eq!(plan.pressure_node_count, 2);
    assert_eq!(plan.rebalance_objects, 1);
    assert_eq!(plan.bytes_to_rebalance, 32);
    assert_eq!(plan.items[0].object.object_id, metadata.object_id);
    assert_eq!(plan.items[0].pressure_node_id, "chunk-a");
    assert_eq!(plan.items[0].plan.target_node_id, "chunk-c");
    assert!(plan.rebalance_needed);
    assert!(plan.rebalance_can_apply);
    assert_eq!(plan.rebalance_reason, "object_capacity_rebalance_ready");

    let unbounded_plan = store.plan_object_capacity_rebalance(0, 40, None);
    assert!(unbounded_plan.rebalance_can_apply);
    assert_eq!(
        unbounded_plan.rebalance_reason,
        "object_capacity_rebalance_ready"
    );

    let run = store.rebalance_object_capacity(0, 40, None);
    assert_eq!(run.plan.rebalance_objects, 1);
    assert_eq!(run.attempted_migration_objects, 1);
    assert_eq!(run.migrated_objects, 1);
    assert_eq!(run.failed_migration_objects, 0);
    assert_eq!(run.bytes_migrated, 32);
    let after = store.object_placement("bucket", "rebalance").unwrap();
    assert_eq!(
        after.node_ids,
        vec!["chunk-c".to_string(), "chunk-b".to_string()]
    );
    assert_eq!(run.migrated[0].node_ids, after.node_ids);
}

#[test]
fn multipart_upload_completes_large_object_and_survives_snapshot() {
    let mut store = MatrixObjectStore::new(test_options()).unwrap();
    let upload = store
        .create_multipart_upload(
            "bucket",
            "large",
            "application/octet-stream",
            PutOptions::default(),
        )
        .unwrap();
    assert_eq!(upload.next_part_number, 1);
    let first = store
        .upload_part(&upload.upload_id, 1, vec![b'a'; 40])
        .unwrap();
    let duplicate = store
        .upload_part(&upload.upload_id, 1, vec![b'a'; 40])
        .unwrap();
    assert_eq!(first, duplicate);
    store
        .upload_part(&upload.upload_id, 3, vec![b'c'; 10])
        .unwrap();
    assert!(matches!(
        store.complete_multipart_upload(&upload.upload_id, None, None),
        Err(ObjectError::PreconditionFailed(_))
    ));
    store
        .upload_part(&upload.upload_id, 2, vec![b'b'; 24])
        .unwrap();
    let staged = store.multipart_upload(&upload.upload_id).unwrap();
    assert_eq!(staged.total_bytes, 74);
    let staged_page = store
        .list_multipart_uploads_page(Some("bucket"), None, 1, 1)
        .unwrap();
    assert_eq!(staged_page.scanned_uploads, 1);
    assert_eq!(staged_page.emitted_uploads, 1);
    assert_eq!(staged_page.uploads[0].upload_id, upload.upload_id);
    assert!(staged_page.payload_bytes >= 74);
    assert!(!staged_page.has_more);
    assert_eq!(
        store
            .list_multipart_parts(&upload.upload_id, 1, 10)
            .unwrap()
            .iter()
            .map(|part| part.part_number)
            .collect::<Vec<_>>(),
        vec![2, 3]
    );
    let first_part_page = store
        .list_multipart_parts_page(&upload.upload_id, 0, 1, 0)
        .unwrap();
    assert_eq!(first_part_page.scanned_parts, 3);
    assert_eq!(first_part_page.emitted_parts, 1);
    assert_eq!(first_part_page.parts[0].part_number, 1);
    assert_eq!(first_part_page.next_part_marker, Some(1));
    assert!(first_part_page.has_more);
    let second_part_page = store
        .list_multipart_parts_page(
            &upload.upload_id,
            first_part_page.next_part_marker.unwrap(),
            2,
            0,
        )
        .unwrap();
    assert_eq!(
        second_part_page
            .parts
            .iter()
            .map(|part| part.part_number)
            .collect::<Vec<_>>(),
        vec![2, 3]
    );
    assert!(!second_part_page.has_more);
    let budgeted_part_page = store
        .list_multipart_parts_page(&upload.upload_id, 0, 10, 1)
        .unwrap();
    assert_eq!(budgeted_part_page.emitted_parts, 1);
    assert!(budgeted_part_page.payload_bytes >= 40);
    assert!(budgeted_part_page.has_more);

    let snapshot = store.export_snapshot().unwrap();
    snapshot.validate().unwrap();
    let mut restored = MatrixObjectStore::new(test_options()).unwrap();
    restored.install_snapshot(snapshot).unwrap();
    assert_eq!(
        restored
            .list_multipart_uploads(Some("bucket"), None, 10)
            .unwrap()
            .len(),
        1
    );
    let expected = [vec![b'a'; 40], vec![b'b'; 24], vec![b'c'; 10]].concat();
    let metadata = restored
        .complete_multipart_upload(
            &upload.upload_id,
            Some(expected.len() as u64),
            Some(etag(&expected)),
        )
        .unwrap();
    assert_eq!(metadata.length, expected.len() as u64);
    assert_eq!(
        restored.get_object("bucket", "large").unwrap().data,
        expected
    );
    assert!(restored.multipart_upload(&upload.upload_id).is_err());

    let aborting = restored
        .create_multipart_upload("bucket", "abort", "text/plain", PutOptions::default())
        .unwrap();
    let pending = restored
        .create_multipart_upload("bucket", "pending", "text/plain", PutOptions::default())
        .unwrap();
    let first_upload_page = restored
        .list_multipart_uploads_page(Some("bucket"), None, 1, 0)
        .unwrap();
    assert_eq!(first_upload_page.scanned_uploads, 2);
    assert_eq!(first_upload_page.emitted_uploads, 1);
    assert!(first_upload_page.has_more);
    assert_eq!(
        first_upload_page.next_marker.as_deref(),
        Some(aborting.upload_id.as_str())
    );
    let second_upload_page = restored
        .list_multipart_uploads_page(
            Some("bucket"),
            first_upload_page.next_marker.as_deref(),
            1,
            0,
        )
        .unwrap();
    assert_eq!(second_upload_page.emitted_uploads, 1);
    assert_eq!(second_upload_page.uploads[0].upload_id, pending.upload_id);
    assert!(!second_upload_page.has_more);
    restored
        .upload_part(&aborting.upload_id, 1, b"staged".to_vec())
        .unwrap();
    let aborted = restored
        .abort_multipart_upload(&aborting.upload_id)
        .unwrap();
    assert_eq!(aborted.total_bytes, 6);
    assert!(restored.multipart_upload(&aborting.upload_id).is_err());
    restored.abort_multipart_upload(&pending.upload_id).unwrap();
}

#[test]
fn overwrite_delete_and_discard_accounting() {
    let mut store = MatrixObjectStore::new(test_options()).unwrap();
    store
        .put_object("bucket", "object", b"abcdefgh".to_vec(), "text/plain")
        .unwrap();
    store
        .put_object("bucket", "object", b"ABCDEF".to_vec(), "text/plain")
        .unwrap();
    let report = store.gc_report();
    assert!(report.stale_bytes >= 8);
    assert!(report.live_bytes >= 6);
    assert_eq!(report.min_discard_bytes, 1);
    assert_eq!(report.max_discard_bytes, 0);
    assert!(report.selected_discard_range_count > 0);
    assert_eq!(report.budget_skipped_discard_range_count, 0);
    assert_eq!(
        report.selected_discard_bytes,
        report.discard_candidate_bytes
    );
    assert_eq!(
        report.discard_candidates.len() as u64,
        report.selected_discard_range_count
    );
    assert_eq!(
        report
            .discard_candidates
            .iter()
            .map(|candidate| candidate.range.length)
            .sum::<u64>(),
        report.selected_discard_bytes
    );
    let fields = report.to_control_fields("");
    assert_eq!(
        fields
            .get("discard_candidate_range_count")
            .and_then(|value| value.parse::<u64>().ok()),
        Some(report.selected_discard_range_count)
    );
    assert_eq!(
        fields
            .get("object_gc_report_proof_format")
            .map(String::as_str),
        Some(report.proof_format())
    );
    assert_eq!(
        fields.get("object_gc_report_proof_checksum"),
        Some(&report.proof_checksum())
    );
    assert!(fields.contains_key("discard_candidate.0.segment_id"));
    assert!(fields.contains_key("discard_candidate.0.range.offset"));
    assert!(report
        .verify_expected_proof_checksum(report.proof_checksum())
        .is_ok());
    assert!(store
        .gc_report_with_expected_proof(report.proof_checksum())
        .is_ok());
    assert!(matches!(
        store.gc_report_with_expected_proof("stale-gc-proof"),
        Err(ObjectError::PreconditionFailed(_))
    ));
    assert!(store
        .gc_report_with_discard_policy_proof_fenced(1, 0, None, report.proof_checksum())
        .is_ok());
    let route_checksum = store.chunk_service.route_control_proof().state_checksum;
    let route_fenced_report = store
        .gc_report_with_discard_policy_fenced(1, 0, Some(&route_checksum))
        .unwrap();
    assert!(store
        .gc_report_with_discard_policy_proof_fenced(
            1,
            0,
            Some(&route_checksum),
            route_fenced_report.proof_checksum()
        )
        .is_ok());
    let (metadata_report, _readiness) = store
        .gc_report_with_metadata_read_proof_fenced(
            MetadataReadOptions::default(),
            Some(&route_checksum),
            route_fenced_report.proof_checksum(),
        )
        .unwrap();
    assert_eq!(
        metadata_report.proof_checksum(),
        route_fenced_report.proof_checksum()
    );
    let mut tampered_report = report.clone();
    tampered_report.discard_candidates[0].range.length = tampered_report.discard_candidates[0]
        .range
        .length
        .saturating_add(1);
    assert_ne!(report.proof_checksum(), tampered_report.proof_checksum());
    assert!(matches!(
        tampered_report.verify_expected_proof_checksum(report.proof_checksum()),
        Err(ObjectError::PreconditionFailed(_))
    ));
    assert!(!report.discard_budget_limited);
    let bounded_report = store.gc_report_with_discard_budget(3);
    assert_eq!(bounded_report.max_discard_bytes, 3);
    assert_eq!(bounded_report.selected_discard_bytes, 0);
    assert_eq!(bounded_report.selected_discard_range_count, 0);
    assert!(bounded_report.discard_candidates.is_empty());
    assert!(bounded_report.budget_skipped_discard_range_count > 0);
    assert!(bounded_report.discard_budget_limited);
    let min_filtered_report = store.gc_report_with_discard_policy(9, 0);
    assert_eq!(min_filtered_report.min_discard_bytes, 9);
    assert_eq!(min_filtered_report.max_discard_bytes, 0);
    assert_eq!(min_filtered_report.selected_discard_bytes, 0);
    assert_eq!(min_filtered_report.selected_discard_range_count, 0);
    assert!(min_filtered_report.discard_candidates.is_empty());
    assert_eq!(min_filtered_report.budget_skipped_discard_range_count, 0);
    assert!(!min_filtered_report.discard_budget_limited);
    let plans = store.plan_discard(1, 8);
    assert!(!plans.is_empty());
    let first = plans[0].clone();
    store
        .apply_discard(&first.chunk_id, first.ranges.clone())
        .unwrap();
    assert!(store.gc_report().discarded_bytes >= first.discard_bytes);
    store.delete_object("bucket", "object").unwrap();
    assert!(store.get_object("bucket", "object").is_err());
}

#[test]
fn raft_backed_object_gc_report_rejects_stale_expected_proof() {
    let raft = InMemoryRustRaft::new(1).unwrap();
    let store = MatrixObjectStore::new(test_options()).unwrap();
    let mut replicated = RaftBackedObjectStore::new(raft, store);
    replicated
        .propose(ObjectCommand::PutObject {
            bucket: "bucket".to_string(),
            key: "gc-proof".to_string(),
            data: b"old-data".to_vec(),
            content_type: "text/plain".to_string(),
            update_time_ms: 1,
            options: PutOptions::default(),
        })
        .unwrap();
    replicated
        .propose(ObjectCommand::PutObject {
            bucket: "bucket".to_string(),
            key: "gc-proof".to_string(),
            data: b"new-data".to_vec(),
            content_type: "text/plain".to_string(),
            update_time_ms: 2,
            options: PutOptions::default(),
        })
        .unwrap();
    let route_checksum = replicated
        .store()
        .chunk_service
        .route_control_proof()
        .state_checksum;
    let (report, readiness) = replicated
        .object_gc_report_with_discard_policy_linearizable_fenced(1, 0, 2, &route_checksum)
        .unwrap();
    assert!(readiness.readable);
    assert!(report.selected_discard_range_count > 0);
    let proof_checksum = report.proof_checksum();
    let (proof_report, proof_readiness) = replicated
        .object_gc_report_with_discard_policy_linearizable_proof_fenced(
            1,
            0,
            2,
            &route_checksum,
            &proof_checksum,
        )
        .unwrap();
    assert!(proof_readiness.readable);
    assert_eq!(proof_report.proof_checksum(), proof_checksum);
    let proven = replicated
        .object_gc_report_with_discard_policy_and_read_proof_linearizable_proof_fenced(
            1,
            0,
            2,
            &proof_checksum,
        )
        .unwrap();
    assert_eq!(proven.value.proof_checksum(), proof_checksum);
    assert!(matches!(
        replicated.object_gc_report_with_discard_policy_linearizable_proof_fenced(
            1,
            0,
            2,
            &route_checksum,
            "stale-gc-proof",
        ),
        Err(ObjectError::PreconditionFailed(_))
    ));
}

#[test]
fn copy_object_uses_put_semantics_and_stale_accounting() {
    let mut store = MatrixObjectStore::new(test_options()).unwrap();
    store.set_bucket_versioning("bucket", true).unwrap();
    let source = store
        .put_object_with_options(
            "bucket",
            "source",
            b"copy-me".to_vec(),
            "text/plain",
            PutOptions {
                tags: tags(&[("team", "storage"), ("env", "prod")]),
                ..PutOptions::default()
            },
        )
        .unwrap();
    let copy = store
        .copy_object("bucket", "source", "bucket", "copy")
        .unwrap();
    assert_eq!(copy.length, source.length);
    assert_eq!(copy.etag(), source.etag());
    assert_eq!(copy.content_type, "text/plain");
    assert_eq!(copy.tags.get("team").map(String::as_str), Some("storage"));
    assert_eq!(
        store.get_object("bucket", "copy").unwrap().data,
        b"copy-me".to_vec()
    );

    let overwritten = store
        .copy_object_with_options(
            "bucket",
            "source",
            "bucket",
            "copy",
            Some("application/octet-stream".to_string()),
            PutOptions {
                if_match_etag: Some(copy.etag().to_string()),
                tags: tags(&[("team", "database")]),
                ..PutOptions::default()
            },
        )
        .unwrap();
    assert_eq!(overwritten.version, copy.version + 1);
    assert_eq!(overwritten.content_type, "application/octet-stream");
    assert_eq!(
        store.get_object_tags("bucket", "copy").unwrap(),
        tags(&[("team", "database")])
    );
    assert_eq!(
        store.list_object_versions("bucket", "copy").unwrap().len(),
        2
    );
    assert!(matches!(
        store.copy_object_with_options(
            "bucket",
            "missing",
            "bucket",
            "copy2",
            None,
            PutOptions::default(),
        ),
        Err(ObjectError::NotFound(_))
    ));

    let before = store.gc_report().stale_bytes;
    store
        .copy_object_with_options(
            "bucket",
            "source",
            "plain",
            "plain-copy",
            None,
            PutOptions::default(),
        )
        .unwrap();
    store
        .copy_object("bucket", "source", "plain", "plain-copy")
        .unwrap();
    assert!(store.gc_report().stale_bytes > before);
}

#[test]
fn batch_object_copies_are_bounded_and_report_per_item_status() {
    let mut store = MatrixObjectStore::new(test_options()).unwrap();
    store
        .put_object("bucket", "source-a", b"alpha".to_vec(), "text/plain")
        .unwrap();
    store
        .put_object("bucket", "source-b", b"bravo".to_vec(), "text/plain")
        .unwrap();

    let report = store
        .batch_copy_objects(
            vec![
                ObjectCopyRequest {
                    source_bucket: "bucket".to_string(),
                    source_key: "source-a".to_string(),
                    source_version: None,
                    destination_bucket: "dest".to_string(),
                    destination_key: "copy-a".to_string(),
                    content_type: Some("application/copied".to_string()),
                    options: PutOptions::default(),
                },
                ObjectCopyRequest {
                    source_bucket: "bucket".to_string(),
                    source_key: "source-b".to_string(),
                    source_version: None,
                    destination_bucket: "dest".to_string(),
                    destination_key: "copy-b".to_string(),
                    content_type: None,
                    options: PutOptions {
                        tags: tags(&[("team", "metadata")]),
                        ..PutOptions::default()
                    },
                },
                ObjectCopyRequest {
                    source_bucket: "bucket".to_string(),
                    source_key: "missing".to_string(),
                    source_version: None,
                    destination_bucket: "dest".to_string(),
                    destination_key: "copy-missing".to_string(),
                    content_type: None,
                    options: PutOptions::default(),
                },
            ],
            8,
            1024,
            10,
        )
        .unwrap();

    assert_eq!(report.requested_objects, 3);
    assert_eq!(report.copied_objects, 2);
    assert_eq!(report.failed_objects, 1);
    assert_eq!(report.copied_bytes, 10);
    assert_eq!(report.items.len(), 3);
    assert!(report.items[0].error_code.is_none());
    assert_eq!(
        report.items[0]
            .metadata
            .as_ref()
            .map(|metadata| &*metadata.content_type),
        Some("application/copied")
    );
    assert_eq!(
        store.get_object("dest", "copy-a").unwrap().data,
        b"alpha".to_vec()
    );
    assert_eq!(
        store.get_object_tags("dest", "copy-b").unwrap(),
        tags(&[("team", "metadata")])
    );
    assert_eq!(report.items[2].error_code.as_deref(), Some("NotFound"));
    assert!(store.get_object("dest", "copy-missing").is_err());

    let budgeted = store
        .batch_copy_objects(
            vec![
                ObjectCopyRequest {
                    source_bucket: "bucket".to_string(),
                    source_key: "source-a".to_string(),
                    source_version: None,
                    destination_bucket: "dest".to_string(),
                    destination_key: "budget-a".to_string(),
                    content_type: None,
                    options: PutOptions::default(),
                },
                ObjectCopyRequest {
                    source_bucket: "bucket".to_string(),
                    source_key: "source-b".to_string(),
                    source_version: None,
                    destination_bucket: "dest".to_string(),
                    destination_key: "budget-b".to_string(),
                    content_type: None,
                    options: PutOptions::default(),
                },
            ],
            2,
            5,
            11,
        )
        .unwrap();
    assert_eq!(budgeted.copied_objects, 1);
    assert_eq!(budgeted.failed_objects, 1);
    assert_eq!(
        budgeted.items[1].error_code.as_deref(),
        Some("PreconditionFailed")
    );
    assert!(store.get_object("dest", "budget-b").is_err());
    assert!(matches!(
        store.batch_copy_objects(Vec::new(), 0, 0, 12),
        Err(ObjectError::InvalidArgument(_))
    ));
}

#[test]
fn object_changefeed_tracks_mutations_cursors_and_snapshots() {
    let mut store = MatrixObjectStore::new(test_options()).unwrap();
    store.create_bucket("bucket").unwrap();
    store
        .put_object("bucket", "object", b"alpha".to_vec(), "text/plain")
        .unwrap();
    store
        .copy_object("bucket", "object", "bucket", "copy")
        .unwrap();
    store
        .set_object_tags("bucket", "copy", tags(&[("kind", "copy")]))
        .unwrap();
    store.delete_object("bucket", "object").unwrap();

    let changes = store.list_object_changes_after(0, 16).unwrap();
    assert_eq!(
        changes
            .iter()
            .map(|change| &*change.operation)
            .collect::<Vec<_>>(),
        vec![
            "put_object",
            "copy_object",
            "set_object_tags",
            "delete_object"
        ]
    );
    assert_eq!(changes[0].sequence, 1);
    assert_eq!(changes[1].previous_sequence, 1);
    assert_eq!(changes[1].object_id, ObjectId::new("bucket", "copy"));
    assert!(changes[3].deleted);
    assert_eq!(
        store
            .list_object_changes_after(changes[1].sequence, 2)
            .unwrap()
            .len(),
        2
    );

    let cursor = store
        .commit_object_change_cursor("replicator-a", changes[2].sequence, 100)
        .unwrap();
    assert_eq!(cursor.sequence, changes[2].sequence);
    assert!(matches!(
        store.commit_object_change_cursor("replicator-a", changes[1].sequence, 101),
        Err(ObjectError::PreconditionFailed(_))
    ));
    assert!(matches!(
        store.commit_object_change_cursor("bad/id", changes[2].sequence, 101),
        Err(ObjectError::InvalidArgument(_))
    ));

    let snapshot = store.export_snapshot().unwrap();
    snapshot.validate().unwrap();
    let mut restored = MatrixObjectStore::new(test_options()).unwrap();
    restored.install_snapshot(snapshot).unwrap();
    assert_eq!(
        restored
            .object_change_cursor("replicator-a")
            .unwrap()
            .sequence,
        changes[2].sequence
    );
    assert_eq!(
        restored
            .list_object_changes_after(0, 16)
            .unwrap()
            .iter()
            .map(|change| &*change.operation)
            .collect::<Vec<_>>(),
        vec![
            "put_object",
            "copy_object",
            "set_object_tags",
            "delete_object"
        ]
    );
}

#[test]
fn object_tags_are_durable_listable_and_preserved_by_multipart() {
    let mut store = MatrixObjectStore::new(test_options()).unwrap();
    let first = store
        .put_object_with_options(
            "bucket",
            "tagged-a",
            b"a".to_vec(),
            "text/plain",
            PutOptions {
                tags: tags(&[("class", "hot"), ("team", "alpha")]),
                ..PutOptions::default()
            },
        )
        .unwrap();
    assert_eq!(first.tags.get("class").map(String::as_str), Some("hot"));
    store
        .put_object_with_options(
            "bucket",
            "tagged-b",
            b"b".to_vec(),
            "text/plain",
            PutOptions {
                tags: tags(&[("class", "cold"), ("team", "alpha")]),
                ..PutOptions::default()
            },
        )
        .unwrap();
    store
        .set_object_tags("bucket", "tagged-b", tags(&[("class", "hot")]))
        .unwrap();
    assert_eq!(
        store
            .list_objects_by_tag("bucket", "class", "hot", None, 10)
            .unwrap()
            .iter()
            .map(|metadata| metadata.object_id.key.clone())
            .collect::<Vec<_>>(),
        vec!["tagged-a".to_string(), "tagged-b".to_string()]
    );
    let first_tag_page = store
        .list_objects_by_tag_page("bucket", "class", "hot", None, 1, 0)
        .unwrap();
    assert_eq!(first_tag_page.scanned_objects, 2);
    assert_eq!(first_tag_page.emitted_objects, 1);
    assert_eq!(first_tag_page.objects[0].object_id.key, "tagged-a");
    assert_eq!(first_tag_page.next_marker.as_deref(), Some("tagged-a"));
    assert!(first_tag_page.has_more);
    let second_tag_page = store
        .list_objects_by_tag_page(
            "bucket",
            "class",
            "hot",
            first_tag_page.next_marker.as_deref(),
            1,
            0,
        )
        .unwrap();
    assert_eq!(second_tag_page.emitted_objects, 1);
    assert_eq!(second_tag_page.objects[0].object_id.key, "tagged-b");
    assert_eq!(second_tag_page.next_marker, None);
    assert!(!second_tag_page.has_more);
    let budgeted_tag_page = store
        .list_objects_by_tag_page("bucket", "class", "hot", None, 10, 1)
        .unwrap();
    assert_eq!(budgeted_tag_page.emitted_objects, 1);
    assert!(budgeted_tag_page.payload_bytes >= 1);
    assert!(budgeted_tag_page.has_more);

    let upload = store
        .create_multipart_upload(
            "bucket",
            "mpu-tagged",
            "application/octet-stream",
            PutOptions {
                tags: tags(&[("class", "hot"), ("source", "multipart")]),
                ..PutOptions::default()
            },
        )
        .unwrap();
    store
        .upload_part(&upload.upload_id, 1, b"part".to_vec())
        .unwrap();
    let completed = store
        .complete_multipart_upload(&upload.upload_id, Some(4), Some(etag(b"part")))
        .unwrap();
    assert_eq!(
        completed.tags.to_map(),
        tags(&[("class", "hot"), ("source", "multipart")])
    );

    let snapshot = store.export_snapshot().unwrap();
    snapshot.validate().unwrap();
    let mut restored = MatrixObjectStore::new(test_options()).unwrap();
    restored.install_snapshot(snapshot).unwrap();
    assert_eq!(
        restored
            .get_object_tags("bucket", "mpu-tagged")
            .unwrap()
            .get("source")
            .map(String::as_str),
        Some("multipart")
    );
    assert!(matches!(
        restored.set_object_tags("bucket", "tagged-a", tags(&[("", "bad")])),
        Err(ObjectError::InvalidArgument(_))
    ));
}

#[test]
fn storage_class_and_restore_windows_gate_cold_payload_reads() {
    let mut store = MatrixObjectStore::new(test_options()).unwrap();
    let cold = store
        .put_object_with_options(
            "bucket",
            "cold",
            b"frozen".to_vec(),
            "text/plain",
            PutOptions {
                storage_class: Some("ARCHIVE".to_string()),
                ..PutOptions::default()
            },
        )
        .unwrap();
    assert_eq!(cold.storage_class, "ARCHIVE");
    assert_eq!(store.head_object("bucket", "cold").unwrap().length, 6);
    assert_eq!(store.list_objects("bucket", "", None, 10).unwrap().len(), 1);
    assert!(matches!(
        store.get_object("bucket", "cold"),
        Err(ObjectError::PreconditionFailed(_))
    ));
    assert!(matches!(
        store.get_object_range("bucket", "cold", 0, 2),
        Err(ObjectError::PreconditionFailed(_))
    ));
    assert!(matches!(
        store.prewarm_object_range_cache("bucket", "cold", 0, 2, 0),
        Err(ObjectError::PreconditionFailed(_))
    ));

    let restored = store.restore_object("bucket", "cold", 60_000).unwrap();
    assert!(restored.lock.restore_until_ms >= now_millis());
    assert_eq!(
        store.get_object("bucket", "cold").unwrap().data,
        b"frozen".to_vec()
    );
    let copied = store
        .copy_object("bucket", "cold", "bucket", "cold-copy")
        .unwrap();
    assert_eq!(copied.storage_class, "ARCHIVE");
    assert!(copied.lock.restore_until_ms >= now_millis());

    let upload = store
        .create_multipart_upload(
            "bucket",
            "mpu-cold",
            "application/octet-stream",
            PutOptions {
                storage_class: Some("GLACIER".to_string()),
                ..PutOptions::default()
            },
        )
        .unwrap();
    store
        .upload_part(&upload.upload_id, 1, b"part".to_vec())
        .unwrap();
    let completed = store
        .complete_multipart_upload(&upload.upload_id, Some(4), Some(etag(b"part")))
        .unwrap();
    assert_eq!(completed.storage_class, "GLACIER");
    assert!(matches!(
        store.get_object("bucket", "mpu-cold"),
        Err(ObjectError::PreconditionFailed(_))
    ));

    store
        .transition_object("bucket", "mpu-cold", "STANDARD")
        .unwrap();
    assert_eq!(
        store.get_object("bucket", "mpu-cold").unwrap().data,
        b"part".to_vec()
    );
    assert!(matches!(
        store.transition_object("bucket", "mpu-cold", "INVALID"),
        Err(ObjectError::InvalidArgument(_))
    ));

    let snapshot = store.export_snapshot().unwrap();
    snapshot.validate().unwrap();
    let mut restored_store = MatrixObjectStore::new(test_options()).unwrap();
    restored_store.install_snapshot(snapshot).unwrap();
    assert_eq!(
        restored_store
            .head_object("bucket", "cold")
            .unwrap()
            .storage_class,
        "ARCHIVE"
    );
    assert_eq!(
        restored_store.get_object("bucket", "cold").unwrap().data,
        b"frozen".to_vec()
    );
}

#[test]
fn bucket_lifecycle_policies_filter_transition_and_expire_bounded() {
    let mut store = MatrixObjectStore::new(test_options()).unwrap();
    store.set_bucket_versioning("bucket", true).unwrap();
    store
        .put_object_with_options(
            "bucket",
            "logs/hot",
            b"v1".to_vec(),
            "text/plain",
            PutOptions {
                tags: tags(&[("class", "hot")]),
                ..PutOptions::default()
            },
        )
        .unwrap();
    store
        .put_object_with_options(
            "bucket",
            "logs/hot",
            b"v2".to_vec(),
            "text/plain",
            PutOptions {
                tags: tags(&[("class", "hot")]),
                ..PutOptions::default()
            },
        )
        .unwrap();
    store
        .put_object_with_options(
            "bucket",
            "logs/cold",
            b"v1".to_vec(),
            "text/plain",
            PutOptions {
                tags: tags(&[("class", "cold")]),
                ..PutOptions::default()
            },
        )
        .unwrap();
    store
        .put_object_with_options(
            "bucket",
            "logs/cold",
            b"v2".to_vec(),
            "text/plain",
            PutOptions {
                tags: tags(&[("class", "cold")]),
                ..PutOptions::default()
            },
        )
        .unwrap();
    store
        .configure_bucket_lifecycle(
            "bucket",
            BucketLifecyclePolicy {
                noncurrent_versions_to_keep: 0,
                noncurrent_older_than_ms: 1,
                transition_after_ms: 1,
                transition_storage_class: Some("GLACIER".to_string()),
                filter_tag_key: Some("class".to_string()),
                filter_tag_value: Some("hot".to_string()),
                filter_prefix: Some("logs/".to_string()),
                ..BucketLifecyclePolicy::default()
            },
        )
        .unwrap();
    let result = store
        .apply_bucket_lifecycle_policies_at(10, u64::MAX / 2)
        .unwrap();
    assert_eq!(result.transitioned_current_objects, 1);
    assert_eq!(result.expired_noncurrent_versions, 1);
    assert_eq!(
        store
            .head_object("bucket", "logs/hot")
            .unwrap()
            .storage_class,
        "GLACIER"
    );
    assert_eq!(
        store
            .head_object("bucket", "logs/cold")
            .unwrap()
            .storage_class,
        "STANDARD"
    );
    assert_eq!(
        store
            .list_object_versions("bucket", "logs/hot")
            .unwrap()
            .len(),
        1
    );
    assert_eq!(
        store
            .list_object_versions("bucket", "logs/cold")
            .unwrap()
            .len(),
        2
    );

    let snapshot = store.export_snapshot().unwrap();
    snapshot.validate().unwrap();
    let mut restored = MatrixObjectStore::new(test_options()).unwrap();
    restored.install_snapshot(snapshot).unwrap();
    assert_eq!(
        restored
            .bucket_lifecycle("bucket")
            .unwrap()
            .transition_storage_class
            .as_deref(),
        Some("GLACIER")
    );

    let mut bounded = MatrixObjectStore::new(test_options()).unwrap();
    bounded
        .put_object("bucket", "a", b"a".to_vec(), "text/plain")
        .unwrap();
    bounded
        .put_object("bucket", "b", b"b".to_vec(), "text/plain")
        .unwrap();
    bounded
        .configure_bucket_lifecycle(
            "bucket",
            BucketLifecyclePolicy {
                transition_after_ms: 1,
                transition_storage_class: Some("ARCHIVE".to_string()),
                ..BucketLifecyclePolicy::default()
            },
        )
        .unwrap();
    let first = bounded
        .apply_bucket_lifecycle_policies_at(1, u64::MAX / 2)
        .unwrap();
    assert_eq!(first.transitioned_current_objects, 1);
    assert!(first.truncated);
    let second = bounded
        .apply_bucket_lifecycle_policies_at(10, u64::MAX / 2)
        .unwrap();
    assert_eq!(second.transitioned_current_objects, 1);
}

#[test]
fn bucket_lifecycle_transitions_only_preserve_expirable_versions() {
    let mut store = MatrixObjectStore::new(test_options()).unwrap();
    store.set_bucket_versioning("bucket", true).unwrap();
    store
        .put_object("bucket", "object", b"v1".to_vec(), "text/plain")
        .unwrap();
    store
        .put_object("bucket", "object", b"v2".to_vec(), "text/plain")
        .unwrap();
    store
        .put_object("bucket", "marker", b"gone".to_vec(), "text/plain")
        .unwrap();
    store.delete_object("bucket", "marker").unwrap();
    store
        .configure_bucket_lifecycle(
            "bucket",
            BucketLifecyclePolicy {
                noncurrent_versions_to_keep: 0,
                noncurrent_older_than_ms: 1,
                transition_after_ms: 1,
                transition_storage_class: Some("ARCHIVE".to_string()),
                expire_current_after_ms: 1,
                expire_delete_markers: true,
                ..BucketLifecyclePolicy::default()
            },
        )
        .unwrap();

    let result = store
        .apply_bucket_lifecycle_transitions_at(10, u64::MAX / 2)
        .unwrap();
    assert_eq!(result.transitioned_current_objects, 1);
    assert_eq!(result.expired_noncurrent_versions, 0);
    assert_eq!(result.expired_current_objects, 0);
    assert_eq!(result.removed_delete_markers, 0);
    assert_eq!(
        store.head_object("bucket", "object").unwrap().storage_class,
        "ARCHIVE"
    );
    assert_eq!(
        store
            .list_object_versions("bucket", "object")
            .unwrap()
            .len(),
        2
    );
    assert!(store
        .objects.contains(&ObjectId::new("bucket", "marker")));
}

#[test]
fn bucket_lifecycle_expires_current_and_delete_markers() {
    let mut store = MatrixObjectStore::new(test_options()).unwrap();
    store
        .put_object("expire", "current", b"data".to_vec(), "text/plain")
        .unwrap();
    store
        .put_object("expire", "marker", b"gone".to_vec(), "text/plain")
        .unwrap();
    store.delete_object("expire", "marker").unwrap();
    store
        .configure_bucket_lifecycle(
            "expire",
            BucketLifecyclePolicy {
                expire_current_after_ms: 1,
                expire_delete_markers: true,
                ..BucketLifecyclePolicy::default()
            },
        )
        .unwrap();
    let result = store
        .apply_bucket_lifecycle_policies_at(10, u64::MAX / 2)
        .unwrap();
    assert_eq!(result.expired_current_objects, 1);
    assert_eq!(result.removed_delete_markers, 1);
    assert!(store.head_object("expire", "current").is_err());
    assert!(store
        .object(&ObjectId::new("expire", "marker"))
        .is_none());

    let mut semantic_store = MatrixObjectStore::new(test_options()).unwrap();
    semantic_store
        .put_object(
            "expire",
            "tombstoned-marker",
            b"gone".to_vec(),
            "text/plain",
        )
        .unwrap();
    semantic_store
        .delete_object("expire", "tombstoned-marker")
        .unwrap();
    let tombstoned_id = ObjectId::new("expire", "tombstoned-marker");
    let mut tombstoned_archived = semantic_store.object(&tombstoned_id).unwrap().clone();
    tombstoned_archived.version = tombstoned_archived.version.saturating_sub(1);
    semantic_store
        .versions
        .entry(tombstoned_id.clone())
        .or_default()
        .push(tombstoned_archived);
    semantic_store
        .configure_bucket_lifecycle(
            "expire",
            BucketLifecyclePolicy {
                expire_delete_markers: true,
                ..BucketLifecyclePolicy::default()
            },
        )
        .unwrap();
    let semantic_result = semantic_store
        .apply_bucket_lifecycle_policies_at(10, u64::MAX / 2)
        .unwrap();
    assert_eq!(semantic_result.removed_delete_markers, 1);
    assert!(semantic_store.object(&tombstoned_id).is_none());
}

#[test]
fn bucket_quotas_gate_put_copy_and_multipart_completion() {
    let mut store = MatrixObjectStore::new(test_options()).unwrap();
    store.configure_bucket_quota("bucket", 10, 2).unwrap();
    assert_eq!(
        store.bucket_quota("bucket").unwrap(),
        BucketQuota {
            max_live_bytes: 10,
            max_live_objects: 2
        }
    );
    store
        .put_object("bucket", "a", b"1234".to_vec(), "text/plain")
        .unwrap();
    store
        .put_object("bucket", "b", b"12".to_vec(), "text/plain")
        .unwrap();
    assert_eq!(store.bucket_live_usage("bucket").unwrap(), (6, 2));
    assert!(matches!(
        store.put_object("bucket", "c", b"1".to_vec(), "text/plain"),
        Err(ObjectError::PreconditionFailed(_))
    ));
    store.delete_object("bucket", "b").unwrap();
    store
        .put_object("bucket", "c", b"123456".to_vec(), "text/plain")
        .unwrap();
    assert_eq!(store.bucket_live_usage("bucket").unwrap(), (10, 2));
    assert!(matches!(
        store.put_object("bucket", "a", b"12345".to_vec(), "text/plain"),
        Err(ObjectError::PreconditionFailed(_))
    ));
    let report_before = store.gc_report();
    store
        .put_object("bucket", "a", b"123".to_vec(), "text/plain")
        .unwrap();
    assert_eq!(store.bucket_live_usage("bucket").unwrap(), (9, 2));
    assert!(store.gc_report().stale_bytes >= report_before.stale_bytes + 4);

    store.configure_bucket_quota("dest", 4, 1).unwrap();
    assert!(matches!(
        store.copy_object("bucket", "c", "dest", "too-large"),
        Err(ObjectError::PreconditionFailed(_))
    ));

    let upload = store
        .create_multipart_upload("dest", "mpu", "text/plain", PutOptions::default())
        .unwrap();
    store
        .upload_part(&upload.upload_id, 1, b"12345".to_vec())
        .unwrap();
    assert!(matches!(
        store.complete_multipart_upload(&upload.upload_id, Some(5), Some(etag(b"12345"))),
        Err(ObjectError::PreconditionFailed(_))
    ));
    assert!(store.multipart_upload(&upload.upload_id).is_ok());

    let snapshot = store.export_snapshot().unwrap();
    snapshot.validate().unwrap();
    let mut restored = MatrixObjectStore::new(test_options()).unwrap();
    restored.install_snapshot(snapshot).unwrap();
    assert_eq!(restored.bucket_quota("bucket").unwrap().max_live_bytes, 10);
    assert!(matches!(
        restored.put_object("bucket", "d", b"1".to_vec(), "text/plain"),
        Err(ObjectError::PreconditionFailed(_))
    ));
}

#[test]
fn retention_and_legal_hold_gate_destructive_object_paths() {
    let mut store = MatrixObjectStore::new(test_options()).unwrap();
    store
        .put_object("bucket", "held", b"payload".to_vec(), "text/plain")
        .unwrap();
    store.set_object_legal_hold("bucket", "held", true).unwrap();
    assert!(store.get_object_legal_hold("bucket", "held").unwrap());
    assert!(matches!(
        store.put_object("bucket", "held", b"replace".to_vec(), "text/plain"),
        Err(ObjectError::PreconditionFailed(_))
    ));
    assert!(matches!(
        store.delete_object("bucket", "held"),
        Err(ObjectError::PreconditionFailed(_))
    ));

    let copied = store
        .copy_object("bucket", "held", "bucket", "held-copy")
        .unwrap();
    assert!(copied.lock.legal_hold);
    assert!(matches!(
        store.delete_object("bucket", "held-copy"),
        Err(ObjectError::PreconditionFailed(_))
    ));

    store
        .set_object_legal_hold("bucket", "held", false)
        .unwrap();
    let until = now_millis().saturating_add(60_000);
    store.set_object_retention("bucket", "held", until).unwrap();
    assert_eq!(store.get_object_retention("bucket", "held").unwrap(), until);
    assert!(matches!(
        store.set_object_retention("bucket", "held", until - 1),
        Err(ObjectError::PreconditionFailed(_))
    ));
    assert!(matches!(
        store.delete_object("bucket", "held"),
        Err(ObjectError::PreconditionFailed(_))
    ));

    let mut versioned = MatrixObjectStore::new(test_options()).unwrap();
    versioned.set_bucket_versioning("bucket", true).unwrap();
    versioned
        .put_object("bucket", "object", b"v1".to_vec(), "text/plain")
        .unwrap();
    versioned
        .put_object("bucket", "object", b"v2".to_vec(), "text/plain")
        .unwrap();
    versioned
        .configure_bucket_retention("bucket", 60_000)
        .unwrap();
    assert_eq!(versioned.apply_lifecycle("bucket", 0).unwrap(), 0);
    assert_eq!(
        versioned
            .list_object_versions("bucket", "object")
            .unwrap()
            .len(),
        2
    );

    let mut snap_restored = MatrixObjectStore::new(test_options()).unwrap();
    let snapshot = store.export_snapshot().unwrap();
    snapshot.validate().unwrap();
    snap_restored.install_snapshot(snapshot).unwrap();
    assert!(matches!(
        snap_restored.delete_object("bucket", "held"),
        Err(ObjectError::PreconditionFailed(_))
    ));
}

