#[test]
fn raft_backed_store_replays_batch_copy_object_commands() {
    let raft = InMemoryRustRaft::new(1).unwrap();
    let store = MatrixObjectStore::new(test_options()).unwrap();
    let mut replicated = RaftBackedObjectStore::new(raft, store);
    replicated
        .propose(ObjectCommand::PutObject {
            bucket: "bucket".to_string(),
            key: "source-a".to_string(),
            data: b"alpha".to_vec(),
            content_type: "text/plain".to_string(),
            update_time_ms: 1,
            options: PutOptions::default(),
        })
        .unwrap();
    replicated
        .propose(ObjectCommand::PutObject {
            bucket: "bucket".to_string(),
            key: "source-b".to_string(),
            data: b"bravo".to_vec(),
            content_type: "text/plain".to_string(),
            update_time_ms: 2,
            options: PutOptions::default(),
        })
        .unwrap();

    let route_checksum = replicated
        .store
        .chunk_service
        .route_control_proof()
        .state_checksum;
    let local_report = replicated
        .store
        .batch_copy_objects_fenced(
            vec![ObjectCopyRequest {
                source_bucket: "bucket".to_string(),
                source_key: "source-a".to_string(),
                source_version: None,
                destination_bucket: "copy".to_string(),
                destination_key: "local-proof".to_string(),
                content_type: Some("application/local-copy".to_string()),
                options: PutOptions::default(),
            }],
            4,
            1024,
            4,
            Some(&route_checksum),
        )
        .unwrap();
    assert_eq!(local_report.copied_objects, 1);
    assert_eq!(local_report.expected_route_control_checksum, route_checksum);
    assert_eq!(
        local_report.route_control_proof.state_checksum,
        local_report.expected_route_control_checksum
    );
    assert!(matches!(
        replicated.store.batch_copy_objects_fenced(
            Vec::new(),
            4,
            1024,
            5,
            Some("stale-route-checksum"),
        ),
        Err(ObjectError::PreconditionFailed(_))
    ));

    let metadata = replicated
        .propose_batch_copy_objects(
            vec![
                ObjectCopyRequest {
                    source_bucket: "bucket".to_string(),
                    source_key: "source-a".to_string(),
                    source_version: None,
                    destination_bucket: "copy".to_string(),
                    destination_key: "source-a".to_string(),
                    content_type: Some("application/copied".to_string()),
                    options: PutOptions::default(),
                },
                ObjectCopyRequest {
                    source_bucket: "bucket".to_string(),
                    source_key: "source-b".to_string(),
                    source_version: None,
                    destination_bucket: "copy".to_string(),
                    destination_key: "source-b".to_string(),
                    content_type: None,
                    options: PutOptions::default(),
                },
                ObjectCopyRequest {
                    source_bucket: "bucket".to_string(),
                    source_key: "missing".to_string(),
                    source_version: None,
                    destination_bucket: "copy".to_string(),
                    destination_key: "missing".to_string(),
                    content_type: None,
                    options: PutOptions::default(),
                },
            ],
            8,
            1024,
            3,
        )
        .unwrap();

    assert_eq!(metadata.content_type, "objectstore/batch-copy");
    assert_eq!(metadata.version, 2);
    assert_eq!(metadata.length, 1);
    assert_eq!(metadata.update_time_ms, 10);
    assert_eq!(replicated.raft_commit_index(), 3);

    let mut follower = MatrixObjectStore::new(test_options()).unwrap();
    replicated.replay_into(&mut follower).unwrap();
    let copy_a = follower.get_object("copy", "source-a").unwrap();
    assert_eq!(copy_a.data, b"alpha".to_vec());
    assert_eq!(copy_a.metadata.content_type, "application/copied");
    assert_eq!(
        follower.get_object("copy", "source-b").unwrap().data,
        b"bravo".to_vec()
    );
    assert!(follower.get_object("copy", "missing").is_err());
    assert_eq!(follower.last_applied_index(), 3);
}

#[test]
fn raft_backed_store_replays_object_changefeed_cursors() {
    let raft = InMemoryRustRaft::new(1).unwrap();
    let store = MatrixObjectStore::new(test_options()).unwrap();
    let mut replicated = RaftBackedObjectStore::new(raft, store);
    replicated
        .propose(ObjectCommand::PutObject {
            bucket: "bucket".to_string(),
            key: "object".to_string(),
            data: b"raft-change".to_vec(),
            content_type: "text/plain".to_string(),
            update_time_ms: 1,
            options: PutOptions::default(),
        })
        .unwrap();
    replicated
        .propose_delete_with_placement_release("bucket", "object", None, 2)
        .unwrap();
    let changes = replicated.store().list_object_changes_after(0, 10).unwrap();
    assert_eq!(changes.len(), 2);
    assert_eq!(&*changes[1].operation, "delete_object");

    let cursor_meta = replicated
        .propose_commit_object_change_cursor("mirror-a", changes[1].sequence, 3)
        .unwrap();
    assert_eq!(cursor_meta.content_type, "objectstore/change-cursor");
    assert_eq!(replicated.raft_commit_index(), 3);

    let mut follower = MatrixObjectStore::new(test_options()).unwrap();
    replicated.replay_into(&mut follower).unwrap();
    assert_eq!(
        follower
            .list_object_changes_after(0, 10)
            .unwrap()
            .iter()
            .map(|change| &*change.operation)
            .collect::<Vec<_>>(),
        vec!["put_object", "delete_object"]
    );
    assert_eq!(
        follower.object_change_cursor("mirror-a").unwrap().sequence,
        changes[1].sequence
    );
    assert_eq!(follower.last_applied_index(), 3);
}

#[test]
fn raft_backed_store_replays_object_tag_updates() {
    let raft = InMemoryRustRaft::new(1).unwrap();
    let store = MatrixObjectStore::new(test_options()).unwrap();
    let mut replicated = RaftBackedObjectStore::new(raft, store);
    replicated
        .propose(ObjectCommand::PutObject {
            bucket: "bucket".to_string(),
            key: "tagged".to_string(),
            data: b"tagged-data".to_vec(),
            content_type: "text/plain".to_string(),
            update_time_ms: 1,
            options: PutOptions {
                tags: tags(&[("team", "storage")]),
                ..PutOptions::default()
            },
        })
        .unwrap();
    replicated
        .propose_set_object_tags("bucket", "tagged", tags(&[("team", "infra")]), 2)
        .unwrap();
    assert_eq!(replicated.raft_commit_index(), 2);

    let mut follower = MatrixObjectStore::new(test_options()).unwrap();
    replicated.replay_into(&mut follower).unwrap();
    assert_eq!(
        follower.get_object_tags("bucket", "tagged").unwrap(),
        tags(&[("team", "infra")])
    );
    // The replayed record must agree with the replayed object. Taken from the FOLLOWER's own
    // object, so a replay that updated one copy and not the other fails here.
    assert_eq!(
        follower
            .metadata_record(&meta_object_key(&ObjectId::new("bucket", "tagged")))
            .unwrap()
            .value,
        RecordValue::Digest(RecordValue::digest_of_object(
            &follower.head_object("bucket", "tagged").unwrap()
        )),
        "a replayed object record must carry the digest of the replayed object"
    );
    assert_eq!(follower.last_applied_index(), 2);
}

#[test]
fn raft_backed_store_replays_metaserver_shards_and_leases() {
    let raft = InMemoryRustRaft::new(1).unwrap();
    let store = MatrixObjectStore::new(test_options()).unwrap();
    let mut replicated = RaftBackedObjectStore::new(raft, store);
    let shard = MetadataShard {
        shard_id: "objects-a".to_string(),
        start_key: "object/bucket/".to_string(),
        end_key: "object/bucket0".to_string(),
        owner_node_id: "meta-a".to_string(),
        epoch: 1,
        draining: false,
    };
    let shard_receipt = replicated
        .propose_configure_meta_shard(shard.clone())
        .unwrap();
    assert_eq!(shard_receipt.content_type, "metaserver/shard-serving");
    let lease = replicated
        .propose_acquire_metadata_lease("object/bucket/", "writer-a", 100, 10)
        .unwrap();
    assert_eq!(lease.version, 1);
    replicated
        .propose_renew_metadata_lease("object/bucket/", "writer-a", 1, 200, 20)
        .unwrap();
    replicated
        .propose(ObjectCommand::PutObject {
            bucket: "bucket".to_string(),
            key: "object".to_string(),
            data: b"leased-write".to_vec(),
            content_type: "text/plain".to_string(),
            update_time_ms: 21,
            options: PutOptions {
                lease_owner: Some("writer-a".to_string()),
                lease_epoch: Some(1),
                ..PutOptions::default()
            },
        })
        .unwrap();
    let released = replicated
        .propose_release_metadata_lease("object/bucket/", "writer-a", 1)
        .unwrap();
    assert_eq!(released.content_type, "metaserver/lease-release");
    assert_eq!(replicated.raft_commit_index(), 5);

    let mut follower = MatrixObjectStore::new(test_options()).unwrap();
    replicated.replay_into(&mut follower).unwrap();
    let read = follower.get_object("bucket", "object").unwrap();
    assert_eq!(read.data, b"leased-write".to_vec());
    assert_eq!(
        follower
            .metadata_record(&meta_object_key(&ObjectId::new("bucket", "object")))
            .unwrap()
            .version(),
        1
    );
    let snapshot = follower.export_snapshot().unwrap();
    assert_eq!(snapshot.meta_snapshot.shards.get("objects-a"), Some(&shard));
    assert!(snapshot
        .meta_snapshot
        .leases
        .get("object/bucket/")
        .is_none());
    assert_eq!(follower.last_applied_index(), 5);
}

#[test]
fn raft_backed_store_applies_prepared_metaserver_leases() {
    let raft = InMemoryRustRaft::new(1).unwrap();
    let store = MatrixObjectStore::new(test_options()).unwrap();
    let mut replicated = RaftBackedObjectStore::new(raft, store);

    let prepared_acquire = replicated
        .prepare_metadata_lease_raft_entry("acquire", "object/bucket/", "writer-a", 0, 100, 10)
        .unwrap();
    assert_eq!(prepared_acquire.expected_previous_commit_index, 0);
    assert_eq!(prepared_acquire.prepared_commit_index, 1);
    assert_eq!(prepared_acquire.operation, "acquire");
    assert_eq!(prepared_acquire.lease.owner, "writer-a");
    assert!(!prepared_acquire.before_state_fingerprint.is_empty());
    assert_ne!(
        prepared_acquire.before_state_fingerprint,
        prepared_acquire.after_state_fingerprint
    );
    assert_eq!(prepared_acquire.metadata_read_index, 0);
    assert_eq!(prepared_acquire.metadata_raft_term, 1);
    assert!(!prepared_acquire.metadata_control_proof_checksum.is_empty());
    assert!(!prepared_acquire.raft_entry_checksum.is_empty());

    let mut tampered = prepared_acquire.clone();
    tampered.ttl_ms = tampered.ttl_ms.saturating_add(1);
    assert!(matches!(
        replicated
            .store()
            .clone()
            .apply_command(ObjectCommand::ApplyPreparedMetaLease { prepared: tampered }),
        Err(ObjectError::PreconditionFailed(_))
    ));

    let mut stale_proof = prepared_acquire.clone();
    stale_proof.metadata_control_proof_checksum = "stale-metadata-proof".to_string();
    assert!(matches!(
        replicated.propose_prepared_metadata_lease(stale_proof),
        Err(ObjectError::PreconditionFailed(_))
    ));

    let acquire = replicated
        .propose_prepared_metadata_lease(prepared_acquire)
        .unwrap();
    assert_eq!(acquire.content_type, "metaserver/prepared-lease");
    assert_eq!(acquire.version, 1);

    let prepared_renew = replicated
        .prepare_metadata_lease_raft_entry("renew", "object/bucket/", "writer-a", 1, 200, 20)
        .unwrap();
    assert_eq!(prepared_renew.expected_previous_commit_index, 1);
    assert!(matches!(
        MatrixObjectStore::new(test_options())
            .unwrap()
            .apply_prepared_metadata_lease(prepared_renew.clone()),
        Err(ObjectError::PreconditionFailed(_))
    ));
    let renew = replicated
        .propose_prepared_metadata_lease(prepared_renew)
        .unwrap();
    assert_eq!(renew.version, 1);
    assert_eq!(renew.update_time_ms, 20);

    let release = replicated
        .propose_release_metadata_lease_prepared("object/bucket/", "writer-a", 1)
        .unwrap();
    assert_eq!(release.content_type, "metaserver/prepared-lease");
    assert_eq!(replicated.raft_commit_index(), 3);

    let mut follower = MatrixObjectStore::new(test_options()).unwrap();
    replicated.replay_into(&mut follower).unwrap();
    assert!(follower
        .export_snapshot().unwrap()
        .meta_snapshot
        .leases
        .get("object/bucket/")
        .is_none());
    assert_eq!(follower.last_applied_index(), 3);
}

#[test]
fn raft_backed_store_dedupes_metaserver_lease_receipts_across_snapshots() {
    let raft = InMemoryRustRaft::new(1).unwrap();
    let store = MatrixObjectStore::new(test_options()).unwrap();
    let mut replicated = RaftBackedObjectStore::new(raft, store);

    let acquire = replicated
        .propose_acquire_metadata_lease_idempotent(
            "object/bucket/",
            "writer-a",
            100,
            10,
            "meta-lease-acquire-a",
        )
        .unwrap();
    assert_eq!(acquire.content_type, "metaserver/lease-acquire-idempotent");
    assert_eq!(acquire.version, 1);
    assert_eq!(acquire.update_time_ms, 10);
    let acquire_retry = replicated
        .propose_acquire_metadata_lease_idempotent(
            "object/bucket/",
            "writer-a",
            100,
            10,
            "meta-lease-acquire-a",
        )
        .unwrap();
    assert_eq!(acquire_retry.version, 1);
    assert_eq!(acquire_retry.update_time_ms, 10);
    assert!(matches!(
        replicated.propose_acquire_metadata_lease_idempotent(
            "object/bucket/",
            "writer-a",
            101,
            10,
            "meta-lease-acquire-a",
        ),
        Err(ObjectError::PreconditionFailed(_))
    ));

    let renew = replicated
        .propose_renew_metadata_lease_idempotent(
            "object/bucket/",
            "writer-a",
            1,
            200,
            20,
            "meta-lease-renew-a",
        )
        .unwrap();
    assert_eq!(renew.content_type, "metaserver/lease-renew-idempotent");
    assert_eq!(renew.update_time_ms, 20);
    let renew_retry = replicated
        .propose_renew_metadata_lease_idempotent(
            "object/bucket/",
            "writer-a",
            1,
            200,
            20,
            "meta-lease-renew-a",
        )
        .unwrap();
    assert_eq!(renew_retry.update_time_ms, 20);
    assert!(matches!(
        replicated.propose_renew_metadata_lease_idempotent(
            "object/bucket/",
            "writer-a",
            1,
            201,
            20,
            "meta-lease-renew-a",
        ),
        Err(ObjectError::PreconditionFailed(_))
    ));

    let release = replicated
        .propose_release_metadata_lease_idempotent(
            "object/bucket/",
            "writer-a",
            1,
            "meta-lease-release-a",
        )
        .unwrap();
    assert_eq!(release.content_type, "metaserver/lease-release-idempotent");
    assert_eq!(release.version, 1);
    assert!(release.deleted);
    let release_retry = replicated
        .propose_release_metadata_lease_idempotent(
            "object/bucket/",
            "writer-a",
            1,
            "meta-lease-release-a",
        )
        .unwrap();
    assert_eq!(release_retry.version, 1);
    assert!(matches!(
        replicated.propose_release_metadata_lease_idempotent(
            "object/bucket/",
            "writer-a",
            2,
            "meta-lease-release-a",
        ),
        Err(ObjectError::PreconditionFailed(_))
    ));
    assert_eq!(replicated.raft_commit_index(), 6);

    let mut follower = MatrixObjectStore::new(test_options()).unwrap();
    replicated.replay_into(&mut follower).unwrap();
    assert_eq!(follower.last_applied_index(), 6);
    let snapshot = follower.export_snapshot().unwrap();
    assert_eq!(snapshot.meta_snapshot.lease_receipts.len(), 3);
    snapshot.meta_snapshot.validate().unwrap();

    let restored_snapshot =
        MetaSnapshot::from_bytes(&snapshot.meta_snapshot.to_bytes().unwrap()).unwrap();
    let mut restored = MatrixObjectStore::new(test_options()).unwrap();
    restored
        .install_snapshot(StoreSnapshot {
            meta_snapshot: restored_snapshot,
            ..snapshot
        })
        .unwrap();
    let restored_retry = restored
        .release_metadata_lease_idempotent("object/bucket/", "writer-a", 1, "meta-lease-release-a")
        .unwrap();
    assert!(restored_retry.deduped);
    assert!(restored_retry.released);
    assert_eq!(restored_retry.lease.expire_time_ms, 220);
}

#[test]
fn raft_backed_store_applies_prepared_metaserver_lease_expiry() {
    let raft = InMemoryRustRaft::new(1).unwrap();
    let store = MatrixObjectStore::new(test_options()).unwrap();
    let mut replicated = RaftBackedObjectStore::new(raft, store);
    replicated
        .propose_acquire_metadata_lease("object/lease-expiry/a", "writer-a", 50, 10)
        .unwrap();
    replicated
        .propose_acquire_metadata_lease("object/lease-expiry/b", "writer-b", 200, 10)
        .unwrap();
    replicated
        .propose_acquire_metadata_lease("object/other/c", "writer-c", 50, 10)
        .unwrap();
    assert_eq!(replicated.raft_commit_index(), 3);

    let prepared = replicated
        .prepare_expire_metadata_leases_raft_entry("object/lease-expiry/", 100, 10)
        .unwrap();
    assert_eq!(prepared.expected_previous_commit_index, 3);
    assert_eq!(prepared.prepared_commit_index, 4);
    assert_eq!(prepared.expired.len(), 1);
    assert_eq!(prepared.expired[0].namespace, "object/lease-expiry/a");
    assert!(!prepared.metadata_control_proof_checksum.is_empty());
    assert!(!prepared.request_checksum.is_empty());
    assert!(!prepared.raft_entry_checksum.is_empty());
    assert!(replicated
        .store()
        .export_snapshot().unwrap()
        .meta_snapshot
        .leases
        .contains_key("object/lease-expiry/a"));

    let mut tampered = prepared.clone();
    tampered.expired[0].owner = "writer-z".to_string();
    assert!(matches!(
        replicated
            .store()
            .clone()
            .apply_command(ObjectCommand::ApplyPreparedMetaLeaseExpiry { prepared: tampered }),
        Err(ObjectError::Corruption(_))
    ));

    let mut stale_proof = prepared.clone();
    stale_proof.metadata_control_proof_checksum = "stale-metadata-proof".to_string();
    stale_proof.raft_entry_checksum = prepared_metadata_lease_expiry_checksum(&stale_proof);
    assert!(matches!(
        replicated
            .store()
            .clone()
            .apply_command(ObjectCommand::ApplyPreparedMetaLeaseExpiry {
                prepared: stale_proof,
            }),
        Err(ObjectError::PreconditionFailed(_))
    ));

    let applied = replicated
        .propose_prepared_metadata_lease_expiry(prepared.clone())
        .unwrap();
    assert_eq!(applied.content_type, "metaserver/prepared-lease-expire");
    assert_eq!(applied.version, 1);
    assert_eq!(replicated.raft_commit_index(), 4);
    let leader_snapshot = replicated.store().export_snapshot().unwrap();
    assert!(!leader_snapshot
        .meta_snapshot
        .leases
        .contains_key("object/lease-expiry/a"));
    assert!(leader_snapshot
        .meta_snapshot
        .leases
        .contains_key("object/lease-expiry/b"));
    assert!(leader_snapshot
        .meta_snapshot
        .leases
        .contains_key("object/other/c"));

    let mut follower = MatrixObjectStore::new(test_options()).unwrap();
    replicated.replay_into(&mut follower).unwrap();
    assert_eq!(follower.last_applied_index(), 4);
    let follower_snapshot = follower.export_snapshot().unwrap();
    assert!(!follower_snapshot
        .meta_snapshot
        .leases
        .contains_key("object/lease-expiry/a"));
    assert!(follower_snapshot
        .meta_snapshot
        .leases
        .contains_key("object/lease-expiry/b"));
    assert!(follower_snapshot
        .meta_snapshot
        .leases
        .contains_key("object/other/c"));
}

