#[test]
fn raft_backed_store_applies_prepared_metaserver_session_expiry() {
    let raft = InMemoryRustRaft::new(1).unwrap();
    let store = MatrixObjectStore::new(test_options()).unwrap();
    let mut replicated = RaftBackedObjectStore::new(raft, store);
    replicated
        .propose_register_meta_coordinator_session(
            "session-expire-a",
            "meta-a",
            "127.0.0.1:9200",
            50,
            10,
        )
        .unwrap();
    replicated
        .propose_register_meta_coordinator_session(
            "session-expire-b",
            "meta-b",
            "127.0.0.1:9201",
            200,
            10,
        )
        .unwrap();
    assert_eq!(replicated.raft_commit_index(), 2);

    let prepared = replicated
        .prepare_expire_meta_coordinator_sessions_raft_entry(100, 10)
        .unwrap();
    assert_eq!(prepared.expected_previous_commit_index, 2);
    assert_eq!(prepared.prepared_commit_index, 3);
    assert_eq!(prepared.expired.len(), 1);
    assert_eq!(prepared.expired[0].session_id, "session-expire-a");
    assert!(!prepared.metadata_control_proof_checksum.is_empty());
    assert!(!prepared.request_checksum.is_empty());
    assert!(!prepared.raft_entry_checksum.is_empty());
    let proven_envelope = replicated
        .prepare_expire_meta_coordinator_sessions_envelope_with_read_proof_linearizable(100, 10)
        .unwrap();
    assert_eq!(
        proven_envelope.proof.requested_read_index,
        replicated.raft_commit_index()
    );
    assert_eq!(proven_envelope.proof.read_fence_read_index_lag, 0);
    assert_eq!(proven_envelope.value.now_ms, 100);
    assert_eq!(proven_envelope.value.limit, 10);
    assert_eq!(proven_envelope.value.expired_session_count, 1);
    assert!(proven_envelope.value.expired_payload_bytes > 0);
    assert_eq!(proven_envelope.value.first_session_id, "session-expire-a");
    assert_eq!(proven_envelope.value.first_owner, "meta-a");
    assert_eq!(proven_envelope.value.first_epoch, 1);
    assert_eq!(proven_envelope.value.first_expire_time_ms, 60);
    assert_eq!(
        proven_envelope.value.request_checksum,
        prepared.request_checksum
    );
    assert_eq!(
        proven_envelope.value.raft_entry_checksum,
        prepared.raft_entry_checksum
    );
    assert!(!proven_envelope.value.envelope_checksum.is_empty());
    assert!(replicated
        .store()
        .meta_coordinator_session("session-expire-a")
        .is_ok());

    let mut tampered = prepared.clone();
    tampered.expired[0].endpoint = "127.0.0.1:9299".to_string();
    assert!(matches!(
        replicated.store().clone().apply_command(
            ObjectCommand::ApplyPreparedMetaCoordinatorSessionExpiry { prepared: tampered }
        ),
        Err(ObjectError::Corruption(_))
    ));

    let mut stale_proof = prepared.clone();
    stale_proof.metadata_control_proof_checksum = "stale-metadata-proof".to_string();
    stale_proof.raft_entry_checksum =
        prepared_metadata_coordinator_session_expiry_checksum(&stale_proof);
    assert!(matches!(
        replicated.store().clone().apply_command(
            ObjectCommand::ApplyPreparedMetaCoordinatorSessionExpiry {
                prepared: stale_proof,
            }
        ),
        Err(ObjectError::PreconditionFailed(_))
    ));

    let applied = replicated
        .propose_prepared_meta_coordinator_session_expiry(prepared.clone())
        .unwrap();
    assert_eq!(applied.content_type, "metaserver/prepared-session-expire");
    assert_eq!(applied.version, 1);
    assert_eq!(replicated.raft_commit_index(), 3);
    assert!(replicated
        .store()
        .meta_coordinator_session("session-expire-a")
        .is_err());
    assert!(replicated
        .store()
        .meta_coordinator_session("session-expire-b")
        .is_ok());

    let mut follower = MatrixObjectStore::new(test_options()).unwrap();
    replicated.replay_into(&mut follower).unwrap();
    assert_eq!(follower.last_applied_index(), 3);
    assert!(follower
        .meta_coordinator_session("session-expire-a")
        .is_err());
    assert!(follower
        .meta_coordinator_session("session-expire-b")
        .is_ok());
}

