#[test]
fn raft_backed_store_applies_prepared_chunk_mutation_qos() {
    let raft = InMemoryRustRaft::new(1).unwrap();
    let store = MatrixObjectStore::new(test_options()).unwrap();
    let mut replicated = RaftBackedObjectStore::new(raft, store);
    let chunk_id = ChunkId::new(0, 7020).unwrap();
    replicated
        .propose_write_page_range_idempotent(
            chunk_id.clone(),
            0,
            b"seed".to_vec(),
            "prepared-chunk-qos-seed",
        )
        .unwrap();
    let config = ReplicaMutationQosConfig {
        window_ms: 45_000,
        max_write_ops_per_window: 2,
        max_write_bytes_per_window: 2048,
        max_discard_ops_per_window: 1,
        max_discard_bytes_per_window: 1024,
    };
    let stale_route_checksum = replicated
        .store()
        .chunk_service
        .route_control_proof()
        .state_checksum;
    replicated
        .propose_configure_page_route_qos(ChunkRouteQosConfig {
            window_ms: 30_000,
            max_read_ops_per_window: 100,
            max_read_bytes_per_window: 1024 * 1024,
            max_write_ops_per_window: 100,
            max_write_bytes_per_window: 1024 * 1024,
            max_discard_ops_per_window: 100,
            max_discard_bytes_per_window: 1024 * 1024,
        })
        .unwrap();
    let current_route_checksum = replicated
        .store()
        .chunk_service
        .route_control_proof()
        .state_checksum;
    assert_ne!(stale_route_checksum, current_route_checksum);
    assert!(matches!(
        replicated.prepare_configure_chunk_mutation_qos_raft_entry_linearizable_fenced(
            config.clone(),
            Some(&stale_route_checksum),
        ),
        Err(ObjectError::PreconditionFailed(_))
    ));
    let prepared = replicated
        .prepare_configure_chunk_mutation_qos_raft_entry_linearizable_fenced(
            config.clone(),
            Some(&current_route_checksum),
        )
        .unwrap();
    assert_eq!(prepared.expected_previous_commit_index, 2);
    assert_eq!(prepared.prepared_commit_index, 3);
    assert_eq!(prepared.config, config);
    assert_eq!(
        prepared.route_control_proof.state_checksum,
        current_route_checksum
    );
    assert_eq!(
        prepared.expected_route_control_checksum,
        current_route_checksum
    );
    assert!(prepared
        .chunk_service
        .chunk_replica_mutation_qos_configs()
        .iter()
        .all(|replica_config| replica_config == &config));
    assert!(prepared
        .chunk_service
        .chunk_replica_mutation_qos_states()
        .iter()
        .all(|state| state == &ReplicaMutationQosState::default()));
    assert!(!prepared.raft_entry_checksum.is_empty());

    let mut tampered = prepared.clone();
    tampered.config.max_write_ops_per_window = 3;
    assert!(matches!(
        replicated
            .store()
            .clone()
            .apply_command(ObjectCommand::ApplyPreparedChunkMutationQos { prepared: tampered }),
        Err(ObjectError::Corruption(_))
    ));

    let applied = replicated
        .propose_prepared_chunk_mutation_qos_linearizable_fenced(
            prepared,
            Some(&current_route_checksum),
        )
        .unwrap();
    assert_eq!(
        applied.content_type,
        "chunkserver/prepared-mutation-qos-config"
    );
    assert_eq!(applied.object_id.key, "all_replicas");
    assert_eq!(applied.version, 3);
    assert_eq!(applied.length, 3);
    assert_eq!(applied.update_time_ms, 45_000);
    assert_eq!(replicated.raft_commit_index(), 3);
    assert!(replicated
        .store()
        .chunk_replica_mutation_qos_configs()
        .iter()
        .all(|replica_config| replica_config == &config));

    let mut follower = MatrixObjectStore::new(test_options()).unwrap();
    replicated.replay_into(&mut follower).unwrap();
    assert_eq!(follower.last_applied_index(), 3);
    assert!(follower
        .chunk_replica_mutation_qos_configs()
        .iter()
        .all(|replica_config| replica_config == &config));
    assert!(follower
        .chunk_replica_mutation_qos_states()
        .iter()
        .all(|state| state == &ReplicaMutationQosState::default()));
    let readiness = follower.page_storage_readiness(0, 0, 10);
    assert!(readiness
        .replica_readiness
        .iter()
        .all(|replica| replica.mutation_qos_window_ms == 45_000));
    assert!(readiness
        .replica_readiness
        .iter()
        .all(|replica| replica.control_proof.mutation_qos_max_write_ops_per_window == 2));
    assert!(readiness.replica_readiness.iter().all(|replica| {
        replica.control_proof.state_format == "MOSRSCHUNKCONTROL12"
            && replica.control_proof.chunk_mutation_control_commit_index == 3
            && replica.control_proof.chunk_mutation_control_next_log_index == 4
    }));
}

#[test]
fn raft_backed_store_replays_idempotent_page_writes() {
    let raft = InMemoryRustRaft::new(1).unwrap();
    let store = MatrixObjectStore::new(test_options()).unwrap();
    let mut replicated = RaftBackedObjectStore::new(raft, store);
    let chunk_id = ChunkId::new(0, 7000).unwrap();
    let first = replicated
        .propose_write_page_range_idempotent(
            chunk_id.clone(),
            0,
            b"abcdefgh".to_vec(),
            "raft-block-write-a",
        )
        .unwrap();
    assert_eq!(first.object_id.bucket, "_blockwrite");
    assert_eq!(first.content_type, "blockserver/idempotent-write");
    assert_eq!(first.version, 0);
    assert_eq!(first.length, 8);
    let retry = replicated
        .propose_write_page_range_idempotent(
            chunk_id.clone(),
            0,
            b"abcdefgh".to_vec(),
            "raft-block-write-a",
        )
        .unwrap();
    assert_eq!(retry.version, 1);
    assert_eq!(retry.length, 8);
    assert!(matches!(
        replicated.propose_write_page_range_idempotent(
            chunk_id.clone(),
            0,
            b"ABCDefgh".to_vec(),
            "raft-block-write-a",
        ),
        Err(ObjectError::PreconditionFailed(_))
    ));
    let second = replicated
        .propose_write_page_range_idempotent(
            chunk_id.clone(),
            8,
            b"ijkl".to_vec(),
            "raft-block-write-b",
        )
        .unwrap();
    assert_eq!(second.length, 4);
    assert_eq!(replicated.raft_commit_index(), 3);
    let (payload, _) = replicated
        .store()
        .chunk_service
        .read_chunk_range(&chunk_id, 0, 12)
        .unwrap();
    assert_eq!(payload, b"abcdefghijkl".to_vec());

    let mut follower = MatrixObjectStore::new(test_options()).unwrap();
    replicated.replay_into(&mut follower).unwrap();
    let (follower_payload, _) = follower
        .chunk_service
        .read_chunk_range(&chunk_id, 0, 12)
        .unwrap();
    assert_eq!(follower_payload, b"abcdefghijkl".to_vec());
    assert_eq!(follower.last_applied_index(), 3);
    let chunk_snapshot = follower.chunk_service.export_snapshot();
    assert_eq!(chunk_snapshot.write_request_receipts.len(), 2);
    let mut restored = MatrixObjectStore::new(test_options()).unwrap();
    restored
        .chunk_service
        .install_snapshot(chunk_snapshot)
        .unwrap();
    let restored_retry = restored
        .chunk_service
        .write_chunk_range_idempotent(&chunk_id, 0, b"abcdefgh", "raft-block-write-a")
        .unwrap();
    assert!(restored_retry.deduped);
}

