#[test]
fn raft_backed_store_gates_page_and_chunk_receipt_reads() {
    let raft = InMemoryRustRaft::new(1).unwrap();
    let store = MatrixObjectStore::new(test_options()).unwrap();
    let mut replicated = RaftBackedObjectStore::new(raft, store);
    let chunk_id = ChunkId::new(0, 7003).unwrap();
    replicated
        .propose_write_page_range_idempotent(
            chunk_id.clone(),
            0,
            b"receipt-audit".to_vec(),
            "raft-receipt-write-a",
        )
        .unwrap();
    replicated
        .propose_discard_page_range_idempotent(chunk_id.clone(), 2, 4, "raft-receipt-discard-a")
        .unwrap();

    let (page_write_page, write_readiness) = replicated
        .list_page_write_receipts_linearizable(None, 10, Some(&chunk_id), 30)
        .unwrap();
    assert_eq!(page_write_page.receipt_count, 1);
    assert_eq!(page_write_page.chunk_id, Some(chunk_id.clone()));
    assert_eq!(
        page_write_page.receipts[0].idempotency_key,
        "raft-receipt-write-a"
    );
    assert_eq!(
        write_readiness.raft_log_commit_index,
        replicated.raft_commit_index()
    );

    let (page_discard_page, _) = replicated
        .list_page_discard_receipts_linearizable(None, 10, Some(&chunk_id), 31)
        .unwrap();
    assert_eq!(page_discard_page.receipt_count, 1);
    assert_eq!(
        page_discard_page.receipts[0].idempotency_key,
        "raft-receipt-discard-a"
    );

    let page_id = PageId {
        chunk_id: chunk_id.clone(),
        page_index: 0,
    };
    let (chunk_write_page, _) = replicated
        .list_chunk_write_receipts_linearizable(0, None, 10, Some(&page_id), 32)
        .unwrap();
    assert_eq!(chunk_write_page.receipt_count, 1);
    assert_eq!(chunk_write_page.page_id, Some(page_id.clone()));
    assert!(chunk_write_page.receipts[0]
        .idempotency_key
        .starts_with("sw:"));

    let (chunk_discard_page, _) = replicated
        .list_chunk_discard_receipts_linearizable(0, None, 10, Some(&page_id), 33)
        .unwrap();
    assert_eq!(chunk_discard_page.receipt_count, 1);
    assert_eq!(chunk_discard_page.page_id, Some(page_id));
    assert!(chunk_discard_page.receipts[0]
        .idempotency_key
        .starts_with("sd:"));

    let stale = RaftBackedObjectStore::new(
        replicated.raft.clone(),
        MatrixObjectStore::new(test_options()).unwrap(),
    );
    let err = stale
        .list_page_write_receipts_linearizable(None, 10, Some(&chunk_id), 34)
        .unwrap_err();
    assert!(matches!(err, ObjectError::PreconditionFailed(_)));
    assert!(err
        .to_string()
        .contains("block write receipt read index is not satisfied"));
}

