#[test]
fn raft_backed_store_replays_prepared_page_reclaim_with_route_fence() {
    let raft = InMemoryRustRaft::new(1).unwrap();
    let store = MatrixObjectStore::new(test_options()).unwrap();
    let mut replicated = RaftBackedObjectStore::new(raft, store);
    replicated
        .propose(ObjectCommand::PutObject {
            bucket: "bucket".to_string(),
            key: "prepared-block-reclaim".to_string(),
            data: b"abcdefghijkl".to_vec(),
            content_type: "text/plain".to_string(),
            update_time_ms: 1,
            options: PutOptions::default(),
        })
        .unwrap();
    replicated
        .propose(ObjectCommand::DeleteObject {
            bucket: "bucket".to_string(),
            key: "prepared-block-reclaim".to_string(),
            update_time_ms: 2,
            if_match_etag: None,
        })
        .unwrap();
    let route_checksum = replicated
        .store()
        .chunk_service
        .route_control_proof()
        .state_checksum;
    let prepared = replicated
        .prepare_page_reclaim_raft_entry_bounded_linearizable_fenced(
            1,
            1024,
            1,
            1,
            4,
            1024,
            3,
            Some(&route_checksum),
        )
        .unwrap();
    assert_eq!(prepared.expected_previous_commit_index, 2);
    assert_eq!(prepared.prepared_commit_index, 3);
    assert_eq!(prepared.expected_route_control_checksum, route_checksum);
    assert_eq!(
        prepared.route_control_proof.state_checksum,
        prepared.expected_route_control_checksum
    );
    assert!(prepared.plan.reclaim_needed);
    assert!(prepared.plan.reclaim_can_apply);
    assert_eq!(prepared.plan.scheduled_chunks, 1);
    assert_eq!(prepared.report.reclaimed_chunks, 1);
    assert!(!prepared.raft_entry_checksum.is_empty());
    let after_prepare = replicated
        .plan_chunk_replica_reclaim_linearizable_fenced(
            None,
            1,
            1024,
            1,
            1,
            4,
            1024,
            &route_checksum,
        )
        .unwrap();
    assert!(after_prepare.candidate_chunks > 0);
    assert!(matches!(
        replicated.prepare_page_reclaim_raft_entry_bounded_linearizable_fenced(
            1,
            1024,
            1,
            1,
            4,
            1024,
            3,
            Some("stale-block-route")
        ),
        Err(ObjectError::PreconditionFailed(_))
    ));
    assert!(matches!(
        replicated.propose_prepared_page_reclaim_linearizable_fenced(
            prepared.clone(),
            None,
            &prepared.raft_entry_checksum
        ),
        Err(ObjectError::PreconditionFailed(_))
    ));
    let mut stale_checksum = prepared.clone();
    stale_checksum.raft_entry_checksum = "stale-block-reclaim-entry".to_string();
    assert!(matches!(
        replicated.propose_prepared_page_reclaim_linearizable_fenced(
            stale_checksum,
            Some(&route_checksum),
            "stale-block-reclaim-entry"
        ),
        Err(ObjectError::Corruption(_))
    ));
    let mut unfenced_prepared = prepared.clone();
    unfenced_prepared.expected_route_control_checksum.clear();
    unfenced_prepared.raft_entry_checksum = prepared_page_reclaim_checksum(&unfenced_prepared);
    assert!(matches!(
        replicated
            .store()
            .clone()
            .apply_prepared_page_reclaim(unfenced_prepared),
        Err(ObjectError::PreconditionFailed(_))
    ));
    let apply_report = replicated
        .propose_prepared_page_reclaim_linearizable_fenced_with_status(
            prepared.clone(),
            Some(&route_checksum),
            &prepared.raft_entry_checksum,
        )
        .unwrap();
    let receipt = apply_report.metadata.clone();
    assert_eq!(receipt.object_id.bucket, "_blockreclaim");
    assert_eq!(receipt.content_type, "blockserver/prepared-reclaim-more");
    assert_eq!(receipt.version, 1);
    assert_eq!(receipt.length, prepared.report.reclaimed_discard_bytes);
    assert_eq!(apply_report.mutation_id, prepared.raft_entry_checksum);
    assert_eq!(
        apply_report.mutation_request_checksum,
        prepared.raft_entry_checksum
    );
    assert_eq!(apply_report.mutation_commit_index, 3);
    assert_eq!(apply_report.next_log_index, 4);
    assert!(apply_report.committed);
    assert!(!apply_report.prepared);
    assert!(!apply_report.external_raft_required);
    assert!(!apply_report.deduped);
    assert_eq!(apply_report.report, prepared.report);
    let apply_fields = apply_report.to_control_fields("reclaim.");
    assert_eq!(
        apply_fields.get("reclaim.report.reclaimed_chunks"),
        Some(&"1".to_string())
    );
    assert_eq!(
        apply_fields.get("reclaim.report.reclaimed_discard_bytes"),
        Some(&prepared.report.reclaimed_discard_bytes.to_string())
    );
    assert_eq!(
        apply_fields.get("reclaim.metadata.content_type"),
        Some(&"blockserver/prepared-reclaim-more".to_string())
    );
    assert_eq!(replicated.raft_commit_index(), 3);
    assert!(matches!(
        replicated.propose_prepared_page_reclaim_linearizable_fenced(
            prepared,
            Some(&route_checksum),
            &receipt.etag()
        ),
        Err(ObjectError::PreconditionFailed(_))
    ));

    let mut follower = MatrixObjectStore::new(test_options()).unwrap();
    replicated.replay_into(&mut follower).unwrap();
    assert_eq!(follower.last_applied_index(), 3);
}

#[test]
fn raft_backed_store_replays_targeted_chunk_reclaim() {
    let raft = InMemoryRustRaft::new(1).unwrap();
    let store = MatrixObjectStore::new(test_options()).unwrap();
    let mut replicated = RaftBackedObjectStore::new(raft, store);
    replicated
        .propose(ObjectCommand::PutObject {
            bucket: "bucket".to_string(),
            key: "targeted-reclaim".to_string(),
            data: b"abcdefgh".to_vec(),
            content_type: "text/plain".to_string(),
            update_time_ms: 1,
            options: PutOptions::default(),
        })
        .unwrap();
    replicated
        .propose(ObjectCommand::DeleteObject {
            bucket: "bucket".to_string(),
            key: "targeted-reclaim".to_string(),
            update_time_ms: 2,
            if_match_etag: None,
        })
        .unwrap();
    let plan = replicated
        .store()
        .plan_chunk_replica_reclaim(None, 10, 6, 1, 200_000, 2, 2)
        .unwrap();
    assert_eq!(plan.scheduled_chunks, 3);
    assert_eq!(plan.scheduled_trim_ops, 3);
    assert_eq!(plan.scheduled_trim_bytes, 6);
    assert_eq!(plan.skipped_by_budget_chunks, 3);
    assert_eq!(plan.skipped_by_budget_bytes, 6);
    assert!(plan.global_reclaim_budget_enforced);
    assert_eq!(plan.global_reclaim_budget_basis, "scheduled");
    assert!(plan.reclaim_needed);
    assert!(plan.reclaim_can_apply);
    assert_eq!(plan.reclaim_reason, "blockserver_reclaim_ready");
    let route_proof = replicated.store().chunk_service.route_control_proof();
    let raft_plan = replicated
        .plan_chunk_replica_reclaim_with_read_proof_linearizable_fenced(
            None,
            10,
            6,
            1,
            200_000,
            2,
            2,
            &route_proof.state_checksum,
        )
        .unwrap();
    assert_eq!(raft_plan.value, plan);
    assert_eq!(
        raft_plan.proof.requested_storage_read_index,
        replicated.raft_commit_index()
    );
    assert_eq!(raft_plan.proof.control_checksum, route_proof.state_checksum);
    assert!(matches!(
        replicated.plan_chunk_replica_reclaim_linearizable_fenced(
            None,
            10,
            6,
            1,
            200_000,
            2,
            2,
            "stale-block-route-control"
        ),
        Err(ObjectError::PreconditionFailed(_))
    ));
    let stale_reader = RaftBackedObjectStore::new(
        replicated.raft.clone(),
        MatrixObjectStore::new(test_options()).unwrap(),
    );
    let err = stale_reader
        .plan_chunk_replica_reclaim_linearizable(None, 10, 6, 1, 200_000, 2, 2)
        .unwrap_err();
    assert!(matches!(err, ObjectError::PreconditionFailed(_)));
    assert!(err.to_string().contains("read index is not satisfied"));

    let receipt = replicated
        .propose_reclaim_chunk_replicas_with_limits(10, 6, 1, 200_000, 2, 2)
        .unwrap();
    assert_eq!(receipt.object_id.bucket, "_chunkreclaim");
    assert_eq!(receipt.content_type, "chunkserver/targeted-reclaim-more");
    assert_eq!(receipt.version, 3);
    assert_eq!(receipt.length, 12);
    assert_eq!(receipt.update_time_ms, 6);
    assert_eq!(replicated.raft_commit_index(), 3);

    let mut follower = MatrixObjectStore::new(test_options()).unwrap();
    replicated.replay_into(&mut follower).unwrap();
    let chunk1 = PageId {
        chunk_id: ChunkId::new(0, 1).unwrap(),
        page_index: 1,
    };
    assert_eq!(
        follower.chunk_service.replicas[0]
            .read_chunk_state(&chunk1)
            .unwrap()
            .logical_length,
        2
    );
    assert!(follower.chunk_service.replicas[0]
        .read_chunk_state(&chunk1)
        .unwrap()
        .discarded_ranges
        .is_empty());
    assert_eq!(follower.last_applied_index(), 3);
}

#[test]
fn raft_backed_store_replays_prepared_chunk_reclaim_with_compact_fences() {
    let raft = InMemoryRustRaft::new(1).unwrap();
    let store = MatrixObjectStore::new(test_options()).unwrap();
    let mut replicated = RaftBackedObjectStore::new(raft, store);
    replicated
        .propose(ObjectCommand::PutObject {
            bucket: "bucket".to_string(),
            key: "prepared-reclaim".to_string(),
            data: b"abcdefgh".to_vec(),
            content_type: "text/plain".to_string(),
            update_time_ms: 1,
            options: PutOptions::default(),
        })
        .unwrap();
    replicated
        .propose(ObjectCommand::DeleteObject {
            bucket: "bucket".to_string(),
            key: "prepared-reclaim".to_string(),
            update_time_ms: 2,
            if_match_etag: None,
        })
        .unwrap();
    let stale_route_checksum = replicated
        .store()
        .chunk_service
        .route_control_proof()
        .state_checksum;
    replicated
        .propose_configure_page_route_qos(ChunkRouteQosConfig {
            window_ms: 30_000,
            max_read_ops_per_window: 100,
            max_read_bytes_per_window: 1024 * 1024,
            max_write_ops_per_window: 100,
            max_write_bytes_per_window: 1024 * 1024,
            max_discard_ops_per_window: 100,
            max_discard_bytes_per_window: 1024 * 1024,
        })
        .unwrap();
    let current_route_checksum = replicated
        .store()
        .chunk_service
        .route_control_proof()
        .state_checksum;
    assert_ne!(stale_route_checksum, current_route_checksum);
    assert!(matches!(
        replicated.prepare_reclaim_chunk_replica_raft_entry_bounded_fenced(
            0,
            10,
            6,
            1,
            200_000,
            2,
            2,
            12,
            &stale_route_checksum,
        ),
        Err(ObjectError::PreconditionFailed(_))
    ));
    let proven_prepared = replicated
        .prepare_reclaim_chunk_replica_raft_entry_bounded_with_read_proof_linearizable_fenced(
            0,
            10,
            6,
            1,
            200_000,
            2,
            2,
            12,
            &current_route_checksum,
        )
        .unwrap();
    assert_eq!(proven_prepared.proof.requested_storage_read_index, 3);
    assert_eq!(proven_prepared.proof.storage_applied_index, 3);
    assert_eq!(proven_prepared.proof.control_kind, "block-route");
    assert_eq!(
        proven_prepared.proof.control_checksum,
        current_route_checksum
    );
    let prepared = proven_prepared.value;
    assert_eq!(prepared.replica_index, 0);
    assert_eq!(
        prepared.route_control_proof.state_checksum,
        current_route_checksum
    );
    assert_eq!(
        prepared.expected_route_control_checksum,
        current_route_checksum
    );
    let default_prepared = replicated
        .prepare_reclaim_chunk_replica_raft_entry(0, 10, 6, 1, 200_000, 2, 2, 12)
        .unwrap();
    assert_eq!(
        default_prepared.expected_route_control_checksum,
        current_route_checksum
    );
    assert!(!prepared.before_replica_service_fingerprint.is_empty());
    assert!(!prepared.after_replica_service_fingerprint.is_empty());
    assert_ne!(
        prepared.before_replica_service_fingerprint,
        prepared.after_replica_service_fingerprint
    );
    let reclaim_envelope = replicated
        .prepare_reclaim_chunk_replica_envelope_with_read_proof_linearizable_fenced(
            0,
            10,
            6,
            1,
            200_000,
            2,
            2,
            12,
            &current_route_checksum,
        )
        .unwrap();
    assert_eq!(
        reclaim_envelope.envelope.envelope_format,
        "MXOSCHUNK-RECLAIM-ENVELOPE1"
    );
    assert_eq!(
        reclaim_envelope.envelope.plan_checksum,
        prepared.plan.plan_checksum
    );
    assert_eq!(
        reclaim_envelope.envelope.raft_entry_checksum,
        prepared.raft_entry_checksum
    );
    assert_eq!(
        reclaim_envelope.envelope.route_control_proof_checksum,
        current_route_checksum
    );
    assert_eq!(reclaim_envelope.envelope.replica_index, 0);
    assert_eq!(
        reclaim_envelope.envelope.scheduled_reclaim_chunks,
        prepared.plan.scheduled_chunks
    );
    assert_eq!(
        reclaim_envelope.envelope.reclaimed_chunks,
        prepared.report.reclaimed_chunks
    );
    assert!(reclaim_envelope.envelope.first_reclaim_chunk_id.is_some());
    assert!(!reclaim_envelope.envelope.envelope_checksum.is_empty());
    assert_eq!(
        reclaim_envelope.proof.control_checksum,
        current_route_checksum
    );
    assert!(matches!(
        replicated.propose_prepared_reclaim_chunk_replica(1, prepared.clone()),
        Err(ObjectError::PreconditionFailed(_))
    ));
    assert!(matches!(
        replicated.propose_prepared_reclaim_chunk_replica_fenced(0, prepared.clone(), ""),
        Err(ObjectError::PreconditionFailed(_))
    ));
    let mut unfenced_prepared = prepared.clone();
    unfenced_prepared.expected_route_control_checksum.clear();
    unfenced_prepared.raft_entry_checksum = prepared_chunk_reclaim_checksum(&unfenced_prepared);
    assert!(matches!(
        replicated
            .store()
            .clone()
            .apply_prepared_chunk_reclaim(0, unfenced_prepared.clone()),
        Err(ObjectError::PreconditionFailed(_))
    ));
    assert!(matches!(
        replicated.propose_prepared_reclaim_chunk_replica_fenced(
            0,
            unfenced_prepared,
            &current_route_checksum,
        ),
        Err(ObjectError::PreconditionFailed(_))
    ));
    let apply_report = replicated
        .propose_prepared_reclaim_chunk_replica_fenced_with_status(
            0,
            prepared.clone(),
            &current_route_checksum,
        )
        .unwrap();
    let receipt = apply_report.metadata.clone();
    assert_eq!(receipt.object_id.bucket, "_chunkreclaim");
    assert_eq!(receipt.content_type, "chunkserver/prepared-reclaim");
    assert_eq!(receipt.version, 2);
    assert_eq!(receipt.length, 8);
    assert_eq!(apply_report.mutation_id, prepared.raft_entry_checksum);
    assert_eq!(
        apply_report.mutation_request_checksum,
        prepared.raft_entry_checksum
    );
    assert_eq!(apply_report.mutation_commit_index, 4);
    assert_eq!(apply_report.next_log_index, 5);
    assert!(apply_report.committed);
    assert!(!apply_report.prepared);
    assert!(!apply_report.external_raft_required);
    assert!(!apply_report.deduped);
    assert_eq!(apply_report.replica_index, 0);
    assert_eq!(apply_report.report, prepared.report);
    let apply_fields = apply_report.to_control_fields("chunk_reclaim.");
    assert_eq!(
        apply_fields.get("chunk_reclaim.replica_index"),
        Some(&"0".to_string())
    );
    assert_eq!(
        apply_fields.get("chunk_reclaim.report.reclaimed_chunks"),
        Some(&prepared.report.reclaimed_chunks.to_string())
    );
    assert_eq!(
        apply_fields.get("chunk_reclaim.report.reclaimed_discard_bytes"),
        Some(&prepared.report.reclaimed_discard_bytes.to_string())
    );
    assert_eq!(
        apply_fields.get("chunk_reclaim.metadata.content_type"),
        Some(&"chunkserver/prepared-reclaim".to_string())
    );
    assert_eq!(replicated.raft_commit_index(), 4);

    let mut follower = MatrixObjectStore::new(test_options()).unwrap();
    replicated.replay_into(&mut follower).unwrap();
    let chunk1 = PageId {
        chunk_id: ChunkId::new(0, 1).unwrap(),
        page_index: 1,
    };
    assert_eq!(
        follower.chunk_service.replicas[0]
            .read_chunk_state(&chunk1)
            .unwrap()
            .logical_length,
        2
    );
    assert_eq!(follower.last_applied_index(), 4);
}

#[test]
fn raft_backed_store_replays_storage_maintenance() {
    let raft = InMemoryRustRaft::new(1).unwrap();
    let store = MatrixObjectStore::new(test_options()).unwrap();
    let mut replicated = RaftBackedObjectStore::new(raft, store);
    replicated
        .propose(ObjectCommand::PutObject {
            bucket: "bucket".to_string(),
            key: "storage-maintenance".to_string(),
            data: b"abcdefghijklmnop".to_vec(),
            content_type: "text/plain".to_string(),
            update_time_ms: 1,
            options: PutOptions::default(),
        })
        .unwrap();
    replicated
        .propose(ObjectCommand::DeleteObject {
            bucket: "bucket".to_string(),
            key: "storage-maintenance".to_string(),
            update_time_ms: 2,
            if_match_etag: None,
        })
        .unwrap();
    let plan = replicated
        .plan_storage_maintenance_linearizable(32, 0, 1, 32, 1024, 1, 1, 4, 1024, 3)
        .unwrap();
    assert!(plan.reclaim_pressure);
    assert!(plan
        .actions
        .iter()
        .any(|action| action.action == "reclaim_discarded_chunk"));
    assert!(!plan.plan_checksum.is_empty());
    assert!(!plan.readiness.route_control_proof.state_checksum.is_empty());
    let envelope = replicated
        .prepare_storage_maintenance_envelope_with_read_proof_linearizable_with_control_fence(
            32,
            0,
            1,
            32,
            1024,
            1,
            1,
            4,
            1024,
            3,
            &plan.readiness.route_control_proof.state_checksum,
        )
        .unwrap();
    assert_eq!(
        envelope.envelope.envelope_format,
        "MXOSBLOCK-STORAGE-MAINTENANCE-ENVELOPE1"
    );
    assert_eq!(envelope.envelope.plan_checksum, plan.plan_checksum);
    assert_eq!(
        envelope.envelope.route_control_proof_checksum,
        plan.readiness.route_control_proof.state_checksum
    );
    assert_eq!(
        envelope.envelope.selected_action_count,
        plan.actions.len() as u64
    );
    assert!(envelope.envelope.planned_reclaim_chunks > 0);
    assert_eq!(
        envelope.envelope.scheduled_reclaim_chunks,
        plan.reclaim.scheduled_chunks
    );
    assert!(envelope.envelope.scheduled_reclaim_chunks > 0);
    assert_eq!(envelope.envelope.first_action, "reclaim_discarded_chunk");
    assert!(envelope.envelope.first_chunk_id.is_some());
    assert!(!envelope.envelope.envelope_checksum.is_empty());
    assert_eq!(
        envelope.proof.control_checksum,
        plan.readiness.route_control_proof.state_checksum
    );
    assert!(matches!(
        replicated.plan_storage_maintenance_linearizable_with_control_fence(
            32,
            0,
            1,
            32,
            1024,
            1,
            1,
            4,
            1024,
            3,
            "stale-block-route-control"
        ),
        Err(ObjectError::PreconditionFailed(_))
    ));
    assert!(matches!(
        replicated.propose_run_storage_maintenance_linearizable_fenced(
            32,
            0,
            1,
            32,
            1024,
            1,
            1,
            4,
            1024,
            3,
            "stale-storage-maintenance-plan"
        ),
        Err(ObjectError::InvalidArgument(_))
    ));
    let receipt = replicated
        .propose_run_storage_maintenance_linearizable_with_control_fence(
            32,
            0,
            1,
            32,
            1024,
            1,
            1,
            4,
            1024,
            3,
            &plan.readiness.route_control_proof.state_checksum,
            &plan.plan_checksum,
        )
        .unwrap();
    assert_eq!(receipt.object_id.bucket, "_storagemaintenance");
    assert_eq!(receipt.content_type, "storage/maintenance-reclaim");
    assert!(receipt.version > 0);
    assert!(receipt.length > 0);
    assert_eq!(replicated.raft_commit_index(), 3);

    let mut follower = MatrixObjectStore::new(test_options()).unwrap();
    replicated.replay_into(&mut follower).unwrap();
    let readiness = follower.page_storage_readiness(0, 1, 4);
    assert_eq!(readiness.total_reclaimable_bytes, 0);
    assert_eq!(follower.last_applied_index(), 3);
}

#[test]
fn raft_backed_storage_maintenance_repairs_degraded_chunks() {
    let raft = InMemoryRustRaft::new(1).unwrap();
    let store = MatrixObjectStore::new(test_options()).unwrap();
    let mut replicated = RaftBackedObjectStore::new(raft, store);
    let written = replicated
        .propose(ObjectCommand::PutObject {
            bucket: "bucket".to_string(),
            key: "storage-maintenance-repair".to_string(),
            data: b"abcdefghijkl".to_vec(),
            content_type: "text/plain".to_string(),
            update_time_ms: 1,
            options: PutOptions::default(),
        })
        .unwrap();
    let first_chunk = replicated
        .store()
        .chunk_service
        .map_range(
            &written.extents[0].chunk_id,
            written.extents[0].offset(),
            written.length,
        )
        .unwrap()[0]
        .page_id
        .clone();
    replicated
        .store
        .chunk_service
        .remove_replica_chunk_for_repair(0, &first_chunk)
        .unwrap();
    let degraded = replicated
        .store
        .chunk_service
        .scrub_chunk_replicas(false)
        .unwrap();
    assert!(degraded.degraded_chunks > 0);

    let receipt = replicated
        .propose_run_storage_maintenance(4, 0, 0, 4, 1024, 1, 1, 4, 1024, 2)
        .unwrap();
    assert_eq!(receipt.object_id.bucket, "_storagemaintenance");
    assert_eq!(receipt.content_type, "storage/maintenance-repair");
    assert_eq!(receipt.version, 1);
    assert_eq!(receipt.length, 1);
    assert_eq!(replicated.raft_commit_index(), 2);
    let repaired = replicated
        .store
        .chunk_service
        .scrub_chunk_replicas(false)
        .unwrap();
    assert_eq!(repaired.degraded_chunks, 0);

    let mut follower = MatrixObjectStore::new(test_options()).unwrap();
    replicated.replay_into(&mut follower).unwrap();
    assert_eq!(
        follower
            .get_object("bucket", "storage-maintenance-repair")
            .unwrap()
            .data,
        b"abcdefghijkl".to_vec()
    );
    assert_eq!(follower.last_applied_index(), 2);
}

#[test]
fn raft_backed_store_replays_chunk_trim_flow_throttling() {
    let raft = InMemoryRustRaft::new(1).unwrap();
    let store = MatrixObjectStore::new(test_options()).unwrap();
    let mut replicated = RaftBackedObjectStore::new(raft, store);
    replicated
        .propose(ObjectCommand::PutObject {
            bucket: "bucket".to_string(),
            key: "trim-flow".to_string(),
            data: b"abcdefgh".to_vec(),
            content_type: "text/plain".to_string(),
            update_time_ms: 1,
            options: PutOptions::default(),
        })
        .unwrap();
    replicated
        .propose(ObjectCommand::DeleteObject {
            bucket: "bucket".to_string(),
            key: "trim-flow".to_string(),
            update_time_ms: 2,
            if_match_etag: None,
        })
        .unwrap();
    let configured = replicated
        .propose_configure_chunk_trim_flow(1, 2, 1_000)
        .unwrap();
    assert_eq!(configured.content_type, "chunkserver/trim-flow");
    assert_eq!(configured.object_id.bucket, "_chunktrimflow");
    assert_eq!(configured.object_id.key, "all_replicas");
    assert_eq!(configured.length, 3);
    let receipt = replicated
        .propose(ObjectCommand::ReclaimChunkReplicasWithLimits {
            max_chunks: 10,
            max_rewrite_bytes: 8,
            min_discarded_bytes: 1,
            min_discard_ratio_ppm: 0,
            max_discard_ranges: 0,
            max_trim_bytes: 4,
            now_ms: 1_000,
        })
        .unwrap();
    assert_eq!(
        receipt.content_type,
        "chunkserver/targeted-reclaim-throttled"
    );
    assert_eq!(replicated.raft_commit_index(), 4);

    let mut follower = MatrixObjectStore::new(test_options()).unwrap();
    replicated.replay_into(&mut follower).unwrap();
    let page_id = PageId {
        chunk_id: ChunkId::new(0, 1).unwrap(),
        page_index: 0,
    };
    let follower_replica = &follower.chunk_service.replicas[0];
    assert_eq!(follower_replica.trim_flow_rate_bytes_per_sec(), 1);
    assert_eq!(follower_replica.trim_flow_burst_bytes(), 2);
    assert_eq!(follower_replica.trim_flow_available_bytes(), 0);
    assert_eq!(follower_replica.trim_flow_throttled_reclaims(), 1);
    assert_eq!(follower_replica.trim_flow_throttled_bytes(), 2);
    assert_eq!(
        follower_replica
            .read_chunk_state(&page_id)
            .unwrap()
            .logical_length,
        2
    );
    assert_eq!(follower.last_applied_index(), 4);
}

