#[test]
fn raft_backed_store_replays_page_chunk_endpoint_topology() {
    let raft = InMemoryRustRaft::new(1).unwrap();
    let store = MatrixObjectStore::new(test_options()).unwrap();
    let mut replicated = RaftBackedObjectStore::new(raft, store);
    let mut disabled = BTreeSet::new();
    disabled.insert(2);

    let configured = replicated
        .propose_configure_page_chunk_endpoints(
            vec![
                "chunk-a:9100".to_string(),
                "chunk-b:9100".to_string(),
                "chunk-c:9100".to_string(),
            ],
            disabled.clone(),
            2,
            2,
        )
        .unwrap();
    assert_eq!(configured.content_type, "blockserver/chunk-endpoints");
    assert_eq!(configured.version, 3);
    assert_eq!(configured.length, 1);
    let ready = replicated.store().page_storage_readiness(0, 0, 1);
    assert_eq!(ready.chunk_endpoint_count, 3);
    assert_eq!(ready.disabled_chunk_endpoint_count, 1);
    assert_eq!(ready.effective_writable_chunk_endpoints, 2);
    assert_eq!(ready.route_control_proof.state_format, "MOSRSBLOCKROUTE10");
    assert_eq!(ready.route_control_proof.chunk_endpoint_count, 3);
    assert_eq!(ready.route_control_proof.disabled_chunk_endpoint_count, 1);
    assert_eq!(
        replicated.store().chunk_service.chunk_endpoints(),
        &[
            "chunk-a:9100".to_string(),
            "chunk-b:9100".to_string(),
            "chunk-c:9100".to_string()
        ]
    );
    assert_eq!(
        replicated
            .store()
            .chunk_service
            .disabled_chunk_endpoint_indices(),
        vec![2]
    );
    replicated
        .propose(ObjectCommand::PutObject {
            bucket: "bucket".to_string(),
            key: "endpoint-disabled-write".to_string(),
            data: b"endpoint-data".to_vec(),
            content_type: "text/plain".to_string(),
            update_time_ms: 2,
            options: PutOptions::default(),
        })
        .unwrap();
    assert_eq!(
        replicated
            .store()
            .get_object("bucket", "endpoint-disabled-write")
            .unwrap()
            .data,
        b"endpoint-data".to_vec()
    );
    assert_eq!(
        replicated
            .store()
            .chunk_service
            .chunk_replica_physical_write_count(),
        vec![4, 4, 0]
    );
    assert!(matches!(
        replicated.store().chunk_service.replicas[2].read_chunk_state(&PageId {
            chunk_id: ChunkId::new(0, 1).unwrap(),
            page_index: 0,
        }),
        Err(ObjectError::NotFound(_))
    ));
    assert!(replicated
        .propose_configure_page_chunk_endpoints(
            vec![
                "chunk-a:9100".to_string(),
                "chunk-b:9100".to_string(),
                "chunk-c:9100".to_string(),
            ],
            BTreeSet::from([1usize, 2usize]),
            2,
            2,
        )
        .is_err());

    let mut follower = MatrixObjectStore::new(test_options()).unwrap();
    replicated.replay_into(&mut follower).unwrap();
    assert_eq!(follower.last_applied_index(), 2);
    assert_eq!(
        follower
            .get_object("bucket", "endpoint-disabled-write")
            .unwrap()
            .data,
        b"endpoint-data".to_vec()
    );
    assert_eq!(
        follower.chunk_service.chunk_replica_physical_write_count(),
        vec![4, 4, 0]
    );
    assert_eq!(
        follower.chunk_service.chunk_endpoints(),
        replicated.store().chunk_service.chunk_endpoints()
    );
    assert_eq!(
        follower.chunk_service.disabled_chunk_endpoint_indices(),
        vec![2]
    );
    let restored_snapshot =
        StoreSnapshot::from_bytes(&follower.export_snapshot().unwrap().to_bytes().unwrap()).unwrap();
    let mut restored = MatrixObjectStore::new(test_options()).unwrap();
    restored.install_snapshot(restored_snapshot).unwrap();
    assert_eq!(
        restored.chunk_service.chunk_endpoints(),
        replicated.store().chunk_service.chunk_endpoints()
    );
    assert_eq!(
        restored.chunk_service.disabled_chunk_endpoint_indices(),
        vec![2]
    );
}

#[test]
fn raft_backed_store_replays_metaserver_transactions() {
    let raft = InMemoryRustRaft::new(1).unwrap();
    let store = MatrixObjectStore::new(test_options()).unwrap();
    let mut replicated = RaftBackedObjectStore::new(raft, store);
    replicated
        .propose_begin_meta_transaction(
            "txn/commit",
            "owner-a",
            100,
            vec![MetadataMutation {
                key: "object/meta/a".to_string().into(),
                record_value: ("value-a".to_string()).into(),
                expected_version: 0,
                delete: false,
            }],
            10,
        )
        .unwrap();
    let committed = replicated
        .propose_commit_meta_transaction("txn/commit", "owner-a", 11)
        .unwrap();
    assert_eq!(committed.content_type, "metaserver/transaction-commit");
    replicated
        .propose_begin_meta_transaction(
            "txn/abort",
            "owner-b",
            100,
            vec![MetadataMutation {
                key: "object/meta/b".to_string().into(),
                record_value: ("value-b".to_string()).into(),
                expected_version: 0,
                delete: false,
            }],
            12,
        )
        .unwrap();
    replicated
        .propose_abort_meta_transaction("txn/abort", "owner-b", 13)
        .unwrap();
    replicated
        .propose_begin_meta_transaction(
            "txn/expire",
            "owner-c",
            1,
            vec![MetadataMutation {
                key: "object/meta/c".to_string().into(),
                record_value: ("value-c".to_string()).into(),
                expected_version: 0,
                delete: false,
            }],
            14,
        )
        .unwrap();
    let expired = replicated.propose_expire_meta_transactions(16).unwrap();
    assert_eq!(expired.length, 1);
    assert_eq!(replicated.raft_commit_index(), 6);

    let mut follower = MatrixObjectStore::new(test_options()).unwrap();
    replicated.replay_into(&mut follower).unwrap();
    assert_eq!(
        follower.metadata_record("object/meta/a").unwrap().value,
        "value-a".into()
    );
    assert!(matches!(
        follower.metadata_record("object/meta/b"),
        Err(ObjectError::NotFound(_))
    ));
    assert!(matches!(
        follower.metadata_record("object/meta/c"),
        Err(ObjectError::NotFound(_))
    ));
    let snapshot = follower.export_snapshot().unwrap();
    assert_eq!(
        snapshot
            .meta_snapshot
            .transactions
            .get("txn/commit")
            .unwrap()
            .state,
        "committed"
    );
    assert_eq!(
        snapshot
            .meta_snapshot
            .transactions
            .get("txn/abort")
            .unwrap()
            .state,
        "aborted"
    );
    assert_eq!(
        snapshot
            .meta_snapshot
            .transactions
            .get("txn/expire")
            .unwrap()
            .state,
        "expired"
    );
    assert_eq!(follower.last_applied_index(), 6);
}

#[test]
fn raft_backed_store_dedupes_metaserver_transaction_receipts_across_snapshots() {
    let raft = InMemoryRustRaft::new(1).unwrap();
    let store = MatrixObjectStore::new(test_options()).unwrap();
    let mut replicated = RaftBackedObjectStore::new(raft, store);
    let mutations = vec![MetadataMutation {
        key: "object/meta/txn-receipt".to_string().into(),
        record_value: ("value-a".to_string()).into(),
        expected_version: 0,
        delete: false,
    }];
    let begin = replicated
        .propose_begin_meta_transaction_idempotent(
            "txn/receipt",
            "owner-a",
            100,
            mutations.clone(),
            10,
            "txn-begin-a",
        )
        .unwrap();
    assert_eq!(
        begin.content_type,
        "metaserver/transaction-begin-idempotent"
    );
    let begin_retry = replicated
        .propose_begin_meta_transaction_idempotent(
            "txn/receipt",
            "owner-a",
            100,
            mutations.clone(),
            10,
            "txn-begin-a",
        )
        .unwrap();
    assert_eq!(
        begin_retry.content_type,
        "metaserver/transaction-begin-idempotent-deduped"
    );
    let renew = replicated
        .propose_renew_meta_transaction_idempotent("txn/receipt", "owner-a", 200, 11, "txn-renew-a")
        .unwrap();
    assert_eq!(
        renew.content_type,
        "metaserver/transaction-renew-idempotent"
    );
    let renew_retry = replicated
        .propose_renew_meta_transaction_idempotent("txn/receipt", "owner-a", 200, 11, "txn-renew-a")
        .unwrap();
    assert_eq!(
        renew_retry.content_type,
        "metaserver/transaction-renew-idempotent-deduped"
    );
    assert!(matches!(
        replicated.propose_renew_meta_transaction_idempotent(
            "txn/receipt",
            "owner-a",
            201,
            11,
            "txn-renew-a",
        ),
        Err(ObjectError::PreconditionFailed(_))
    ));
    assert_eq!(
        replicated
            .store()
            .meta_service
            .export_snapshot()
            .transactions
            .get("txn/receipt")
            .unwrap()
            .expire_time_ms,
        211
    );
    assert!(matches!(
        replicated.propose_begin_meta_transaction_idempotent(
            "txn/receipt-conflict",
            "owner-a",
            100,
            mutations.clone(),
            10,
            "txn-begin-a",
        ),
        Err(ObjectError::PreconditionFailed(_))
    ));
    let commit = replicated
        .propose_commit_meta_transaction_idempotent("txn/receipt", "owner-a", 12, "txn-commit-a")
        .unwrap();
    assert_eq!(
        commit.content_type,
        "metaserver/transaction-commit-idempotent"
    );
    let commit_retry = replicated
        .propose_commit_meta_transaction_idempotent("txn/receipt", "owner-a", 12, "txn-commit-a")
        .unwrap();
    assert_eq!(
        commit_retry.content_type,
        "metaserver/transaction-commit-idempotent-deduped"
    );

    replicated
        .propose_begin_meta_transaction_idempotent(
            "txn/abort-receipt",
            "owner-b",
            100,
            vec![MetadataMutation {
                key: "object/meta/txn-abort".to_string().into(),
                record_value: ("value-b".to_string()).into(),
                expected_version: 0,
                delete: false,
            }],
            12,
            "txn-abort-begin",
        )
        .unwrap();
    let abort = replicated
        .propose_abort_meta_transaction_idempotent(
            "txn/abort-receipt",
            "owner-b",
            13,
            "txn-abort-a",
        )
        .unwrap();
    assert_eq!(
        abort.content_type,
        "metaserver/transaction-abort-idempotent"
    );
    let abort_retry = replicated
        .propose_abort_meta_transaction_idempotent(
            "txn/abort-receipt",
            "owner-b",
            13,
            "txn-abort-a",
        )
        .unwrap();
    assert_eq!(
        abort_retry.content_type,
        "metaserver/transaction-abort-idempotent-deduped"
    );
    assert_eq!(replicated.raft_commit_index(), 9);
    assert_eq!(
        replicated
            .store()
            .metadata_raft_readiness(0, 20)
            .transaction_receipt_count,
        5
    );

    let snapshot = replicated.store().export_snapshot().unwrap();
    assert_eq!(snapshot.meta_snapshot.transaction_receipts.len(), 5);
    let restored_meta_snapshot =
        MetaSnapshot::from_bytes(&snapshot.meta_snapshot.to_bytes().unwrap()).unwrap();
    assert_eq!(restored_meta_snapshot.transaction_receipts.len(), 5);
    let mut restored = MatrixObjectStore::new(test_options()).unwrap();
    restored
        .install_snapshot(StoreSnapshot {
            meta_snapshot: restored_meta_snapshot,
            ..snapshot.clone()
        })
        .unwrap();
    let restored_retry = restored
        .commit_metadata_transaction_idempotent("txn/receipt", "owner-a", 12, "txn-commit-a")
        .unwrap();
    assert!(restored_retry.deduped);
    assert_eq!(restored_retry.records.len(), 1);
    assert_eq!(
        restored
            .metadata_record("object/meta/txn-receipt")
            .unwrap()
            .value,
        "value-a".into()
    );

    let metadata_commit_floor = restored
        .meta_service
        .export_snapshot()
        .next_commit_index
        .saturating_sub(1);
    let report = restored
        .compact_metadata_snapshot_retention(metadata_commit_floor, 0, usize::MAX)
        .unwrap();
    assert_eq!(report.compacted_transaction_receipts, 5);
    assert_eq!(report.remaining_transaction_receipts, 0);

    let mut follower = MatrixObjectStore::new(test_options()).unwrap();
    replicated.replay_into(&mut follower).unwrap();
    assert_eq!(
        follower
            .metadata_record("object/meta/txn-receipt")
            .unwrap()
            .value,
        "value-a".into()
    );
    assert_eq!(
        follower
            .metadata_raft_readiness(0, 20)
            .transaction_receipt_count,
        5
    );
    assert_eq!(follower.last_applied_index(), 9);
}

#[test]
fn raft_backed_store_replays_metaserver_transaction_gc() {
    let raft = InMemoryRustRaft::new(1).unwrap();
    let store = MatrixObjectStore::new(test_options()).unwrap();
    let mut replicated = RaftBackedObjectStore::new(raft, store);
    replicated
        .propose_begin_meta_transaction(
            "txn/commit",
            "owner-a",
            100,
            vec![MetadataMutation {
                key: "object/meta/a".to_string().into(),
                record_value: ("value-a".to_string()).into(),
                expected_version: 0,
                delete: false,
            }],
            10,
        )
        .unwrap();
    replicated
        .propose_commit_meta_transaction("txn/commit", "owner-a", 11)
        .unwrap();
    replicated
        .propose_begin_meta_transaction(
            "txn/abort",
            "owner-b",
            100,
            vec![MetadataMutation {
                key: "object/meta/b".to_string().into(),
                record_value: ("value-b".to_string()).into(),
                expected_version: 0,
                delete: false,
            }],
            12,
        )
        .unwrap();
    replicated
        .propose_abort_meta_transaction("txn/abort", "owner-b", 13)
        .unwrap();
    replicated
        .propose_begin_meta_transaction(
            "txn/pending",
            "owner-c",
            100,
            vec![MetadataMutation {
                key: "object/meta/c".to_string().into(),
                record_value: ("value-c".to_string()).into(),
                expected_version: 0,
                delete: false,
            }],
            14,
        )
        .unwrap();

    let first_gc = replicated.propose_gc_meta_transactions(20, 1, 0).unwrap();
    assert_eq!(first_gc.content_type, "metaserver/transaction-gc");
    assert_eq!(first_gc.version, 1);
    assert_eq!(first_gc.length, 1);
    let second_gc = replicated.propose_gc_meta_transactions(20, 10, 0).unwrap();
    assert_eq!(second_gc.version, 1);
    assert_eq!(second_gc.length, 1);
    assert_eq!(replicated.raft_commit_index(), 7);

    let mut follower = MatrixObjectStore::new(test_options()).unwrap();
    replicated.replay_into(&mut follower).unwrap();
    assert_eq!(
        follower.metadata_record("object/meta/a").unwrap().value,
        "value-a".into()
    );
    let snapshot = follower.export_snapshot().unwrap();
    assert!(!snapshot
        .meta_snapshot
        .transactions
        .contains_key("txn/commit"));
    assert!(!snapshot
        .meta_snapshot
        .transactions
        .contains_key("txn/abort"));
    assert_eq!(
        snapshot
            .meta_snapshot
            .transactions
            .get("txn/pending")
            .unwrap()
            .state,
        "pending"
    );
    assert_eq!(follower.last_applied_index(), 7);
}

#[test]
fn metaserver_pages_metadata_transactions_with_filters() {
    let mut store = MatrixObjectStore::new(test_options()).unwrap();
    store
        .begin_metadata_transaction(
            "txn/a-active",
            "owner-a",
            100,
            vec![MetadataMutation {
                key: "object/meta/list-a".to_string().into(),
                record_value: ("value-a".to_string()).into(),
                expected_version: 0,
                delete: false,
            }],
            10,
        )
        .unwrap();
    store
        .begin_metadata_transaction(
            "txn/b-commit",
            "owner-b",
            100,
            vec![MetadataMutation {
                key: "object/meta/list-b".to_string().into(),
                record_value: ("value-b".to_string()).into(),
                expected_version: 0,
                delete: false,
            }],
            11,
        )
        .unwrap();
    store
        .commit_metadata_transaction("txn/b-commit", "owner-b", 12)
        .unwrap();
    store
        .begin_metadata_transaction(
            "txn/c-expired",
            "owner-c",
            1,
            vec![MetadataMutation {
                key: "object/meta/list-c".to_string().into(),
                record_value: ("value-c".to_string()).into(),
                expected_version: 0,
                delete: false,
            }],
            13,
        )
        .unwrap();

    assert_eq!(
        store.metadata_transaction("txn/b-commit").unwrap().state,
        "committed"
    );
    let first = store
        .list_metadata_transactions("txn/", None, 1, true, None, None, false, 20)
        .unwrap();
    assert_eq!(first.transactions.len(), 1);
    assert!(first.truncated);
    assert_eq!(first.transactions[0].transaction_id, "txn/a-active");
    let second = store
        .list_metadata_transactions(
            "txn/",
            first.next_marker.as_deref(),
            10,
            true,
            None,
            None,
            false,
            20,
        )
        .unwrap();
    assert_eq!(second.transactions.len(), 2);
    assert_eq!(second.transactions[0].transaction_id, "txn/b-commit");
    assert_eq!(second.transactions[1].transaction_id, "txn/c-expired");
    assert!(!second.truncated);

    let active_only = store
        .list_metadata_transactions("txn/", None, 10, false, None, None, false, 20)
        .unwrap();
    assert_eq!(active_only.transactions.len(), 2);
    assert_eq!(active_only.skipped_terminal_count, 1);
    let owner_filtered = store
        .list_metadata_transactions(
            "txn/",
            None,
            10,
            true,
            Some("owner-b"),
            Some("committed"),
            false,
            20,
        )
        .unwrap();
    assert_eq!(owner_filtered.transactions.len(), 1);
    assert_eq!(
        owner_filtered.transactions[0].transaction_id,
        "txn/b-commit"
    );
    let expired = store
        .list_metadata_transactions("txn/", None, 10, false, None, None, true, 20)
        .unwrap();
    assert_eq!(expired.transactions.len(), 1);
    assert_eq!(expired.transactions[0].transaction_id, "txn/c-expired");
    assert_eq!(expired.skipped_not_expired_count, 1);
    assert!(matches!(
        store.list_metadata_transactions(
            "txn/",
            Some("other/marker"),
            10,
            true,
            None,
            None,
            false,
            20,
        ),
        Err(ObjectError::InvalidArgument(_))
    ));
    assert!(matches!(
        store.list_metadata_transactions("txn/", None, 10, true, None, Some("active"), false, 20,),
        Err(ObjectError::InvalidArgument(_))
    ));

    let snapshot = store.export_snapshot().unwrap();
    let mut restored = MatrixObjectStore::new(test_options()).unwrap();
    restored.install_snapshot(snapshot).unwrap();
    let restored_page = restored
        .list_metadata_transactions("txn/", None, 10, true, None, None, false, 20)
        .unwrap();
    assert_eq!(restored_page.transactions.len(), 3);
}

#[test]
fn raft_backed_store_replays_metaserver_raft_membership() {
    let raft = InMemoryRustRaft::new(1).unwrap();
    let store = MatrixObjectStore::new(test_options()).unwrap();
    let mut replicated = RaftBackedObjectStore::new(raft, store);
    let plan = replicated
        .store()
        .plan_raft_membership_change(
            vec![
                "meta-c".to_string(),
                "local".to_string(),
                "meta-b".to_string(),
            ],
            2,
        )
        .unwrap();
    assert_eq!(plan.membership_change_type, "add_voter");
    assert!(plan.membership_plan_safe);
    assert_eq!(plan.changed_voter_count, 2);
    assert_eq!(plan.staged_changed_voter_count, 1);
    assert!(plan.requires_joint_consensus);
    assert!(plan.staged_membership_required);
    assert!(plan.membership_plan_reject_reason.is_empty());
    assert_eq!(
        plan.target_voter_node_ids,
        vec!["local".to_string(), "meta-b".to_string()]
    );
    assert_eq!(
        plan.final_target_voter_node_ids,
        vec![
            "local".to_string(),
            "meta-b".to_string(),
            "meta-c".to_string()
        ]
    );
    let staged_prepared = replicated
        .prepare_apply_raft_membership_entry(
            "meta-membership-joint-0001",
            vec![
                "meta-c".to_string(),
                "local".to_string(),
                "meta-b".to_string(),
            ],
            2,
        )
        .unwrap();
    assert!(staged_prepared.plan.staged_membership_required);
    assert_eq!(
        staged_prepared.target_voter_node_ids,
        vec!["local".to_string(), "meta-b".to_string()]
    );
    let one_step_plan = replicated
        .store()
        .plan_raft_membership_change(vec!["local".to_string(), "meta-b".to_string()], 2)
        .unwrap();
    assert_eq!(one_step_plan.changed_voter_count, 1);
    assert!(!one_step_plan.requires_joint_consensus);
    assert!(one_step_plan.membership_plan_safe);
    assert_eq!(
        one_step_plan.target_voter_node_ids,
        vec!["local".to_string(), "meta-b".to_string()]
    );
    let unsafe_plan = replicated
        .store()
        .plan_raft_membership_change(vec!["local".to_string(), "meta-b".to_string()], 1)
        .unwrap();
    assert!(!unsafe_plan.membership_plan_safe);
    assert_eq!(
        unsafe_plan.membership_plan_reject_reason,
        "target_quorum_unavailable"
    );

    let receipt = replicated
        .propose_apply_raft_membership(
            "meta-membership-0001",
            vec!["local".to_string(), "meta-b".to_string()],
            2,
        )
        .unwrap();
    assert_eq!(receipt.content_type, "metaserver/raft-membership");
    assert_eq!(receipt.version, 2);
    assert_eq!(receipt.length, 2);
    assert_eq!(replicated.raft_commit_index(), 1);
    assert_eq!(replicated.store().raft_membership_epoch(), 2);
    assert_eq!(replicated.store().raft_membership_receipt_count(), 1);
    let membership_receipts = replicated
        .store()
        .list_raft_membership_receipts(None, 1, Some("meta-b"), None, Some(true), Some(true))
        .unwrap();
    assert_eq!(membership_receipts.receipt_count, 1);
    assert_eq!(membership_receipts.total_receipt_count, 1);
    assert_eq!(
        membership_receipts.target_voter_node_id,
        Some("meta-b".to_string())
    );
    assert_eq!(membership_receipts.quorum_preserved, Some(true));
    assert_eq!(membership_receipts.membership_plan_safe, Some(true));
    assert_eq!(membership_receipts.skipped_target_voter_count, 0);
    assert_eq!(
        membership_receipts.receipts[0].mutation_id,
        "meta-membership-0001"
    );
    assert_eq!(membership_receipts.receipts[0].membership_epoch, 2);
    assert_eq!(membership_receipts.receipts[0].target_healthy_peer_count, 2);
    let (linearizable_membership_receipts, membership_readiness) = replicated
        .list_raft_membership_receipts_linearizable(
            None,
            1,
            Some("meta-b"),
            None,
            Some(true),
            Some(true),
            10,
        )
        .unwrap();
    assert!(membership_readiness.readable);
    assert_eq!(
        membership_readiness.raft_log_commit_index,
        replicated.raft_commit_index()
    );
    assert_eq!(linearizable_membership_receipts.receipt_count, 1);
    assert_eq!(
        linearizable_membership_receipts.receipts[0].mutation_id,
        "meta-membership-0001"
    );
    let membership_receipt_miss = replicated
        .store()
        .list_raft_membership_receipts(None, 1, Some("meta-z"), None, None, None)
        .unwrap();
    assert_eq!(membership_receipt_miss.receipt_count, 0);
    assert_eq!(membership_receipt_miss.skipped_target_voter_count, 1);
    assert!(matches!(
        replicated.list_raft_membership_receipts_linearizable(
            Some("bad\nmarker"),
            1,
            None,
            None,
            None,
            None,
            10
        ),
        Err(ObjectError::InvalidArgument(_))
    ));
    assert_eq!(
        replicated.store().raft_voter_node_ids(),
        &["local".to_string(), "meta-b".to_string()]
    );
    let ready_membership = replicated
        .store()
        .distributed_readiness(0, 0, 0, 0, 2, 0, 0)
        .unwrap();
    assert!(ready_membership.ready);
    assert!(ready_membership.metadata_replication_enabled);
    assert_eq!(ready_membership.metadata_replica_count, 2);
    assert_eq!(ready_membership.metadata_replication_quorum, 2);
    assert_eq!(ready_membership.metadata_replication_acks, 2);
    assert_eq!(ready_membership.metadata_replication_failures, 0);
    assert_eq!(ready_membership.raft_membership_epoch, 2);
    assert_eq!(ready_membership.raft_membership_receipt_count, 1);
    assert_eq!(ready_membership.metadata.raft_membership_receipt_count, 1);
    assert_eq!(
        ready_membership.metadata_replication_last_status,
        "quorum available: 2/2"
    );

    let peer_health = replicated.propose_update_raft_peer_health(1).unwrap();
    assert_eq!(peer_health.content_type, "metaserver/raft-peer-health");
    assert_eq!(peer_health.version, 1);
    assert_eq!(peer_health.length, 2);
    assert_eq!(replicated.raft_commit_index(), 2);
    let degraded_membership = replicated
        .store()
        .distributed_readiness(0, 0, 0, 0, 2, 0, 0)
        .unwrap();
    assert!(!degraded_membership.ready);
    assert_eq!(
        degraded_membership.reason,
        "metadata_replication_quorum_unavailable"
    );
    assert!(degraded_membership.metadata_replication_enabled);
    assert_eq!(degraded_membership.metadata_replica_count, 2);
    assert_eq!(degraded_membership.metadata_replication_quorum, 2);
    assert_eq!(degraded_membership.metadata_replication_acks, 1);
    assert_eq!(degraded_membership.metadata_replication_failures, 1);
    assert_eq!(
        degraded_membership.metadata_replication_last_status,
        "quorum unavailable: 1/2"
    );

    let mut follower = MatrixObjectStore::new(test_options()).unwrap();
    replicated.replay_into(&mut follower).unwrap();
    assert_eq!(follower.last_applied_index(), 2);
    assert_eq!(follower.raft_membership_epoch(), 2);
    assert_eq!(follower.raft_membership_receipt_count(), 1);
    assert_eq!(follower.raft_healthy_peer_count(), 1);
    assert_eq!(
        follower.raft_voter_node_ids(),
        &["local".to_string(), "meta-b".to_string()]
    );
    let snapshot = follower.export_snapshot().unwrap();
    let restored_snapshot = StoreSnapshot::from_bytes(&snapshot.to_bytes().unwrap()).unwrap();
    let mut restored = MatrixObjectStore::new(test_options()).unwrap();
    restored.install_snapshot(restored_snapshot).unwrap();
    assert_eq!(restored.raft_membership_epoch(), 2);
    assert_eq!(restored.raft_membership_receipt_count(), 1);
    assert_eq!(restored.raft_healthy_peer_count(), 1);
    assert_eq!(
        restored.raft_voter_node_ids(),
        follower.raft_voter_node_ids()
    );
    let restored_receipts = restored
        .list_raft_membership_receipts(None, 100, None, None, None, None)
        .unwrap();
    assert_eq!(restored_receipts.receipt_count, 1);
    assert_eq!(restored_receipts.total_receipt_count, 1);
    assert_eq!(
        restored_receipts.receipts[0].target_voter_node_ids,
        vec!["local".to_string(), "meta-b".to_string()]
    );
    let readiness = restored.distributed_readiness(0, 0, 0, 0, 2, 0, 0).unwrap();
    assert!(!readiness.ready);
    assert_eq!(readiness.reason, "metadata_replication_quorum_unavailable");
    assert!(readiness.metadata_replication_enabled);
    assert_eq!(readiness.metadata_replica_count, 2);
    assert_eq!(readiness.metadata_replication_quorum, 2);
    assert_eq!(readiness.metadata_replication_acks, 1);
    assert_eq!(readiness.metadata_replication_failures, 1);
    assert_eq!(
        readiness.metadata_replication_last_status,
        "quorum unavailable: 1/2"
    );
    assert_eq!(readiness.raft_membership_epoch, 2);
    assert_eq!(readiness.raft_membership_receipt_count, 1);
    assert_eq!(readiness.metadata.raft_membership_receipt_count, 1);
    assert_eq!(
        readiness.metadata_commit_index,
        readiness.metadata.applied_commit_index
    );
}

#[test]
fn raft_backed_store_applies_prepared_metaserver_raft_membership() {
    let raft = InMemoryRustRaft::new(1).unwrap();
    let store = MatrixObjectStore::new(test_options()).unwrap();
    let mut replicated = RaftBackedObjectStore::new(raft, store);

    let prepared = replicated
        .prepare_apply_raft_membership_entry(
            "meta-membership-prepared-0001",
            vec!["local".to_string(), "meta-b".to_string()],
            2,
        )
        .unwrap();
    assert_eq!(prepared.expected_previous_commit_index, 0);
    assert_eq!(prepared.prepared_commit_index, 1);
    assert_eq!(prepared.plan.membership_change_type, "add_voter");
    assert!(prepared.plan.membership_plan_safe);
    assert!(!prepared.raft_entry_checksum.is_empty());

    let mut tampered = prepared.clone();
    tampered.target_healthy_peer_count = 1;
    let mut validator = replicated.store().clone();
    assert!(matches!(
        validator.apply_command(ObjectCommand::ApplyPreparedRaftMembership { prepared: tampered }),
        Err(ObjectError::PreconditionFailed(_))
    ));

    let receipt = replicated
        .propose_prepared_raft_membership(prepared.clone())
        .unwrap();
    assert_eq!(receipt.content_type, "metaserver/raft-membership-prepared");
    assert_eq!(receipt.version, 2);
    assert_eq!(receipt.length, 2);
    assert_eq!(replicated.raft_commit_index(), 1);
    assert_eq!(replicated.store().last_applied_index(), 1);
    assert_eq!(replicated.store().raft_membership_epoch(), 2);
    assert_eq!(replicated.store().raft_membership_receipt_count(), 1);

    let duplicate = replicated
        .prepare_apply_raft_membership_entry(
            "meta-membership-prepared-0002",
            vec!["local".to_string(), "meta-b".to_string()],
            2,
        )
        .unwrap();
    assert_eq!(duplicate.plan.membership_change_type, "no_change");
    let duplicate_receipt = replicated
        .propose_prepared_raft_membership(duplicate)
        .unwrap();
    assert_eq!(
        duplicate_receipt.content_type,
        "metaserver/raft-membership-prepared"
    );
    assert_eq!(replicated.raft_commit_index(), 2);
    assert_eq!(replicated.store().raft_membership_epoch(), 3);
    assert_eq!(replicated.store().raft_membership_receipt_count(), 2);

    let mut follower = MatrixObjectStore::new(test_options()).unwrap();
    replicated.replay_into(&mut follower).unwrap();
    assert_eq!(follower.last_applied_index(), 2);
    assert_eq!(follower.raft_membership_epoch(), 3);
    assert_eq!(follower.raft_membership_receipt_count(), 2);
    assert_eq!(
        follower.raft_voter_node_ids(),
        &["local".to_string(), "meta-b".to_string()]
    );
    let restored_snapshot =
        StoreSnapshot::from_bytes(&follower.export_snapshot().unwrap().to_bytes().unwrap()).unwrap();
    let mut restored = MatrixObjectStore::new(test_options()).unwrap();
    restored.install_snapshot(restored_snapshot).unwrap();
    assert_eq!(restored.raft_membership_epoch(), 3);
    assert_eq!(restored.raft_membership_receipt_count(), 2);
    let page = restored
        .list_raft_membership_receipts(None, 10, Some("meta-b"), None, Some(true), Some(true))
        .unwrap();
    assert_eq!(page.receipt_count, 2);
    assert_eq!(page.total_receipt_count, 2);
    assert_eq!(
        page.receipts[0].mutation_id,
        "meta-membership-prepared-0001"
    );
    assert_eq!(
        page.receipts[1].mutation_id,
        "meta-membership-prepared-0002"
    );
}

#[test]
fn raft_backed_store_rolls_out_staged_metaserver_raft_membership() {
    let raft = InMemoryRustRaft::new(1).unwrap();
    let store = MatrixObjectStore::new(test_options()).unwrap();
    let mut replicated = RaftBackedObjectStore::new(raft, store);

    let partial = replicated
        .propose_staged_raft_membership_rollout(
            "meta-membership-rollout-partial",
            vec![
                "meta-c".to_string(),
                "local".to_string(),
                "meta-b".to_string(),
            ],
            3,
            1,
        )
        .unwrap();
    assert!(!partial.completed);
    assert!(partial.phase_budget_limited);
    assert!(partial.needs_read_index_refresh);
    assert_eq!(partial.prepared_phases.len(), 1);
    assert_eq!(partial.applied_phases.len(), 1);
    assert_eq!(
        partial.prepared_phases[0].target_voter_node_ids,
        vec!["local".to_string(), "meta-b".to_string()]
    );
    assert_eq!(
        partial.final_plan.current_voter_node_ids,
        vec!["local".to_string(), "meta-b".to_string()]
    );
    assert_eq!(replicated.raft_commit_index(), 1);
    assert_eq!(replicated.store().raft_membership_epoch(), 2);

    let complete = replicated
        .propose_staged_raft_membership_rollout(
            "meta-membership-rollout-complete",
            vec![
                "meta-c".to_string(),
                "local".to_string(),
                "meta-b".to_string(),
            ],
            3,
            4,
        )
        .unwrap();
    assert!(complete.completed);
    assert!(!complete.phase_budget_limited);
    assert!(complete.needs_read_index_refresh);
    assert_eq!(complete.prepared_phases.len(), 1);
    assert_eq!(complete.applied_phases.len(), 1);
    assert_eq!(
        complete.prepared_phases[0].target_voter_node_ids,
        vec![
            "local".to_string(),
            "meta-b".to_string(),
            "meta-c".to_string()
        ]
    );
    assert_eq!(
        complete.final_plan.current_voter_node_ids,
        vec![
            "local".to_string(),
            "meta-b".to_string(),
            "meta-c".to_string()
        ]
    );
    assert_eq!(replicated.raft_commit_index(), 2);
    assert_eq!(replicated.store().raft_membership_epoch(), 3);
    assert_eq!(replicated.store().raft_membership_receipt_count(), 2);
    assert_eq!(
        replicated.store().raft_voter_node_ids(),
        &[
            "local".to_string(),
            "meta-b".to_string(),
            "meta-c".to_string()
        ]
    );

    let no_change = replicated
        .propose_staged_raft_membership_rollout(
            "meta-membership-rollout-noop",
            vec![
                "meta-c".to_string(),
                "local".to_string(),
                "meta-b".to_string(),
            ],
            3,
            1,
        )
        .unwrap();
    assert!(no_change.completed);
    assert!(!no_change.needs_read_index_refresh);
    assert!(no_change.prepared_phases.is_empty());
    assert_eq!(replicated.raft_commit_index(), 2);

    let mut follower = MatrixObjectStore::new(test_options()).unwrap();
    replicated.replay_into(&mut follower).unwrap();
    assert_eq!(follower.last_applied_index(), 2);
    assert_eq!(follower.raft_membership_epoch(), 3);
    assert_eq!(follower.raft_membership_receipt_count(), 2);
    assert_eq!(
        follower.raft_voter_node_ids(),
        &[
            "local".to_string(),
            "meta-b".to_string(),
            "meta-c".to_string()
        ]
    );
    let receipts = follower
        .list_raft_membership_receipts(None, 10, Some("meta-c"), None, Some(true), Some(true))
        .unwrap();
    assert_eq!(receipts.receipt_count, 1);
    assert_eq!(
        receipts.receipts[0].mutation_id,
        "meta-membership-rollout-complete-phase-0001"
    );
}

#[test]
fn raft_backed_store_replays_metaserver_prefix_delete_and_checkpoints() {
    let raft = InMemoryRustRaft::new(1).unwrap();
    let store = MatrixObjectStore::new(test_options()).unwrap();
    let mut replicated = RaftBackedObjectStore::new(raft, store);
    replicated
        .propose_begin_meta_transaction(
            "txn/prefix",
            "owner-a",
            100,
            vec![
                MetadataMutation {
                    key: "object/gc/a".to_string().into(),
                    record_value: ("value-a".to_string()).into(),
                    expected_version: 0,
                    delete: false,
                },
                MetadataMutation {
                    key: "object/gc/b".to_string().into(),
                    record_value: ("value-b".to_string()).into(),
                    expected_version: 0,
                    delete: false,
                },
                MetadataMutation {
                    key: "object/live/c".to_string().into(),
                    record_value: ("value-c".to_string()).into(),
                    expected_version: 0,
                    delete: false,
                },
            ],
            20,
        )
        .unwrap();
    replicated
        .propose_commit_meta_transaction("txn/prefix", "owner-a", 21)
        .unwrap();
    let deleted = replicated
        .propose_delete_meta_by_prefix("object/gc/", 10, None, None, 22)
        .unwrap();
    assert_eq!(deleted.content_type, "metaserver/prefix-delete");
    assert_eq!(deleted.length, 2);
    let changes = replicated.store().metadata_changes_after(0, 10);
    let checkpoint = MetadataChangeCheckpoint {
        consumer_id: "consumer-a".to_string(),
        prefix: "object/gc/".to_string(),
        after_change_sequence: changes.last().unwrap().sequence,
        after_commit_index: changes.last().unwrap().commit_index,
        update_time_ms: 23,
        owner: "metaserver-a".to_string(),
        note: "raft consumed".to_string(),
    };
    replicated
        .propose_commit_meta_change_checkpoint(checkpoint.clone())
        .unwrap();
    let compacted = replicated
        .propose_compact_meta_changefeed("object/gc/", 10)
        .unwrap();
    assert_eq!(compacted.content_type, "metaserver/changefeed-compact");
    assert_eq!(compacted.version, 4);
    assert_eq!(compacted.length, 1);
    assert_eq!(compacted.update_time_ms, checkpoint.after_change_sequence);
    assert_eq!(replicated.store().metadata_changes_after(0, 10).len(), 1);
    assert_eq!(replicated.raft_commit_index(), 5);

    let mut follower = MatrixObjectStore::new(test_options()).unwrap();
    replicated.replay_into(&mut follower).unwrap();
    assert!(matches!(
        follower.metadata_record("object/gc/a"),
        Err(ObjectError::NotFound(_))
    ));
    assert!(matches!(
        follower.metadata_record("object/gc/b"),
        Err(ObjectError::NotFound(_))
    ));
    assert_eq!(
        follower.metadata_record("object/live/c").unwrap().value,
        "value-c".into()
    );
    assert_eq!(
        follower
            .metadata_change_checkpoint("consumer-a", "object/gc/")
            .unwrap()
            .note,
        "raft consumed"
    );
    let retained_changes = follower.metadata_changes_after(0, 10);
    assert_eq!(retained_changes.len(), 1);
    assert_eq!(retained_changes[0].key, "object/live/c");
    assert_eq!(follower.last_applied_index(), 5);
}

#[test]
fn raft_backed_store_replays_retention_and_legal_hold_commands() {
    let raft = InMemoryRustRaft::new(1).unwrap();
    let store = MatrixObjectStore::new(test_options()).unwrap();
    let mut replicated = RaftBackedObjectStore::new(raft, store);
    replicated
        .propose(ObjectCommand::PutObject {
            bucket: "bucket".to_string(),
            key: "object".to_string(),
            data: b"governed".to_vec(),
            content_type: "text/plain".to_string(),
            update_time_ms: 10,
            options: PutOptions::default(),
        })
        .unwrap();
    replicated
        .propose_configure_bucket_retention("bucket", 120_000, 11)
        .unwrap();
    let retention_receipt = replicated
        .propose_configure_bucket_retention_idempotent_with_read_proof_linearizable(
            "governed",
            300_000,
            12,
            "bucket-retention-governed-a",
        )
        .unwrap();
    assert_eq!(retention_receipt.value.retain_for_ms, 300_000);
    let retention_retry = replicated
        .propose_configure_bucket_retention_idempotent(
            "governed",
            300_000,
            13,
            "bucket-retention-governed-a",
        )
        .unwrap();
    assert_eq!(retention_retry.commit_index, 3);
    assert!(matches!(
        replicated.propose_configure_bucket_retention_idempotent(
            "governed",
            1,
            14,
            "bucket-retention-governed-a"
        ),
        Err(ObjectError::InvalidArgument(_))
    ));
    replicated
        .propose_set_object_legal_hold("bucket", "object", true, 12)
        .unwrap();
    replicated
        .propose_set_object_retention("bucket", "object", 240_000, 13)
        .unwrap();
    replicated
        .propose_register_meta_coordinator_session(
            "session-retention-meta-a",
            "meta-a",
            "metaserver://meta-a",
            1_000,
            15,
        )
        .unwrap();
    replicated
        .propose_configure_meta_shard(MetadataShard {
            shard_id: "bucket-shardretention".to_string(),
            start_key: "bucket/shardretention".to_string(),
            end_key: "bucket/shardretention0".to_string(),
            owner_node_id: "meta-a".to_string(),
            epoch: 3,
            draining: false,
        })
        .unwrap();
    let shard_retention = replicated
        .propose_configure_bucket_retention_idempotent_with_read_proof_from_meta_shard(
            "shardretention",
            600_000,
            16,
            "bucket-retention-shard-a",
            replicated.raft_commit_index(),
            0,
            "meta-a",
            3,
        )
        .unwrap();
    assert_eq!(shard_retention.value.retain_for_ms, 600_000);
    let wrong_owner = replicated.propose_configure_bucket_retention_idempotent_from_meta_shard(
        "shardretention",
        1,
        17,
        "bucket-retention-shard-wrong-owner",
        replicated.raft_commit_index(),
        "meta-b",
        3,
    );
    assert!(matches!(
        wrong_owner,
        Err(ObjectError::PreconditionFailed(_))
    ));
    assert_eq!(replicated.raft_commit_index(), 8);

    let mut follower = MatrixObjectStore::new(test_options()).unwrap();
    replicated.replay_into(&mut follower).unwrap();
    assert_eq!(follower.bucket_retention("bucket").unwrap(), 120_000);
    assert_eq!(follower.bucket_retention("governed").unwrap(), 300_000);
    assert_eq!(
        follower.bucket_retention("shardretention").unwrap(),
        600_000
    );
    let follower_retry = follower
        .configure_bucket_retention_idempotent(
            "shardretention",
            600_000,
            "bucket-retention-shard-a",
        )
        .unwrap();
    assert_eq!(follower_retry.commit_index, 8);
    let metadata = follower.head_object("bucket", "object").unwrap();
    assert!(metadata.lock.legal_hold);
    assert_eq!(metadata.lock.retention_until_ms, 240_000);
    assert!(matches!(
        follower.delete_object("bucket", "object"),
        Err(ObjectError::PreconditionFailed(_))
    ));
    assert_eq!(follower.last_applied_index(), 8);
}

#[test]
fn raft_backed_store_replays_idempotent_bucket_membership() {
    let raft = InMemoryRustRaft::new(1).unwrap();
    let store = MatrixObjectStore::new(test_options()).unwrap();
    let mut replicated = RaftBackedObjectStore::new(raft, store);
    let created = replicated
        .propose_create_bucket_idempotent_with_read_proof_linearizable(
            "membership",
            10,
            "bucket-membership-create-a",
        )
        .unwrap();
    assert_eq!(created.value.method, "CreateBucket");
    assert_eq!(created.value.bucket, "membership");
    assert_eq!(created.value.commit_index, 1);
    assert!(replicated.store().buckets.contains("membership"));
    let create_retry = replicated
        .propose_create_bucket_idempotent("membership", 11, "bucket-membership-create-a")
        .unwrap();
    assert_eq!(create_retry.commit_index, 1);
    assert!(matches!(
        replicated.propose_create_bucket_idempotent(
            "membership-other",
            12,
            "bucket-membership-create-a"
        ),
        Err(ObjectError::InvalidArgument(_))
    ));
    replicated
        .propose_register_meta_coordinator_session(
            "session-bucket-membership-meta-a",
            "meta-a",
            "metaserver://meta-a",
            1_000,
            13,
        )
        .unwrap();
    replicated
        .propose_configure_meta_shard(MetadataShard {
            shard_id: "bucket-membership-owned".to_string(),
            start_key: "bucket/owned".to_string(),
            end_key: "bucket/owned0".to_string(),
            owner_node_id: "meta-a".to_string(),
            epoch: 9,
            draining: false,
        })
        .unwrap();
    let owned = replicated
        .propose_create_bucket_idempotent_with_read_proof_from_meta_shard(
            "owned",
            14,
            "bucket-membership-create-owned",
            replicated.raft_commit_index(),
            0,
            "meta-a",
            9,
        )
        .unwrap();
    assert_eq!(owned.value.commit_index, 4);
    assert!(matches!(
        replicated.propose_create_bucket_idempotent_from_meta_shard(
            "owned",
            15,
            "bucket-membership-create-owned-wrong-owner",
            replicated.raft_commit_index(),
            "meta-b",
            9,
        ),
        Err(ObjectError::PreconditionFailed(_))
    ));
    let deleted = replicated
        .propose_delete_bucket_idempotent_with_read_proof_from_meta_shard(
            "owned",
            16,
            "bucket-membership-delete-owned",
            replicated.raft_commit_index(),
            0,
            "meta-a",
            9,
        )
        .unwrap();
    assert_eq!(deleted.value.method, "DeleteBucket");
    assert_eq!(deleted.value.commit_index, 5);
    assert!(!replicated.store().buckets.contains("owned"));
    let delete_retry = replicated
        .propose_delete_bucket_idempotent("owned", 17, "bucket-membership-delete-owned")
        .unwrap();
    assert_eq!(delete_retry.commit_index, 5);
    assert!(matches!(
        replicated.propose_delete_bucket_idempotent(
            "owned-other",
            18,
            "bucket-membership-delete-owned"
        ),
        Err(ObjectError::InvalidArgument(_))
    ));
    let mut follower = MatrixObjectStore::new(test_options()).unwrap();
    replicated.replay_into(&mut follower).unwrap();
    assert!(follower.buckets.contains("membership"));
    assert!(!follower.buckets.contains("owned"));
    let follower_delete_retry = follower
        .delete_bucket_idempotent("owned", "bucket-membership-delete-owned")
        .unwrap();
    assert_eq!(follower_delete_retry.commit_index, 5);
    assert_eq!(follower.last_applied_index(), 5);
    assert!(matches!(
        follower.create_bucket_idempotent("owned-other", "bucket-membership-create-owned"),
        Err(ObjectError::InvalidArgument(_))
    ));
}

#[test]
fn raft_backed_store_replays_idempotent_bucket_versioning() {
    let raft = InMemoryRustRaft::new(1).unwrap();
    let store = MatrixObjectStore::new(test_options()).unwrap();
    let mut replicated = RaftBackedObjectStore::new(raft, store);
    let receipt = replicated
        .propose_set_bucket_versioning_idempotent_with_read_proof_linearizable(
            "bucket",
            true,
            11,
            "bucket-versioning-a",
        )
        .unwrap();
    assert!(receipt.value.enabled);
    assert_eq!(receipt.value.metadata.content_type, "bucket/versioning");
    let retry = replicated
        .propose_set_bucket_versioning_idempotent("bucket", true, 12, "bucket-versioning-a")
        .unwrap();
    assert_eq!(retry.commit_index, 1);
    assert!(matches!(
        replicated.propose_set_bucket_versioning_idempotent(
            "bucket",
            false,
            13,
            "bucket-versioning-a"
        ),
        Err(ObjectError::InvalidArgument(_))
    ));
    replicated
        .propose_register_meta_coordinator_session(
            "session-meta-a",
            "meta-a",
            "metaserver://meta-a",
            1_000,
            19,
        )
        .unwrap();
    replicated
        .propose_configure_meta_shard(MetadataShard {
            shard_id: "bucket-owned".to_string(),
            start_key: "bucket/owned".to_string(),
            end_key: "bucket/owned0".to_string(),
            owner_node_id: "meta-a".to_string(),
            epoch: 7,
            draining: false,
        })
        .unwrap();
    let shard_fenced = replicated
        .propose_set_bucket_versioning_idempotent_with_read_proof_from_meta_shard(
            "owned",
            true,
            20,
            "bucket-versioning-owned",
            replicated.raft_commit_index(),
            0,
            "meta-a",
            7,
        )
        .unwrap();
    assert!(shard_fenced.value.enabled);
    let wrong_owner = replicated.propose_set_bucket_versioning_idempotent_from_meta_shard(
        "owned",
        false,
        21,
        "bucket-versioning-wrong-owner",
        replicated.raft_commit_index(),
        "meta-b",
        7,
    );
    assert!(matches!(
        wrong_owner,
        Err(ObjectError::PreconditionFailed(_))
    ));

    let mut follower = MatrixObjectStore::new(test_options()).unwrap();
    replicated.replay_into(&mut follower).unwrap();
    assert!(follower.bucket_versioning_enabled("bucket").unwrap());
    assert!(follower.bucket_versioning_enabled("owned").unwrap());
    let follower_retry = follower
        .set_bucket_versioning_idempotent("bucket", true, "bucket-versioning-a")
        .unwrap();
    assert_eq!(follower_retry.commit_index, 1);
    let follower_shard_retry = follower
        .set_bucket_versioning_idempotent("owned", true, "bucket-versioning-owned")
        .unwrap();
    assert_eq!(follower_shard_retry.commit_index, 4);
    assert!(matches!(
        follower.set_bucket_versioning_idempotent("bucket", false, "bucket-versioning-a"),
        Err(ObjectError::InvalidArgument(_))
    ));
    assert_eq!(follower.last_applied_index(), 4);
}

#[test]
fn raft_backed_store_replays_bucket_quota_commands() {
    let raft = InMemoryRustRaft::new(1).unwrap();
    let store = MatrixObjectStore::new(test_options()).unwrap();
    let mut replicated = RaftBackedObjectStore::new(raft, store);
    replicated
        .propose_configure_bucket_quota("bucket", 8, 1, 1)
        .unwrap();
    let quota_receipt = replicated
        .propose_configure_bucket_quota_idempotent_with_read_proof_linearizable(
            "quota",
            16,
            2,
            2,
            "bucket-quota-a",
        )
        .unwrap();
    assert_eq!(quota_receipt.value.quota.max_live_bytes, 16);
    assert_eq!(quota_receipt.value.quota.max_live_objects, 2);
    let quota_retry = replicated
        .propose_configure_bucket_quota_idempotent("quota", 16, 2, 3, "bucket-quota-a")
        .unwrap();
    assert_eq!(quota_retry.commit_index, 2);
    assert!(matches!(
        replicated.propose_configure_bucket_quota_idempotent("quota", 1, 1, 4, "bucket-quota-a"),
        Err(ObjectError::InvalidArgument(_))
    ));
    replicated
        .propose(ObjectCommand::PutObject {
            bucket: "bucket".to_string(),
            key: "object".to_string(),
            data: b"12345678".to_vec(),
            content_type: "text/plain".to_string(),
            update_time_ms: 2,
            options: PutOptions::default(),
        })
        .unwrap();
    replicated
        .propose_register_meta_coordinator_session(
            "session-quota-meta-a",
            "meta-a",
            "metaserver://meta-a",
            1_000,
            5,
        )
        .unwrap();
    replicated
        .propose_configure_meta_shard(MetadataShard {
            shard_id: "bucket-shardquota".to_string(),
            start_key: "bucket/shardquota".to_string(),
            end_key: "bucket/shardquota0".to_string(),
            owner_node_id: "meta-a".to_string(),
            epoch: 4,
            draining: false,
        })
        .unwrap();
    let shard_quota = replicated
        .propose_configure_bucket_quota_idempotent_with_read_proof_from_meta_shard(
            "shardquota",
            32,
            3,
            6,
            "bucket-quota-shard-a",
            replicated.raft_commit_index(),
            0,
            "meta-a",
            4,
        )
        .unwrap();
    assert_eq!(shard_quota.value.quota.max_live_bytes, 32);
    assert_eq!(shard_quota.value.quota.max_live_objects, 3);
    let wrong_owner = replicated.propose_configure_bucket_quota_idempotent_from_meta_shard(
        "shardquota",
        1,
        1,
        7,
        "bucket-quota-shard-wrong-owner",
        replicated.raft_commit_index(),
        "meta-b",
        4,
    );
    assert!(matches!(
        wrong_owner,
        Err(ObjectError::PreconditionFailed(_))
    ));

    let mut follower = MatrixObjectStore::new(test_options()).unwrap();
    replicated.replay_into(&mut follower).unwrap();
    assert_eq!(follower.bucket_live_usage("bucket").unwrap(), (8, 1));
    assert_eq!(follower.bucket_quota("bucket").unwrap().max_live_objects, 1);
    assert_eq!(follower.bucket_quota("quota").unwrap().max_live_objects, 2);
    assert_eq!(
        follower
            .bucket_quota("shardquota")
            .unwrap()
            .max_live_objects,
        3
    );
    let follower_retry = follower
        .configure_bucket_quota_idempotent("shardquota", 32, 3, "bucket-quota-shard-a")
        .unwrap();
    assert_eq!(follower_retry.commit_index, 6);
    assert!(matches!(
        follower.put_object("bucket", "second", b"x".to_vec(), "text/plain"),
        Err(ObjectError::PreconditionFailed(_))
    ));
    assert_eq!(follower.last_applied_index(), 6);
}

#[test]
fn raft_backed_store_replays_storage_class_restore_commands() {
    let raft = InMemoryRustRaft::new(1).unwrap();
    let store = MatrixObjectStore::new(test_options()).unwrap();
    let mut replicated = RaftBackedObjectStore::new(raft, store);
    replicated
        .propose(ObjectCommand::PutObject {
            bucket: "bucket".to_string(),
            key: "cold".to_string(),
            data: b"cold-data".to_vec(),
            content_type: "text/plain".to_string(),
            update_time_ms: 1,
            options: PutOptions::default(),
        })
        .unwrap();
    replicated
        .propose_transition_object("bucket", "cold", "DEEP_ARCHIVE", 2)
        .unwrap();
    let mut follower = MatrixObjectStore::new(test_options()).unwrap();
    replicated.replay_into(&mut follower).unwrap();
    let metadata = follower.head_object("bucket", "cold").unwrap();
    assert_eq!(metadata.storage_class, "DEEP_ARCHIVE");
    assert!(matches!(
        follower.get_object("bucket", "cold"),
        Err(ObjectError::PreconditionFailed(_))
    ));

    replicated
        .propose_restore_object("bucket", "cold", u64::MAX / 2, 3)
        .unwrap();
    replicated.replay_into(&mut follower).unwrap();
    assert_eq!(
        follower.get_object("bucket", "cold").unwrap().data,
        b"cold-data".to_vec()
    );
    assert_eq!(follower.last_applied_index(), 3);
}

#[test]
fn raft_backed_store_replays_idempotent_bucket_lifecycle() {
    let raft = InMemoryRustRaft::new(1).unwrap();
    let store = MatrixObjectStore::new(test_options()).unwrap();
    let mut retry_replicated = RaftBackedObjectStore::new(raft, store);
    let retry_policy = BucketLifecyclePolicy {
        noncurrent_versions_to_keep: 1,
        expire_current_after_ms: 10_000,
        ..BucketLifecyclePolicy::default()
    };
    let retry_report = retry_replicated
        .propose_configure_bucket_lifecycle_idempotent_with_read_proof_linearizable(
            "lifecycle",
            retry_policy.clone(),
            11,
            "bucket-lifecycle-a",
        )
        .unwrap();
    assert_eq!(
        retry_report.value.policy.noncurrent_versions_to_keep,
        retry_policy.noncurrent_versions_to_keep
    );
    let retry_receipt = retry_replicated
        .propose_configure_bucket_lifecycle_idempotent(
            "lifecycle",
            retry_policy.clone(),
            12,
            "bucket-lifecycle-a",
        )
        .unwrap();
    assert_eq!(retry_receipt.commit_index, 1);
    let changed_policy = BucketLifecyclePolicy {
        noncurrent_versions_to_keep: 2,
        expire_current_after_ms: 10_000,
        ..BucketLifecyclePolicy::default()
    };
    assert!(matches!(
        retry_replicated.propose_configure_bucket_lifecycle_idempotent(
            "lifecycle",
            changed_policy,
            13,
            "bucket-lifecycle-a"
        ),
        Err(ObjectError::InvalidArgument(_))
    ));
    retry_replicated
        .propose_register_meta_coordinator_session(
            "session-lifecycle-meta-a",
            "meta-a",
            "metaserver://meta-a",
            1_000,
            14,
        )
        .unwrap();
    retry_replicated
        .propose_configure_meta_shard(MetadataShard {
            shard_id: "bucket-shardlifecycle".to_string(),
            start_key: "bucket/shardlifecycle".to_string(),
            end_key: "bucket/shardlifecycle0".to_string(),
            owner_node_id: "meta-a".to_string(),
            epoch: 5,
            draining: false,
        })
        .unwrap();
    let shard_policy = BucketLifecyclePolicy {
        noncurrent_versions_to_keep: 3,
        transition_after_ms: 1_000,
        transition_storage_class: Some("ARCHIVE".to_string()),
        ..BucketLifecyclePolicy::default()
    };
    let shard_report = retry_replicated
        .propose_configure_bucket_lifecycle_idempotent_with_read_proof_from_meta_shard(
            "shardlifecycle",
            shard_policy.clone(),
            15,
            "bucket-lifecycle-shard-a",
            retry_replicated.raft_commit_index(),
            0,
            "meta-a",
            5,
        )
        .unwrap();
    assert_eq!(
        shard_report.value.policy.noncurrent_versions_to_keep,
        shard_policy.noncurrent_versions_to_keep
    );
    let wrong_owner = retry_replicated
        .propose_configure_bucket_lifecycle_idempotent_from_meta_shard(
            "shardlifecycle",
            BucketLifecyclePolicy::default(),
            16,
            "bucket-lifecycle-shard-wrong-owner",
            retry_replicated.raft_commit_index(),
            "meta-b",
            5,
        );
    assert!(matches!(
        wrong_owner,
        Err(ObjectError::PreconditionFailed(_))
    ));
    let mut retry_follower = MatrixObjectStore::new(test_options()).unwrap();
    retry_replicated.replay_into(&mut retry_follower).unwrap();
    assert_eq!(
        retry_follower
            .bucket_lifecycle("shardlifecycle")
            .unwrap()
            .noncurrent_versions_to_keep,
        3
    );
    let follower_retry = retry_follower
        .configure_bucket_lifecycle_idempotent(
            "shardlifecycle",
            shard_policy,
            "bucket-lifecycle-shard-a",
        )
        .unwrap();
    assert_eq!(follower_retry.commit_index, 4);
    assert_eq!(retry_follower.last_applied_index(), 4);
}

