#[test]
fn raft_backed_store_replays_lifecycle_policy_application() {
    let mut stale_raft = InMemoryRustRaft::new(1).unwrap();
    stale_raft
        .append(ObjectCommand::CreateBucket {
            bucket: "ahead".to_string(),
        })
        .unwrap();
    let stale_store = MatrixObjectStore::new(test_options()).unwrap();
    let mut stale = RaftBackedObjectStore::new(stale_raft, stale_store);
    let stale_err = stale
        .propose_apply_bucket_lifecycle_policies_report_with_read_proof_linearizable(1, 10)
        .unwrap_err();
    assert!(stale_err
        .to_string()
        .contains("bucket lifecycle apply report read index is not satisfied"));

    let raft = InMemoryRustRaft::new(1).unwrap();
    let store = MatrixObjectStore::new(test_options()).unwrap();
    let mut replicated = RaftBackedObjectStore::new(raft, store);
    replicated
        .propose(ObjectCommand::SetBucketVersioning {
            bucket: "bucket".to_string(),
            enabled: true,
        })
        .unwrap();
    replicated
        .propose(ObjectCommand::PutObject {
            bucket: "bucket".to_string(),
            key: "object".to_string(),
            data: b"v1".to_vec(),
            content_type: "text/plain".to_string(),
            update_time_ms: 1,
            options: PutOptions {
                tags: tags(&[("tier", "cold")]),
                ..PutOptions::default()
            },
        })
        .unwrap();
    replicated
        .propose(ObjectCommand::PutObject {
            bucket: "bucket".to_string(),
            key: "object".to_string(),
            data: b"v2".to_vec(),
            content_type: "text/plain".to_string(),
            update_time_ms: 2,
            options: PutOptions {
                tags: tags(&[("tier", "cold")]),
                ..PutOptions::default()
            },
        })
        .unwrap();
    replicated
        .propose_configure_bucket_lifecycle(
            "bucket",
            BucketLifecyclePolicy {
                noncurrent_versions_to_keep: 0,
                noncurrent_older_than_ms: 1,
                transition_after_ms: 1,
                transition_storage_class: Some("ARCHIVE".to_string()),
                filter_tag_key: Some("tier".to_string()),
                filter_tag_value: Some("cold".to_string()),
                ..BucketLifecyclePolicy::default()
            },
            3,
        )
        .unwrap();
    let before_apply_commit = replicated.raft_commit_index();
    let proven_applied = replicated
        .propose_apply_bucket_lifecycle_policies_report_with_read_proof_linearizable(
            10,
            u64::MAX / 2,
        )
        .unwrap();
    assert_eq!(
        proven_applied.proof.requested_read_index,
        before_apply_commit
    );
    assert_eq!(
        proven_applied.proof.consensus_read_index,
        before_apply_commit
    );
    assert_eq!(
        proven_applied.proof.metadata_commit_index,
        before_apply_commit
    );
    let applied = proven_applied.value;
    assert_eq!(applied.transitioned_current_objects, 1);
    assert_eq!(applied.expired_noncurrent_versions, 1);
    assert_eq!(applied.expired_current_objects, 0);
    assert_eq!(applied.removed_delete_markers, 0);
    assert_eq!(applied.total_actions(), 2);
    assert!(!applied.truncated);

    let mut follower = MatrixObjectStore::new(test_options()).unwrap();
    replicated.replay_into(&mut follower).unwrap();
    assert_eq!(
        follower
            .head_object("bucket", "object")
            .unwrap()
            .storage_class,
        "ARCHIVE"
    );
    assert_eq!(
        follower
            .list_object_versions("bucket", "object")
            .unwrap()
            .len(),
        1
    );
    assert_eq!(follower.last_applied_index(), 5);
}

