fn raft_backed_store_replays_lifecycle_transition_only_application() {
    let raft = InMemoryRustRaft::new(1).unwrap();
    let store = MatrixObjectStore::new(test_options()).unwrap();
    let mut replicated = RaftBackedObjectStore::new(raft, store);
    replicated
        .propose_set_bucket_versioning("bucket", true)
        .unwrap();
    replicated
        .propose(ObjectCommand::PutObject {
            bucket: "bucket".to_string(),
            key: "object".to_string(),
            data: b"v1".to_vec(),
            content_type: "text/plain".to_string(),
            update_time_ms: 1,
            options: PutOptions::default(),
        })
        .unwrap();
    replicated
        .propose(ObjectCommand::PutObject {
            bucket: "bucket".to_string(),
            key: "object".to_string(),
            data: b"v2".to_vec(),
            content_type: "text/plain".to_string(),
            update_time_ms: 2,
            options: PutOptions::default(),
        })
        .unwrap();
    replicated
        .propose_configure_bucket_lifecycle(
            "bucket",
            BucketLifecyclePolicy {
                noncurrent_versions_to_keep: 0,
                noncurrent_older_than_ms: 1,
                transition_after_ms: 1,
                transition_storage_class: Some("GLACIER".to_string()),
                expire_current_after_ms: 1,
                ..BucketLifecyclePolicy::default()
            },
            3,
        )
        .unwrap();

    let before_transition_commit = replicated.raft_commit_index();
    let proven_result = replicated
        .propose_apply_bucket_lifecycle_transitions_report_with_read_proof_linearizable(
            10,
            u64::MAX / 2,
        )
        .unwrap();
    assert_eq!(
        proven_result.proof.requested_read_index,
        before_transition_commit
    );
    assert_eq!(
        proven_result.proof.consensus_read_index,
        before_transition_commit
    );
    assert_eq!(
        proven_result.proof.metadata_commit_index,
        before_transition_commit
    );
    let result = proven_result.value;
    assert_eq!(result.transitioned_current_objects, 1);
    assert_eq!(result.expired_noncurrent_versions, 0);
    assert_eq!(result.expired_current_objects, 0);
    assert_eq!(result.removed_delete_markers, 0);
    assert_eq!(result.total_actions(), 1);

    let mut follower = MatrixObjectStore::new(test_options()).unwrap();
    replicated.replay_into(&mut follower).unwrap();
    assert_eq!(
        follower
            .head_object("bucket", "object")
            .unwrap()
            .storage_class,
        "GLACIER"
    );
    assert_eq!(
        follower
            .list_object_versions("bucket", "object")
            .unwrap()
            .len(),
        2
    );
    assert_eq!(follower.last_applied_index(), 5);
}

#[test]
fn raft_backed_store_replays_idempotent_multipart_create() {
    let raft = InMemoryRustRaft::new(1).unwrap();
    let store = MatrixObjectStore::new(test_options()).unwrap();
    let mut replicated = RaftBackedObjectStore::new(raft, store);
    let route_checksum = replicated
        .store
        .chunk_service
        .route_control_proof()
        .state_checksum;
    let report = replicated
        .propose_create_multipart_upload_idempotent_with_route_report_linearizable_fenced(
            "mpu-idem",
            "bucket",
            "large",
            "application/octet-stream",
            PutOptions::default(),
            10,
            "multipart-create-idem-a",
            &route_checksum,
        )
        .unwrap();
    assert_eq!(report.upload.upload_id, "mpu-idem");
    assert_eq!(
        report.upload.create_idempotency_key.as_deref(),
        Some("multipart-create-idem-a")
    );
    assert_eq!(replicated.raft_commit_index(), 1);
    let retry = replicated
        .propose_create_multipart_upload_idempotent_with_route_report_linearizable_fenced(
            "mpu-idem",
            "bucket",
            "large",
            "application/octet-stream",
            PutOptions::default(),
            10,
            "multipart-create-idem-a",
            &route_checksum,
        )
        .unwrap();
    assert_eq!(retry.upload, report.upload);
    assert_eq!(replicated.raft_commit_index(), 1);
    assert!(matches!(
        replicated
            .propose_create_multipart_upload_idempotent_with_route_report_linearizable_fenced(
                "mpu-idem",
                "bucket",
                "large",
                "application/octet-stream",
                PutOptions::default(),
                10,
                "multipart-create-idem-b",
                &route_checksum,
            ),
        Err(ObjectError::PreconditionFailed(_))
    ));

    let mut follower = MatrixObjectStore::new(test_options()).unwrap();
    replicated.replay_into(&mut follower).unwrap();
    let replayed = follower.multipart_upload("mpu-idem").unwrap();
    assert_eq!(
        replayed.create_idempotency_key.as_deref(),
        Some("multipart-create-idem-a")
    );
    let snapshot = follower.export_snapshot().unwrap();
    let restored = StoreSnapshot::from_bytes(&snapshot.to_bytes().unwrap()).unwrap();
    assert_eq!(
        restored
            .multipart_uploads
            .get("mpu-idem")
            .unwrap()
            .create_idempotency_key
            .as_deref(),
        Some("multipart-create-idem-a")
    );
}

