#[test]
fn raft_backed_store_replays_idempotent_multipart_complete() {
    let raft = InMemoryRustRaft::new(1).unwrap();
    let store = MatrixObjectStore::new(test_options()).unwrap();
    let mut replicated = RaftBackedObjectStore::new(raft, store);
    let route_checksum = replicated
        .store
        .chunk_service
        .route_control_proof()
        .state_checksum;
    replicated
        .propose_create_multipart_upload_idempotent_with_route_report_linearizable_fenced(
            "mpu-complete-idem",
            "bucket",
            "large",
            "application/octet-stream",
            PutOptions::default(),
            10,
            "multipart-create-for-complete-idem",
            &route_checksum,
        )
        .unwrap();
    replicated
        .propose_upload_part_idempotent_with_route_report_linearizable_fenced(
            "mpu-complete-idem",
            1,
            b"complete-one".to_vec(),
            20,
            "multipart-part-for-complete-idem",
            &route_checksum,
        )
        .unwrap();
    let expected = b"complete-one".to_vec();
    let report = replicated
        .propose_complete_multipart_upload_idempotent_with_route_report_linearizable_fenced(
            "mpu-complete-idem",
            Some(expected.len() as u64),
            Some(etag(&expected)),
            Some(etag(&expected)),
            30,
            "multipart-complete-idem-a",
            &route_checksum,
        )
        .unwrap();
    assert_eq!(report.metadata.length, expected.len() as u64);
    assert_eq!(replicated.raft_commit_index(), 3);
    assert!(replicated
        .store()
        .multipart_upload("mpu-complete-idem")
        .is_err());
    let retry = replicated
        .propose_complete_multipart_upload_idempotent_with_route_report_linearizable_fenced(
            "mpu-complete-idem",
            Some(expected.len() as u64),
            Some(etag(&expected)),
            Some(etag(&expected)),
            30,
            "multipart-complete-idem-a",
            &route_checksum,
        )
        .unwrap();
    assert_eq!(retry.metadata, report.metadata);
    assert_eq!(replicated.raft_commit_index(), 3);
    assert!(matches!(
        replicated
            .propose_complete_multipart_upload_idempotent_with_route_report_linearizable_fenced(
                "mpu-complete-idem",
                Some(expected.len() as u64 + 1),
                Some(etag(&expected)),
                Some(etag(&expected)),
                31,
                "multipart-complete-idem-a",
                &route_checksum,
            ),
        Err(ObjectError::PreconditionFailed(_))
    ));

    let mut follower = MatrixObjectStore::new(test_options()).unwrap();
    replicated.replay_into(&mut follower).unwrap();
    assert_eq!(
        follower.get_object("bucket", "large").unwrap().data,
        expected
    );
    let receipt = follower
        .multipart_complete_receipts
        .get("multipart-complete-idem-a")
        .unwrap();
    assert_eq!(receipt.commit_index, 3);
    assert_eq!(receipt.metadata, report.metadata);
    let snapshot = follower.export_snapshot().unwrap();
    let restored = StoreSnapshot::from_bytes(&snapshot.to_bytes().unwrap()).unwrap();
    assert_eq!(
        restored
            .multipart_complete_receipts
            .get("multipart-complete-idem-a")
            .unwrap()
            .metadata,
        report.metadata
    );
}

