#[test]
fn raft_backed_store_trims_multipart_receipts_by_age() {
    let raft = InMemoryRustRaft::new(1).unwrap();
    let store = MatrixObjectStore::new(test_options()).unwrap();
    let mut replicated = RaftBackedObjectStore::new(raft, store);
    let route_checksum = replicated
        .store
        .chunk_service
        .route_control_proof()
        .state_checksum;

    for index in 0..2 {
        let upload_id = format!("mpu-complete-retain-{index}");
        let create_key = format!("multipart-retain-create-{index}");
        let part_key = format!("multipart-retain-part-{index}");
        let complete_key = format!("multipart-retain-complete-{index}");
        let payload = format!("payload-{index}").into_bytes();
        replicated
            .propose_create_multipart_upload_idempotent_with_route_report_linearizable_fenced(
                &upload_id,
                "bucket",
                &format!("complete-{index}"),
                "application/octet-stream",
                PutOptions::default(),
                10 + index as u64,
                &create_key,
                &route_checksum,
            )
            .unwrap();
        replicated
            .propose_upload_part_idempotent_with_route_report_linearizable_fenced(
                &upload_id,
                1,
                payload.clone(),
                20 + index as u64,
                &part_key,
                &route_checksum,
            )
            .unwrap();
        replicated
            .propose_complete_multipart_upload_idempotent_with_route_report_linearizable_fenced(
                &upload_id,
                Some(payload.len() as u64),
                Some(etag(&payload)),
                Some(etag(&payload)),
                30 + index as u64,
                &complete_key,
                &route_checksum,
            )
            .unwrap();
    }

    for index in 0..2 {
        let upload_id = format!("mpu-abort-retain-{index}");
        let create_key = format!("multipart-retain-abort-create-{index}");
        let part_key = format!("multipart-retain-abort-part-{index}");
        let abort_key = format!("multipart-retain-abort-{index}");
        replicated
            .propose_create_multipart_upload_idempotent_with_route_report_linearizable_fenced(
                &upload_id,
                "bucket",
                &format!("abort-{index}"),
                "application/octet-stream",
                PutOptions::default(),
                40 + index as u64,
                &create_key,
                &route_checksum,
            )
            .unwrap();
        replicated
            .propose_upload_part_idempotent_with_route_report_linearizable_fenced(
                &upload_id,
                1,
                format!("abort-payload-{index}").into_bytes(),
                50 + index as u64,
                &part_key,
                &route_checksum,
            )
            .unwrap();
        replicated
            .propose_abort_multipart_upload_idempotent_with_route_report_linearizable_fenced(
                &upload_id,
                60 + index as u64,
                &abort_key,
                &route_checksum,
            )
            .unwrap();
    }

    assert_eq!(replicated.store().multipart_complete_receipts.len(), 2);
    assert_eq!(replicated.store().multipart_abort_receipts.len(), 2);
    assert!(matches!(
        replicated.propose_trim_multipart_receipts_from_meta_shard(
            1,
            1,
            99,
            replicated.raft_commit_index(),
            0,
            "meta-multipart-retention",
            7,
        ),
        Err(ObjectError::PreconditionFailed(_))
    ));
    replicated
        .propose_register_meta_coordinator_session(
            "session-multipart-retention",
            "meta-multipart-retention",
            "127.0.0.1:9810",
            10_000,
            97,
        )
        .unwrap();
    replicated
        .propose_configure_meta_shard(MetadataShard {
            shard_id: "multipart-receipt-retention".to_string(),
            start_key: meta_object_key(&ObjectId::new("_multipartreceipts", "trim")),
            end_key: "object/_multipartreceipts/trin".to_string(),
            owner_node_id: "meta-multipart-retention".to_string(),
            epoch: 7,
            draining: false,
        })
        .unwrap();
    let trim = replicated
        .propose_trim_multipart_receipts_from_meta_shard(
            1,
            1,
            100,
            0,
            0,
            "meta-multipart-retention",
            7,
        )
        .unwrap();
    assert_eq!(trim.value.version, 1);
    assert_eq!(trim.value.length, 1);
    assert_eq!(trim.proof.read_fence_read_index_lag, 0);
    assert_eq!(trim.proof.read_fence_applied_lag, 0);
    assert!(!replicated
        .store()
        .multipart_complete_receipts
        .contains_key("multipart-retain-complete-0"));
    assert!(replicated
        .store()
        .multipart_complete_receipts
        .contains_key("multipart-retain-complete-1"));
    assert!(!replicated
        .store()
        .multipart_abort_receipts
        .contains_key("multipart-retain-abort-0"));
    assert!(replicated
        .store()
        .multipart_abort_receipts
        .contains_key("multipart-retain-abort-1"));

    let mut follower = MatrixObjectStore::new(test_options()).unwrap();
    replicated.replay_into(&mut follower).unwrap();
    assert_eq!(follower.multipart_complete_receipts.len(), 1);
    assert_eq!(follower.multipart_abort_receipts.len(), 1);
    let restored =
        StoreSnapshot::from_bytes(&follower.export_snapshot().unwrap().to_bytes().unwrap()).unwrap();
    assert_eq!(restored.multipart_complete_receipts.len(), 1);
    assert_eq!(restored.multipart_abort_receipts.len(), 1);
    assert!(restored
        .multipart_complete_receipts
        .contains_key("multipart-retain-complete-1"));
    assert!(restored
        .multipart_abort_receipts
        .contains_key("multipart-retain-abort-1"));
}

#[test]
fn raft_backed_store_replays_multipart_commands() {
    let raft = InMemoryRustRaft::new(1).unwrap();
    let store = MatrixObjectStore::new(test_options()).unwrap();
    let mut replicated = RaftBackedObjectStore::new(raft, store);
    let route_checksum = replicated
        .store
        .chunk_service
        .route_control_proof()
        .state_checksum;
    assert!(matches!(
        replicated.propose_create_multipart_upload_with_route_report_linearizable_fenced(
            "mpu-stale",
            "bucket",
            "stale",
            "application/octet-stream",
            PutOptions::default(),
            1,
            "stale-block-route-control",
        ),
        Err(ObjectError::PreconditionFailed(_))
    ));
    let create_report = replicated
        .propose_create_multipart_upload_with_route_report_linearizable_fenced(
            "mpu-100",
            "bucket",
            "large",
            "application/octet-stream",
            PutOptions::default(),
            1,
            &route_checksum,
        )
        .unwrap();
    assert_eq!(create_report.upload.upload_id, "mpu-100");
    assert_eq!(
        create_report.expected_route_control_checksum,
        route_checksum
    );
    assert_eq!(
        create_report.route_control_proof.state_checksum,
        create_report.expected_route_control_checksum
    );
    assert!(matches!(
        replicated.propose_upload_part_with_route_report_linearizable_fenced(
            "mpu-100",
            1,
            vec![b'x'; 33],
            2,
            "stale-block-route-control",
        ),
        Err(ObjectError::PreconditionFailed(_))
    ));
    let part_one = replicated
        .propose_upload_part_with_route_report("mpu-100", 1, vec![b'x'; 33], 2)
        .unwrap();
    assert_eq!(part_one.part.length, 33);
    assert_eq!(part_one.received_bytes, 33);
    assert_eq!(
        part_one.route_control_proof.state_checksum,
        part_one.expected_route_control_checksum
    );
    let part_two = replicated
        .propose_upload_part_with_route_report("mpu-100", 2, vec![b'y'; 31], 3)
        .unwrap();
    assert_eq!(part_two.received_bytes, 64);
    let expected = [vec![b'x'; 33], vec![b'y'; 31]].concat();
    assert!(matches!(
        replicated.propose_complete_multipart_upload_with_route_report_linearizable_fenced(
            "mpu-100",
            Some(64),
            Some(etag(&expected)),
            4,
            "stale-block-route-control",
        ),
        Err(ObjectError::PreconditionFailed(_))
    ));
    let complete_report = replicated
        .propose_complete_multipart_upload_with_route_report(
            "mpu-100",
            Some(64),
            Some(etag(&expected)),
            4,
        )
        .unwrap();
    assert_eq!(complete_report.metadata.length, 64);
    assert_eq!(
        complete_report.route_control_proof.state_checksum,
        complete_report.expected_route_control_checksum
    );
    assert_eq!(replicated.raft_commit_index(), 4);

    let mut follower = MatrixObjectStore::new(test_options()).unwrap();
    replicated.replay_into(&mut follower).unwrap();
    assert_eq!(
        follower.get_object("bucket", "large").unwrap().data,
        expected
    );
    assert!(follower.multipart_upload("mpu-100").is_err());
    assert_eq!(follower.last_applied_index(), 4);

    replicated
        .propose_create_multipart_upload(
            "mpu-abort",
            "bucket",
            "aborted",
            "application/octet-stream",
            PutOptions::default(),
            5,
        )
        .unwrap();
    replicated
        .propose_upload_part("mpu-abort", 1, vec![b'z'; 7], 6)
        .unwrap();
    assert!(matches!(
        replicated.propose_abort_multipart_upload_with_route_report_linearizable_fenced(
            "mpu-abort",
            7,
            "stale-block-route-control",
        ),
        Err(ObjectError::PreconditionFailed(_))
    ));
    let abort_report = replicated
        .propose_abort_multipart_upload_with_route_report("mpu-abort", 7)
        .unwrap();
    assert_eq!(abort_report.upload.total_bytes, 7);
    assert_eq!(
        abort_report.route_control_proof.state_checksum,
        abort_report.expected_route_control_checksum
    );
    replicated.replay_into(&mut follower).unwrap();
    assert!(follower.multipart_upload("mpu-abort").is_err());
    assert!(follower.get_object("bucket", "aborted").is_err());
    assert_eq!(follower.last_applied_index(), 7);
}

