#[test]
fn raft_backed_store_replays_placement_leader_lease() {
    let raft = InMemoryRustRaft::new(1).unwrap();
    let store = MatrixObjectStore::new(test_options()).unwrap();
    let mut replicated = RaftBackedObjectStore::new(raft, store);
    let root_a = PlacementNode {
        node_id: "root-a".to_string(),
        endpoint: "root-a.local:9100".to_string(),
        service_kind: "metaserver".to_string(),
        failure_domain: "rack-a".to_string(),
        metadata_eligible: false,
        data_eligible: false,
        gateway_eligible: false,
        serves_page_tier: false,
        metadata_value_bytes: 0,
        capacity_bytes: 1,
        used_bytes: 0,
        committed_bytes: 0,
        draining: false,
        online: true,
        last_heartbeat_ms: 1,
        page_allocator_shard_index: 0,
        page_allocator_shard_count: 1,
        meta_health: NodeMetaHealth::default(),
        page_health: NodePageHealth::default(),
        chunk_health: NodeChunkHealth::default(),
    };
    replicated.propose_register_placement_node(root_a).unwrap();
    let campaign = replicated
        .propose_campaign_placement_leader("root-a", 100, 10)
        .unwrap();
    assert_eq!(campaign.content_type, "rootserver/leader-campaign");
    assert_eq!(campaign.version, 1);
    replicated
        .propose_renew_placement_leader("root-a", 1, 120, 50)
        .unwrap();
    let campaign_retry = replicated
        .propose_campaign_placement_leader_idempotent("root-a", 120, 171, "raft-root-campaign-a")
        .unwrap();
    assert_eq!(
        campaign_retry.content_type,
        "rootserver/leader-campaign-idempotent"
    );
    let campaign_retry_again = replicated
        .propose_campaign_placement_leader_idempotent("root-a", 120, 171, "raft-root-campaign-a")
        .unwrap();
    assert_eq!(campaign_retry_again.version, campaign_retry.version);
    let renew_retry = replicated
        .propose_renew_placement_leader_idempotent("root-a", 2, 140, 180, "raft-root-renew-a")
        .unwrap();
    assert_eq!(
        renew_retry.content_type,
        "rootserver/leader-renew-idempotent"
    );
    replicated
        .propose_renew_placement_leader_idempotent("root-a", 2, 140, 180, "raft-root-renew-a")
        .unwrap();
    assert_eq!(replicated.raft_commit_index(), 7);

    let mut follower = MatrixObjectStore::new(test_options()).unwrap();
    replicated.replay_into(&mut follower).unwrap();
    let lease = follower.root_leader_lease().unwrap();
    assert_eq!(lease.leader_node_id, "root-a");
    assert_eq!(lease.epoch, 2);
    assert_eq!(lease.expire_time_ms, 320);
    assert_eq!(follower.last_applied_index(), 7);
}

#[test]
fn raft_backed_store_replays_placement_commands() {
    let raft = InMemoryRustRaft::new(1).unwrap();
    let store = MatrixObjectStore::new(test_options()).unwrap();
    let mut replicated = RaftBackedObjectStore::new(raft, store);
    replicated
        .propose_register_placement_node(placement_node("chunk-a", "rack-a", 64))
        .unwrap();
    replicated
        .propose_register_placement_node(placement_node("chunk-b", "rack-b", 64))
        .unwrap();
    replicated
        .propose_register_placement_node(placement_node("chunk-c", "rack-c", 64))
        .unwrap();
    let metadata = replicated
        .propose_put_with_placement(
            "bucket",
            "object",
            b"raft-root".to_vec(),
            "text/plain",
            2,
            PutOptions::default(),
            10,
        )
        .unwrap();
    assert_eq!(metadata.length, 9);
    assert_eq!(replicated.raft_commit_index(), 4);
    assert_eq!(
        replicated
            .store()
            .object_placement("bucket", "object")
            .unwrap()
            .node_ids
            .len(),
        2
    );

    let mut follower = MatrixObjectStore::new(test_options()).unwrap();
    replicated.replay_into(&mut follower).unwrap();
    assert_eq!(
        follower.get_object("bucket", "object").unwrap().data,
        b"raft-root".to_vec()
    );
    assert_eq!(
        follower
            .object_placement("bucket", "object")
            .unwrap()
            .length,
        9
    );
    assert!(follower.placement_nodes().iter().all(|node| {
        if node.node_id == "chunk-a" || node.node_id == "chunk-b" {
            node.committed_bytes == 9
        } else {
            true
        }
    }));

    let plan = replicated
        .store()
        .plan_object_placement_migration("bucket", "object", "chunk-a", "chunk-c")
        .unwrap();
    let committed_migration = replicated
        .propose_placement_migration_prepared_with_envelope_linearizable(
            plan.clone(),
            plan.plan_checksum.clone(),
        )
        .unwrap();
    assert_eq!(
        committed_migration.envelope.envelope_format,
        "MOSRSROOT-PLACEMENT-MIGRATION-COMMIT-ENVELOPE1"
    );
    assert_eq!(committed_migration.envelope.object_id, plan.object_id);
    assert_eq!(
        committed_migration.envelope.after_node_ids,
        plan.after_node_ids
    );
    assert_eq!(
        committed_migration.envelope.committed_raft_index,
        replicated.raft_commit_index()
    );
    assert!(!committed_migration.envelope.envelope_checksum.is_empty());
    replicated.replay_into(&mut follower).unwrap();
    assert_eq!(
        follower
            .object_placement("bucket", "object")
            .unwrap()
            .node_ids,
        plan.after_node_ids
    );
    assert_eq!(
        follower
            .placement_nodes()
            .iter()
            .find(|node| node.node_id == "chunk-a")
            .unwrap()
            .committed_bytes,
        0
    );
    assert_eq!(
        follower
            .placement_nodes()
            .iter()
            .find(|node| node.node_id == "chunk-c")
            .unwrap()
            .committed_bytes,
        9
    );

    replicated
        .propose_delete_with_placement_release("bucket", "object", None, 11)
        .unwrap();
    replicated.replay_into(&mut follower).unwrap();
    assert!(follower.object_placement("bucket", "object").is_err());
    assert!(follower
        .placement_nodes()
        .iter()
        .all(|node| node.committed_bytes == 0));
}

#[test]
fn raft_backed_store_gates_prepared_placement_actions() {
    let raft = InMemoryRustRaft::new(1).unwrap();
    let store = MatrixObjectStore::new(test_options()).unwrap();
    let mut replicated = RaftBackedObjectStore::new(raft, store);
    for (node_id, domain, capacity) in [("chunk-a", "rack-a", 64), ("chunk-b", "rack-b", 64)] {
        replicated
            .propose_register_placement_node(placement_node(node_id, domain, capacity))
            .unwrap();
    }
    replicated
        .propose_put_with_placement(
            "bucket",
            "prepared-root",
            vec![b'p'; 32],
            "text/plain",
            2,
            PutOptions::default(),
            10,
        )
        .unwrap();
    replicated
        .propose_register_placement_node(placement_node("chunk-c", "rack-c", 128))
        .unwrap();

    let stale = RaftBackedObjectStore::new(
        replicated.raft.clone(),
        MatrixObjectStore::new(test_options()).unwrap(),
    );
    assert!(matches!(
        stale.prepare_placement_capacity_rebalance_raft_entry_linearizable(1, 40),
        Err(ObjectError::PreconditionFailed(_))
    ));

    let capacity_prepared = replicated
        .prepare_placement_capacity_rebalance_raft_entry_linearizable(1, 40)
        .unwrap();
    assert_eq!(capacity_prepared.report.rebalance_objects, 1);
    let capacity_receipt = replicated
        .propose_prepared_placement_capacity_rebalance_linearizable(capacity_prepared)
        .unwrap();
    assert_eq!(
        capacity_receipt.content_type,
        "root/prepared-placement-capacity-rebalance"
    );
    assert_eq!(capacity_receipt.version, 1);
    assert_eq!(capacity_receipt.length, 1);
    assert_eq!(capacity_receipt.update_time_ms, 32);

    let placement = replicated
        .object_placement_linearizable("bucket", "prepared-root")
        .unwrap();
    let source_node = placement.node_ids[0].clone();
    let target_node = ["chunk-a", "chunk-b", "chunk-c"]
        .into_iter()
        .find(|node| !placement.node_ids.iter().any(|current| current == node))
        .unwrap();
    let plan = replicated
        .store()
        .plan_object_placement_migration("bucket", "prepared-root", &source_node, target_node)
        .unwrap();
    let prepared = replicated
        .prepare_placement_migration_raft_entry_linearizable(plan.clone(), &plan.plan_checksum)
        .unwrap();
    assert_eq!(prepared.placement_read_index, replicated.raft_commit_index());
    assert_eq!(prepared.placement_raft_term, replicated.raft.term());
    assert!(!prepared.root_read_proof_checksum.is_empty());
    let migration_envelope = replicated
        .prepare_placement_migration_envelope_with_read_proof_linearizable(
            plan.clone(),
            &plan.plan_checksum,
        )
        .unwrap();
    assert_eq!(
        migration_envelope.envelope.envelope_format,
        "MOSRSROOT-PLACEMENT-MIGRATION-ENVELOPE1"
    );
    assert_eq!(migration_envelope.envelope.object_id, plan.object_id);
    assert_eq!(
        migration_envelope.envelope.raft_entry_checksum,
        prepared.raft_entry_checksum
    );
    assert_eq!(
        migration_envelope.envelope.root_read_proof_checksum,
        migration_envelope.proof.proof_checksum
    );
    assert!(migration_envelope.envelope.envelope_bytes > 0);
    assert!(!migration_envelope.envelope.envelope_checksum.is_empty());
    let mut corrupted_proof = prepared.clone();
    corrupted_proof.root_read_proof_checksum = "bad-root-read-proof".to_string();
    assert!(matches!(
        replicated.propose_prepared_placement_migration_linearizable(corrupted_proof),
        Err(ObjectError::PreconditionFailed(_))
    ));
    let migration = replicated
        .propose_prepared_placement_migration_with_envelope_linearizable(prepared)
        .unwrap();
    assert_eq!(
        migration.metadata.content_type,
        "root/prepared-placement-migration"
    );
    assert_eq!(migration.metadata.length, 32);
    assert_eq!(
        migration.envelope.envelope_format,
        "MOSRSROOT-PLACEMENT-MIGRATION-COMMIT-ENVELOPE1"
    );
    assert_eq!(migration.envelope.object_id, plan.object_id);
    assert_eq!(migration.envelope.after_node_ids, plan.after_node_ids);
    assert_eq!(
        migration.envelope.committed_raft_index,
        replicated.raft_commit_index()
    );
    assert_eq!(migration.envelope.metadata_etag, *migration.metadata.etag());
    assert!(migration.envelope.envelope_bytes > 0);
    assert!(!migration.envelope.envelope_checksum.is_empty());

    let mut follower = MatrixObjectStore::new(test_options()).unwrap();
    replicated.replay_into(&mut follower).unwrap();
    assert_eq!(
        follower.last_applied_index(),
        replicated.raft_commit_index()
    );
    assert_eq!(
        follower.get_object("bucket", "prepared-root").unwrap().data,
        vec![b'p'; 32]
    );
    assert_eq!(
        follower
            .object_placement("bucket", "prepared-root")
            .unwrap()
            .node_ids,
        plan.after_node_ids
    );
}

#[test]
fn raft_backed_store_replays_batch_delete_with_placement_release() {
    let raft = InMemoryRustRaft::new(1).unwrap();
    let store = MatrixObjectStore::new(test_options()).unwrap();
    let mut replicated = RaftBackedObjectStore::new(raft, store);
    for (node_id, domain) in [
        ("chunk-a", "rack-a"),
        ("chunk-b", "rack-b"),
        ("chunk-c", "rack-c"),
    ] {
        replicated
            .propose_register_placement_node(placement_node(node_id, domain, 128))
            .unwrap();
    }
    let first = replicated
        .propose_put_with_placement(
            "bucket",
            "delete-a",
            b"first".to_vec(),
            "text/plain",
            2,
            PutOptions::default(),
            10,
        )
        .unwrap();
    replicated
        .propose_put_with_placement(
            "bucket",
            "delete-b",
            b"second".to_vec(),
            "text/plain",
            2,
            PutOptions::default(),
            11,
        )
        .unwrap();
    let receipt = replicated
        .propose_batch_delete_objects(
            vec![
                ObjectDeleteRequest {
                    bucket: "bucket".to_string(),
                    key: "delete-a".to_string(),
                    if_match_etag: Some(first.etag().to_string()),
                    version: None,
                },
                ObjectDeleteRequest {
                    bucket: "bucket".to_string(),
                    key: "delete-b".to_string(),
                    if_match_etag: Some("wrong-etag".to_string()),
                    version: None,
                },
                ObjectDeleteRequest {
                    bucket: "bucket".to_string(),
                    key: "missing".to_string(),
                    if_match_etag: None,
                    version: None,
                },
            ],
            8,
            true,
            12,
        )
        .unwrap();
    assert_eq!(receipt.content_type, "objectstore/batch-delete");
    assert_eq!(receipt.version, 1);
    assert_eq!(receipt.length, 2);
    assert_eq!(receipt.update_time_ms, 5);
    assert_eq!(replicated.raft_commit_index(), 6);

    let mut follower = MatrixObjectStore::new(test_options()).unwrap();
    replicated.replay_into(&mut follower).unwrap();
    assert!(matches!(
        follower.get_object("bucket", "delete-a"),
        Err(ObjectError::NotFound(_))
    ));
    assert_eq!(
        follower.get_object("bucket", "delete-b").unwrap().data,
        b"second".to_vec()
    );
    assert!(follower.object_placement("bucket", "delete-a").is_err());
    assert_eq!(
        follower
            .placement_nodes()
            .iter()
            .map(|node| node.committed_bytes)
            .sum::<u64>(),
        12
    );
    assert_eq!(follower.last_applied_index(), 6);
}

#[test]
fn raft_backed_store_replays_batch_put() {
    let raft = InMemoryRustRaft::new(1).unwrap();
    let store = MatrixObjectStore::new(test_options()).unwrap();
    let mut replicated = RaftBackedObjectStore::new(raft, store);
    let route_checksum = replicated
        .store
        .chunk_service
        .route_control_proof()
        .state_checksum;
    let local_report = replicated
        .store
        .batch_put_objects_fenced(
            vec![ObjectPutRequest {
                bucket: "local".to_string(),
                key: "proof".to_string(),
                data: b"route-proof".to_vec(),
                content_type: "text/plain".to_string(),
                options: PutOptions::default(),
            }],
            4,
            64,
            21,
            Some(&route_checksum),
        )
        .unwrap();
    assert_eq!(local_report.put_objects, 1);
    assert_eq!(local_report.expected_route_control_checksum, route_checksum);
    assert_eq!(
        local_report.route_control_proof.state_checksum,
        local_report.expected_route_control_checksum
    );
    assert!(matches!(
        replicated.store.batch_put_objects_fenced(
            Vec::new(),
            4,
            64,
            22,
            Some("stale-route-checksum"),
        ),
        Err(ObjectError::PreconditionFailed(_))
    ));
    let receipt = replicated
        .propose_batch_put_objects(
            vec![
                ObjectPutRequest {
                    bucket: "bucket".to_string(),
                    key: "batch-a".to_string(),
                    data: b"alpha".to_vec(),
                    content_type: "text/plain".to_string(),
                    options: PutOptions::default(),
                },
                ObjectPutRequest {
                    bucket: "bucket".to_string(),
                    key: String::new(),
                    data: b"bravo".to_vec(),
                    content_type: "text/plain".to_string(),
                    options: PutOptions::default(),
                },
                ObjectPutRequest {
                    bucket: "bucket".to_string(),
                    key: "batch-c".to_string(),
                    data: b"charlie".to_vec(),
                    content_type: "application/octet-stream".to_string(),
                    options: PutOptions::default(),
                },
            ],
            8,
            64,
            42,
        )
        .unwrap();
    assert_eq!(receipt.content_type, "objectstore/batch-put");
    assert_eq!(receipt.version, 2);
    assert_eq!(receipt.length, 1);
    assert_eq!(receipt.update_time_ms, 17);
    assert_eq!(replicated.raft_commit_index(), 1);

    let mut follower = MatrixObjectStore::new(test_options()).unwrap();
    replicated.replay_into(&mut follower).unwrap();
    let batch_a = follower.get_object("bucket", "batch-a").unwrap();
    assert_eq!(batch_a.data, b"alpha".to_vec());
    assert_eq!(batch_a.metadata.update_time_ms, 42);
    assert_eq!(batch_a.metadata.version, 1);
    assert!(matches!(
        follower.get_object("bucket", "batch-b"),
        Err(ObjectError::NotFound(_))
    ));
    assert_eq!(
        follower.get_object("bucket", "batch-c").unwrap().data,
        b"charlie".to_vec()
    );
    assert_eq!(follower.last_applied_index(), 1);
}

